INSERT INTO documents VALUES (1, 'TSRI-F01-01-001', 'TSRI-DOC-0001', 'TSRI-N001', 1, 'หมวดที่ 1', '1. พ.ร.บ. สภานโยบายการอุดมศึกษาฯ พ.ศ. 2562.pdf', 'พระราชบัญญัติสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ พ.ศ. 2562', 'ระดับที่ 1: กฎหมายแม่บทและกฎหมายจัดตั้ง (4.1.1.1)', 'A1, A2, A3, A4, A5, B1, B2, B3, B4', 'สำนัก F1 / F2 / F3', 'กฎหมายแม่บทและกฎหมายจัดตั้งระดับที่ 1 (TOR ข้อ 4.1.1.1) — 80 มาตรา กำหนดโครงสร้าง 4 เสาหลักของระบบ ววน. และจัดตั้ง สกสว. (มาตรา 41–63)', 'กำหนดโครงสร้างอำนาจ 4 เสาหลัก: 1) สภานโยบายฯ (ม.11–12) 2) กสว. (ม.44 กำหนดนโยบาย แผน และกรอบงบกองทุน ววน.) 3) อนก.สกสว. (ม.47 อนุโลม ม.25–27 บริหารงานบุคคล งบสำนักงาน และออกข้อบังคับภายใน) 4) ผู้อำนวยการ สกสว. (ม.50 อนุโลม ม.29–36), แยกเงินสำนักงาน (ม.45) ออกจากเงินกองทุน ววน. (ม.54–61), ห้ามทำวิจัยแข่งขันกับหน่วยรับงบ (ม.43 วรรคสอง) และบทเฉพาะกาลรับโอน สกว. (ม.66–80) | ราชกิจจานุเบกษา เล่ม 136 ตอนที่ 57 ก (1 พ.ค. 2562)', 34, 'f7e1d33a7b6abde1...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1AxO3BpjDioPI1cU98_Q6Bi7heSTEPpW1/view?usp=drivesdk');
INSERT INTO documents VALUES (2, 'TSRI-F01-01-002', 'TSRI-DOC-0002', 'TSRI-N002', 1, 'หมวดที่ 1', '2. พ.ร.บ. สภานโยบายการอุดมศึกษาฯ (ฉ.2) พ.ศ. 2568.pdf', 'พระราชบัญญัติสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ (ฉบับที่ 2) พ.ศ. 2568', 'ระดับที่ 1: กฎหมายแม่บทและกฎหมายจัดตั้ง (4.1.1.1)', 'A2', 'สำนัก F1 / F2 / F3', 'กฎหมายแม่บทและกฎหมายจัดตั้งระดับที่ 1 (TOR ข้อ 4.1.1.1) — 3 มาตรา แก้ไขเพิ่มเติมมาตรา 12(1) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562', 'ปรับปรุงองค์ประกอบและกลไกการเสนอแนะนโยบาย ยุทธศาสตร์ แผน และกรอบวงเงินงบประมาณประจำปีด้านการอุดมศึกษาและด้าน ววน. ของสภานโยบายฯ ต่อคณะรัฐมนตรีและสำนักงบประมาณ ให้สอดคล้องกับวงจรการจัดทำงบประมาณรายจ่ายประจำปีตาม พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (เชื่อมโยง SOP จัดสรรงบ DOC-0101) | ราชกิจจานุเบกษา เล่ม 142 ตอนที่ 14 ก (24 มี.ค. 2568)', 3, '640c286a46ced71a...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/10fth47Z8W_CTIm7AzqcD-aUmzKeXl7Fq/view?usp=drivesdk');
INSERT INTO documents VALUES (3, 'TSRI-F01-02-001', 'TSRI-DOC-0003', 'TSRI-N003', 1, 'หมวดที่ 1', 'บริหารกองทุนส่งเสริม ววน.pdf', 'ระเบียบสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ ว่าด้วยการบริหารกองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม พ.ศ. 2562', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A3', 'F3 ร่วมกับ F2 และ F5', 'พ.ร.บ.สภานโยบายฯ ม.11(9) ประกอบ ม.41(6) [และเชื่อม ม.54–63] | เชื่อมโยง: เป็นระเบียบแม่บทสูงสุดของกองทุน ววน. (ข้อ 10 และข้อ 11 เป็นฐานให้ออกประกาศ กสว. ในโฟลเดอร์ที่ 4)', 'กำหนดองค์ประกอบเงินกองทุน 7 ด้าน (ข้อ 5), ให้ สกสว. รับผิดชอบดำเนินกิจการกองทุน (ข้อ 6), การนำเงินกองทุนไปหาผลประโยชน์ 5 วิธี (ข้อ 10), รายจ่ายกองทุน 6 ประเภท และเพดานงบบริหารกองทุนให้ สกสว. ไม่เกินร้อยละ 5 ของเงินอุดหนุนรายปี (ข้อ 11 วรรคสอง), การจัดทำงบการเงินส่ง สตง. ภายใน 90/180 วัน (ข้อ 18–20) | วันประกาศ/มติ: มติสภานโยบาย ครั้งที่ 3/2562 (27 พ.ย. 2562) (22 ข้อ) | เชื่อมคู่มือ/SOP: SOP 0101, คู่มือระเบียบการเงิน พ.ศ. 2568 และคู่มือ FF | กฎหมายระดับที่ 3: พ.ร.บ.วินัยการเงินการคลังของรัฐ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0103), มาตรฐานการบัญชีภาครัฐ', 6, '1b33a304b8dc82a3...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1xf7MjRx70fXe1XP-WipdV50b1Y-YndsV/view?usp=drivesdk');
INSERT INTO documents VALUES (4, 'TSRI-F01-03-001', 'TSRI-DOC-0004', 'TSRI-N004', 1, 'หมวดที่ 1', '1. การเร่งรัดและติดตามให้มีการชดใช้ทุนคืน.pdf', 'ระเบียบคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการเร่งรัดและติดตามให้มีการชดใช้ทุนคืนตามสัญญาสำหรับโครงการวิจัยและกิจกรรมที่เกี่ยวเนื่องซึ่งได้รับโอนมาจากกองทุนสนับสนุนการวิจัย พ.ศ. 2564', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A3', 'F3 ร่วมกับ F5 (กลุ่มงาน 5.1 นิติการ และงานการเงิน) และ วช.', 'พ.ร.บ.สภานโยบายฯ ม.41(9) และ (16) ประกอบ ม.71 [และปลั๊กอิน พ.ร.บ.ส่งเสริมฯ ม.37] | เชื่อมโยง: ออกตามบทเฉพาะกาล ม.71 (รับโอนภารกิจและหนี้จาก สกว.)', 'ใช้บังคับแก่โครงการวิจัยที่ผิดสัญญาที่รับโอนจาก สกว. ทั้งในความรับผิดชอบของ สกสว. และ วช. (ข้อ 4); กรณีเหลือเวลา <6 เดือนก่อนขาดอายุความให้เตือน/บอกเลิกสัญญาและฟ้องคดีทันที (ข้อ 6); กรณีปกติให้เตือนภายใน 30 วัน และบอกเลิกสัญญา/เรียกชดใช้ภายใน 15 วัน (ข้อ 7); คำนวณสัดส่วนผลงาน 5 ส่วน (10/20/20/40/10%) และลดหย่อนแบบขั้นบันได (ข้อ 10–11) | วันประกาศ/มติ: มติ กสว. 27 ส.ค. 2564 | ราชกิจจาฯ เล่ม 138 ตอนพิเศษ 280 ง (15 พ.ย. 2564) (16 ข้อ) | เชื่อมคู่มือ/SOP: คู่มือระเบียบการเงิน พ.ศ. 2568 ข้อ 2.3 (คำสั่งมอบอำนาจโครงการ Ongoing ตามบทเฉพาะกาล) | กฎหมายระดับที่ 3: ประมวลกฎหมายแพ่งและพาณิชย์ (อายุความสัญญาค้ำประกัน), ระเบียบสำนักนายกรัฐมนตรีว่าด้วยการพิจารณาชี้ขาดการยุติข้อพิพาทระหว่างหน่วยงานของรัฐฯ พ.ศ. 2561', 5, '2c86c60ab3e0a151...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1IZEMWO64c-51OhAlbVa1G54ooCrO5Zee/view?usp=drivesdk');
INSERT INTO documents VALUES (5, 'TSRI-F01-03-002', 'TSRI-DOC-0005', 'TSRI-N005', 1, 'หมวดที่ 1', '2. การรับเงิน จ่ายเงิน และเก็บรักษาเงิน.pdf', 'ระเบียบคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการรับเงิน การจ่ายเงิน และการเก็บรักษาเงินกองทุน พ.ศ. 2562', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B3', 'F5 (งานการเงิน) ร่วมกับ F2 และ F3', 'พ.ร.บ.สภานโยบายฯ ม.41(16) ประกอบ ม.57 และ ม.59 (ได้รับความเห็นชอบจากสภานโยบาย) | เชื่อมโยง: คู่ขนานกับระเบียบสภานโยบายฯ ว่าด้วยการบริหารกองทุน ววน. พ.ศ. 2562 ข้อ 7–9', 'กำหนดวิธีออกใบเสร็จรับเงิน การนำเงินส่งเข้าบัญชีชื่อ ''กองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม'' ในวันที่รับเงินหรือวันทำการถัดไป (ข้อ 9–10); การอนุมัติจ่ายเงินกองทุนเป็นอำนาจของ ผอ.สกสว. หรือผู้ที่ ผอ. มอบหมายโดยความเห็นชอบของ อนก.สกสว. (ข้อ 12); การเก็บรักษาเงินและตู้นิรภัย | วันประกาศ/มติ: มติ กสว. ครั้งที่ 7/2562 (25 ต.ค. 2562) และมติสภานโยบาย ครั้งที่ 3/2562 (27 พ.ย. 2562) (32 ข้อ) | เชื่อมคู่มือ/SOP: คู่มือระเบียบการเงิน พ.ศ. 2568 (TSRI-DOC-0098 ข้อ 2.1 คำสั่งมอบอำนาจอนุมัติจ่ายเงินกองทุน) แยกจากระเบียบ อนก. รับ-จ่ายเงินสำนักงาน พ.ศ. 2563 | กฎหมายระดับที่ 3: พ.ร.บ.วินัยการเงินการคลังของรัฐ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0103) และมาตรฐานการบัญชีภาครัฐ', 7, '3b0dea17b35f6608...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1YwGA8HbSnKeTe3tGXGHsTiYJ_eGG2MU_/view?usp=drivesdk');
INSERT INTO documents VALUES (6, 'TSRI-F01-04-001', 'TSRI-DOC-0006', 'TSRI-N006', 1, 'หมวดที่ 1', '1.1 รายชื่อหน่วยงานที่ยื่นคำของบประมาณ.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง รายชื่อหน่วยงานที่อาจยื่นคำของบประมาณจากกองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม พ.ศ. 2566', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 ร่วมกับ F1 และ F5', 'พ.ร.บ.สภานโยบายฯ ม.41(4) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) [และเชื่อม ม.7] | เชื่อมโยง: เชื่อมกับประกาศสภานโยบายฯ เรื่อง การจัดประเภทหน่วยงานในระบบ ววน. พ.ศ. 2564 (หมวด 2)', 'กำหนดหน่วยงานที่มีสิทธิยื่นคำของบประมาณ 4 กลุ่ม (ข้อ 4): (1) PMU 7 แห่ง (วช., สวรส., สนช., สวก., บพท./บพค./บพข. ใน สอวช., สวช., ศลช.) (2) หน่วยงานอื่นของรัฐ (ม.รัฐ, กรม, รัฐวิสาหกิจ, องค์การมหาชน, ทุนหมุนเวียน, อปท., รัฐสภา/ศาล/องค์กรอิสระ/อัยการ) (3) ม.เอกชนที่มีประสบการณ์วิจัย >=3 ปี (4) นิติบุคคลไม่แสวงหากำไรที่มีประสบการณ์วิจัย >=3 ปีตามบัญชีแนบท้าย; และข้อ 5 เปิดให้ PMU, สป.อว., สอวช. และ ''สกสว.'' ยื่นของบ Strategic Fund (SF) ได้ | วันประกาศ/มติ: มติ กสว. ครั้งที่ 7/2566 (21 ก.ค. 2566) | ประกาศ ณ วันที่ 18 ส.ค. 2566 (7 ข้อ) | เชื่อมคู่มือ/SOP: SOP 0101 (ขั้นตอนเปิดรับคำขอผ่านระบบ NRIIS / STARS) และคู่มือบริหารโครงการ ORG (เชื่อมข้อ 5 กรณี สกสว. ขอ SF เพื่อพัฒนางาน) | กฎหมายระดับที่ 3: พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102)', 3, '72a68a11db35dae9...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1a2a-seocORoUCUEaLx79XRfQyCDm1UpT/view?usp=drivesdk');
INSERT INTO documents VALUES (7, 'TSRI-F01-04-002', 'TSRI-DOC-0007', 'TSRI-N007', 1, 'หมวดที่ 1', '1.2 รายชื่อหน่วยงานที่ยื่นคำของบประมาณ (ฉบับที่ 2).pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง รายชื่อหน่วยงานที่อาจยื่นคำของบประมาณจากกองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม (ฉบับที่ 2) พ.ศ. 2568', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 ร่วมกับ F1', 'พ.ร.บ.สภานโยบายฯ ม.41(4) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) | เชื่อมโยง: แก้ไขเพิ่มเติมประกาศ 1.1 พ.ศ. 2566 เพื่อให้สอดคล้องกับประกาศสภานโยบายฯ จัดประเภทหน่วยงาน (ฉบับที่ 4) พ.ศ. 2568', 'เพิ่ม (ซ) ในข้อ 4(1) ของประกาศปี 2566 โดยกำหนดให้ ''กรมวิทยาศาสตร์และเทคโนโลยีกลาโหม สำนักงานปลัดกระทรวงกลาโหม (วท.กห.)'' เป็นหน่วยงานบริหารและจัดการทุน (PMU) ที่มีสิทธิยื่นคำของบประมาณจากกองทุน ววน. | วันประกาศ/มติ: มติ กสว. ครั้งที่ 74 (11/2568) เมื่อ 13 พ.ย. 2568 | ประกาศ ณ วันที่ 13 พ.ย. 2568 (3 ข้อ) | เชื่อมคู่มือ/SOP: SOP 0101 และระบบ NRIIS | กฎหมายระดับที่ 3: พ.ร.บ.จัดระเบียบราชการกระทรวงกลาโหม พ.ศ. 2551 และ พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102)', 1, '949b03a652aba186...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1P2JBLSFOB3Pof2w9owUvTu48UiYkONgo/view?usp=drivesdk');
INSERT INTO documents VALUES (8, 'TSRI-F01-04-003', 'TSRI-DOC-0008', 'TSRI-N008', 1, 'หมวดที่ 1', '2.1 การจัดทำคำขอ วิจัยนวัตกรรม.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณและการจัดสรรงบประมาณด้านการวิจัยและนวัตกรรมของหน่วยงานในระบบวิจัยและนวัตกรรม พ.ศ. 2566', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 ร่วมกับ F1', 'พ.ร.บ.สภานโยบายฯ ม.41(4) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) | เชื่อมโยง: ออกตามข้อ 11 แห่งระเบียบสภานโยบายฯ ว่าด้วยการบริหารกองทุนส่งเสริม ววน. พ.ศ. 2562 (ยกเลิกประกาศปี 2565)', 'เป็นประกาศหลักในการจัดทำคำของบประมาณและการจัดสรรงบประมาณด้านการวิจัยและนวัตกรรม แบ่งเป็นงบ Fundamental Fund (FF) สำหรับหน่วยรับงบประมาณตามพันธกิจ และงบ Strategic Fund (SF) สำหรับ PMU และหน่วยงานที่ กสว. กำหนด; กำหนดองค์ประกอบคำขอ OKRs การกลั่นกรอง การจัดสรรงบแบบ Block Grant การทำคำรับรองฯ และการคืนเงิน | วันประกาศ/มติ: มติ กสว. ครั้งที่ 8/2566 (18 ส.ค. 2566) | ประกาศ ณ วันที่ 18 ส.ค. 2566 (24 ข้อ) | เชื่อมคู่มือ/SOP: เป็นกฎหมายลำดับรองแม่บทของ คู่มือจัดทำคำขอและการบริหารงบประมาณ FF (TSRI-DOC-0099) และ SOP 0101 ย่อย 1.1, 1.2, 2.1, 2.2 | กฎหมายระดับที่ 3: พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102)', 16, '8041ce101d8a7bc8...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1GdfQ2bzy7HXdH3eYnUh22e-OKT6Ts8Rh/view?usp=drivesdk');
INSERT INTO documents VALUES (9, 'TSRI-F01-04-004', 'TSRI-DOC-0009', 'TSRI-N009', 1, 'หมวดที่ 1', '2.2 การจัดทำคำขอ วิจัยนวัตกรรม (ฉบับที่ 2).pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณและการจัดสรรงบประมาณด้านการวิจัยและนวัตกรรมของหน่วยงานในระบบวิจัยและนวัตกรรม (ฉบับที่ 2) พ.ศ. 2568', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 ร่วมกับ F1', 'พ.ร.บ.สภานโยบายฯ ม.41(4) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) | เชื่อมโยง: ออกตามข้อ 11 แห่งระเบียบสภานโยบายฯ บริหารกองทุน พ.ศ. 2562 (แก้ไขเพิ่มเติมประกาศ 2.1 พ.ศ. 2566)', 'แก้ไขบทนิยามคำว่า ''หน่วยบริหารและจัดการทุน'' ในข้อ 4 ของประกาศ 2.1 พ.ศ. 2566 เพื่อเพิ่ม กรมวิทยาศาสตร์และเทคโนโลยีกลาโหม สำนักงานปลัดกระทรวงกลาโหม (วท.กห.) เข้าเป็น PMU | วันประกาศ/มติ: มติ กสว. ครั้งที่ 74 (11/2568) เมื่อ 13 พ.ย. 2568 | ประกาศ ณ วันที่ 13 พ.ย. 2568 (3 ข้อ) | เชื่อมคู่มือ/SOP: SOP 0101 ย่อย 1.2 และ 2.2 (การจัดกรอบและจัดสรรงบ SF ให้แก่ PMU) | กฎหมายระดับที่ 3: พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102)', 2, 'a6e133da6cf80de5...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1N0kW9gsr9sP2vff1Ect-ksP2HimsPoHy/view?usp=drivesdk');
INSERT INTO documents VALUES (10, 'TSRI-F01-04-005', 'TSRI-DOC-0010', 'TSRI-N010', 1, 'หมวดที่ 1', '2.3 การจัดทำคำของบประมาณ (ฉบับที่ 3) พ.ศ.2569.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณและการจัดสรรงบประมาณด้านการวิจัยและนวัตกรรมของหน่วยงานในระบบวิจัยและนวัตกรรม (ฉบับที่ 3) พ.ศ. 2569', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 ร่วมกับ F1 และ F4', 'พ.ร.บ.สภานโยบายฯ ม.41(4) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) | เชื่อมโยง: ออกตามข้อ 11 แห่งระเบียบสภานโยบายฯ บริหารกองทุน พ.ศ. 2562 (แก้ไขเพิ่มเติมประกาศ 2.1 พ.ศ. 2566 และ 2.2 พ.ศ. 2568)', '1) ปรับนิยาม PMU ล่าสุด 8 แห่ง: วช., สนช., สวรส., สวก., สทนว. (เปลี่ยนจาก ศลช. ตาม พ.ร.ฎ. 2569), สวช., วท.กห. และ รวพ. (สำนักงานเร่งรัดการวิจัยและนวัตกรรมเพื่อเพิ่มความสามารถการแข่งขันและการพัฒนาพื้นที่ (องค์การมหาชน)); 2) ปรับนิยามและขอบเขตคำขอ SF (รวมเงินอุดหนุนการนำงานวิจัยไปใช้ประโยชน์) และ FF; 3) ปรับข้อ 9(3) ให้ยึด OKRs และตัวชี้วัดตามแผนด้าน ววน. | วันประกาศ/มติ: มติ กสว. ครั้งที่ 84 (8/2569) เมื่อ 19 ส.ค. 2569 | ประกาศ พ.ศ. 2569 (6 ข้อ) | เชื่อมคู่มือ/SOP: SOP 0101 (ฉบับกันยายน 2569) และคู่มือ FF ปีงบประมาณ 2570 | กฎหมายระดับที่ 3: พ.ร.ฎ.จัดตั้งสำนักงานเทคโนโลยีและนวัตกรรมด้านชีววิทยาศาสตร์ (องค์การมหาชน) พ.ศ. 2569 และ พ.ร.ฎ.จัดตั้ง รวพ. (องค์การมหาชน) พ.ศ. 2568', 7, '6dce0baab6a3b156...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1nINwy5yt8uAUrGnw58hkMmzEXDndDIRZ/view?usp=drivesdk');
INSERT INTO documents VALUES (11, 'TSRI-F01-04-006', 'TSRI-DOC-0011', 'TSRI-N011', 1, 'หมวดที่ 1', '3.1 การจัดทำคำขอ วิทยาศาสตร์เทคโนโลยี.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณและการจัดสรรงบประมาณเพื่อสนับสนุนการพัฒนาวิทยาศาสตร์และเทคโนโลยีของหน่วยงานในระบบวิจัยและนวัตกรรม พ.ศ. 2566', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 (กลุ่มงานโครงสร้างพื้นฐานระบบ ววน.)', 'พ.ร.บ.สภานโยบายฯ ม.41(4) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) [และเชื่อม ม.5(3), ม.10] | เชื่อมโยง: ออกตามข้อ 11 แห่งระเบียบสภานโยบายฯ บริหารกองทุน พ.ศ. 2562 (สำหรับงบประเภท ST)', 'กำหนดหลักเกณฑ์คำขอและจัดสรรงบประมาณเพื่อสนับสนุนการพัฒนาวิทยาศาสตร์และเทคโนโลยี (Science & Technology Development Fund: ST) มุ่งเน้นโครงสร้างพื้นฐานด้าน ววน. และเทคโนโลยีสารสนเทศ (STI) และโครงสร้างพื้นฐานทางคุณภาพของประเทศ (NQI) โดยยื่นผ่านระบบ STARS | วันประกาศ/มติ: มติ กสว. วาระพิเศษ ครั้งที่ 2/2566 (28 ส.ค. 2566) | ประกาศ ณ วันที่ 28 ส.ค. 2566 (18 ข้อ) | เชื่อมคู่มือ/SOP: SOP 0101 ย่อย 1.3 และ 2.3 (การจัดกรอบและจัดสรรงบ ST ผ่านระบบ STARS) | กฎหมายระดับที่ 3: พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102) และกฎหมายเกี่ยวกับมาตรวิทยาและมาตรฐานคุณภาพ', 8, '00c24f44ba4eec18...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1ubXDcsy9qO_YHl3ZKFPEMqedO_201P7O/view?usp=drivesdk');
INSERT INTO documents VALUES (12, 'TSRI-F01-04-007', 'TSRI-DOC-0012', 'TSRI-N012', 1, 'หมวดที่ 1', '3.2 การจัดทำคำขอ วิทยาศาสตร์เทคโนโลยี (ฉบับที่ 2).pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณและการจัดสรรงบประมาณเพื่อสนับสนุนการพัฒนาวิทยาศาสตร์และเทคโนโลยีของหน่วยงานในระบบวิจัยและนวัตกรรม (ฉบับที่ 2) พ.ศ. 2568', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 ร่วมกับ F1 และ F5', 'พ.ร.บ.สภานโยบายฯ ม.41(4) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) | เชื่อมโยง: ออกตามข้อ 11 แห่งระเบียบสภานโยบายฯ บริหารกองทุน พ.ศ. 2562 (แก้ไขเพิ่มเติมประกาศ 3.1 พ.ศ. 2566)', '1) ยกเลิกนิยาม PMU และตัด PMU ออกจากกลุ่มผู้มีสิทธิยื่นของบ ST (เหลือเฉพาะ ม.รัฐ/หน่วยงานรัฐ, ม.เอกชน, นิติบุคคลไม่แสวงหากำไร); 2) บังคับว่าผู้ยื่นคำขอต้องเป็นผู้ดำเนินแผนงาน/โครงการเอง ห้ามนำงบ ST ที่ได้รับจัดสรรไปให้ทุนต่อแก่บุคคลนอกหน่วยงานโดยปราศจากความเห็นชอบเป็นลายลักษณ์อักษรจาก สกสว. หากฝ่าฝืน กสว. อาจยุติโครงการและเรียกเงินคืนพร้อมดอกผล (ข้อ 7 ใหม่); 3) กำหนดรายละเอียดแผนงาน ST 12 ด้าน (รวม Business Plan / Exit Strategy) | วันประกาศ/มติ: มติ กสว. ครั้งที่ 10/2568 (15 ต.ค. 2568) | ประกาศ ณ วันที่ 15 ต.ค. 2568 (7 ข้อ) | เชื่อมคู่มือ/SOP: SOP 0101 ย่อย 1.3 และ 2.3 (ระบบ STARS) | กฎหมายระดับที่ 3: พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102)', 5, 'fdc10a4aee845b57...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1FTYHFXSf3YXu4YuyIMQJxmf1BAC0bL_6/view?usp=drivesdk');
INSERT INTO documents VALUES (13, 'TSRI-F01-04-008', 'TSRI-DOC-0013', 'TSRI-N013', 1, 'หมวดที่ 1', '4. การจัดทำคำขอ การขับเคลื่อนการนำผลงานไปใช้ประโยชน์.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณและการจัดสรรงบประมาณเพื่อสนับสนุนการขับเคลื่อนการนำผลงานวิจัยและนวัตกรรมไปใช้ประโยชน์จริง พ.ศ. 2566', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4', 'F4 ร่วมกับ F2', 'พ.ร.บ.สภานโยบายฯ ม.41(4) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) [และเชื่อม ม.28] | เชื่อมโยง: ออกตามข้อ 11 แห่งระเบียบสภานโยบายฯ บริหารกองทุน พ.ศ. 2562', 'ใช้บังคับแก่ PMU ที่ยื่นขอรับจัดสรรงบประมาณสำหรับแผนงานย่อยด้านการนำผลงานวิจัยและนวัตกรรมที่พร้อมใช้ไปใช้ประโยชน์จริง (Research Utilization: RU) ใน 3 จุดมุ่งเน้น (ข้อ 7): (1) เชิงพาณิชย์ (2) เชิงสังคม ชุมชนและพื้นที่ (3) เชิงนโยบาย โดยต้องระบุผู้ใช้ประโยชน์ (User) และผลลัพธ์/ผลกระทบอย่างชัดเจน | วันประกาศ/มติ: มติ กสว. ครั้งที่ 12/2566 (22 ธ.ค. 2566) | ประกาศ ณ วันที่ 22 ธ.ค. 2566 (15 ข้อ) | เชื่อมคู่มือ/SOP: SOP 0101 ย่อย 1.2 และ 2.2 (Strategic Fund ด้านการใช้ประโยชน์งานวิจัย) | กฎหมายระดับที่ 3: พ.ร.บ.ส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2564 (TRIUP Act)', 5, '560d7c4c96729542...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1lqhXjD5JE4N9v-jvbzVYnCworDvEIV1Z/view?usp=drivesdk');
INSERT INTO documents VALUES (14, 'TSRI-F01-04-009', 'TSRI-DOC-0014', 'TSRI-N014', 1, 'หมวดที่ 1', '5. การนำเงินกองทุนไปหาประโยชน์.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์ วิธีการและเงื่อนไข การนำเงินกองทุนไปหาผลประโยชน์ พ.ศ. 2563', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A3', 'F3 ร่วมกับ F5 (งานการเงิน)', 'พ.ร.บ.สภานโยบายฯ ม.41(6) และ (16) [ประกอบ ม.55(7), ม.57] | เชื่อมโยง: ออกตามข้อ 6 และข้อ 10 แห่งระเบียบสภานโยบายฯ ว่าด้วยการบริหารกองทุนส่งเสริม ววน. พ.ศ. 2562', 'กำหนดให้ สกสว. นำเงินกองทุนไปหาผลประโยชน์ได้ 5 วิธีโดยคำนึงถึงความมั่นคงปลอดภัยและสภาพคล่อง (ข้อ 5–6): (1) ฝากประจำ/บัตรเงินฝากในธนาคารรัฐวิสาหกิจหรือธนาคารพาณิชย์ที่มี Credit Rating ตั้งแต่ระดับ AA ขึ้นไป (2) ซื้อพันธบัตรกระทรวงการคลังหรือ ธปท. (3) ซื้อตั๋วเงินคลัง (4) ซื้อตราสารหนี้ไทยระยะสั้นอายุไม่เกิน 3 เดือนที่ธนาคารระดับ AA ขึ้นไปรับรอง/อาวัล/ค้ำประกันเต็มจำนวน (5) วิธีอื่นที่ กสว. อนุมัติ (ต้องทำแผน 5 รายการเสนอ กสว. ตามข้อ 7); รายงานผลต่อ กสว. เป็นรายไตรมาส (ข้อ 8) | วันประกาศ/มติ: มติ กสว. ครั้งที่ 6/2563 (19 มิ.ย. 2563) | ประกาศ ณ วันที่ 22 มิ.ย. 2563 (9 ข้อ) | เชื่อมคู่มือ/SOP: คู่มือระเบียบการเงิน พ.ศ. 2568 และแผนการบริหารสภาพคล่องกองทุน ววน. | กฎหมายระดับที่ 3: พ.ร.บ.ธุรกิจสถาบันการเงิน พ.ศ. 2551 และ พ.ร.บ.วินัยการเงินการคลังของรัฐ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0103)', 2, '8ad24012aa44f23f...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1k2ChJ2HGAnKnvWDSaYw8VspVdFdAhVzD/view?usp=drivesdk');
INSERT INTO documents VALUES (15, 'TSRI-F01-04-010', 'TSRI-DOC-0015', 'TSRI-N015', 1, 'หมวดที่ 1', '6.1 การใช้จ่ายเงินอุดหนุนของPMU.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การใช้จ่ายเงินอุดหนุนของหน่วยบริหารและจัดการทุนซึ่งได้รับเงินอุดหนุนจากกองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 ร่วมกับ F3 และ F5', 'พ.ร.บ.สภานโยบายฯ ม.41(16) [ประกอบ ม.57] | เชื่อมโยง: ออกตามข้อ 11 แห่งระเบียบสภานโยบายฯ ว่าด้วยการบริหารกองทุนส่งเสริม ววน. พ.ศ. 2562 (ยกเลิกหลักเกณฑ์ปี 2563–2564 รวม 3 ฉบับ)', 'กำหนดให้ PMU เปิดบัญชีธนาคารแยกสำหรับรับเงินอุดหนุนจากกองทุนและแนบในคำรับรองฯ (ข้อ 6); การเบิกจ่ายเงินค่าบำรุงสถาบัน (Overhead) ของหน่วยงานที่รับทุนจาก PMU ให้เบิกจ่ายได้ในเงินงวดสุดท้ายภายหลังโครงการเสร็จสิ้น (ข้อ 7 วรรคสอง); บันทึกข้อมูลและความก้าวหน้าในระบบ NRIIS (ข้อ 8); การจัดซื้อจัดจ้างในโครงการวิจัยให้เป็นไปตามเกณฑ์ ม.19 พ.ร.บ.ส่งเสริมฯ (ข้อ 9); กำหนดเพดานงบบริหารจัดการของ PMU และการคืนเงินคงเหลือ (ข้อ 10–13) | วันประกาศ/มติ: มติ กสว. ครั้งที่ 7/2565 (22 ก.ค. 2565) | ประกาศ พ.ศ. 2565 (15 ข้อ) | เชื่อมคู่มือ/SOP: SOP 0101 (การทำคำรับรองฯ และการติดตามการใช้จ่ายเงินของ PMU) | กฎหมายระดับที่ 3: พ.ร.บ.การจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 (หมวด 12: TSRI-DOC-0104) (เชื่อม พ.ร.บ.ส่งเสริมฯ ม.19)', 5, '15cdeb894547c6f7...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1Yg3Iljt32l8Vg5w9oyTw6zPHwtT2ss60/view?usp=drivesdk');
INSERT INTO documents VALUES (16, 'TSRI-F01-04-011', 'TSRI-DOC-0016', 'TSRI-N016', 1, 'หมวดที่ 1', '6.2 การใช้จ่ายเงินอุดหนุนของPMU (ฉบับที่ 2).pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การใช้จ่ายเงินอุดหนุนของหน่วยบริหารและจัดการทุนซึ่งได้รับเงินอุดหนุนจากกองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม (ฉบับที่ 2) พ.ศ. 2567', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A3', 'F3 ร่วมกับ F2 และ F5 (งานการเงิน)', 'พ.ร.บ.สภานโยบายฯ ม.41(16) | เชื่อมโยง: ออกตามข้อ 11 แห่งระเบียบสภานโยบายฯ บริหารกองทุน พ.ศ. 2562 (แก้ไขข้อ 13 ของประกาศ 6.1 พ.ศ. 2565)', 'แก้ไขข้อ 13 เรื่องการคืนเงินคงเหลือและดอกเบี้ยของ PMU: (1) เงินอุดหนุนเพื่อการวิจัยที่ PMU มิได้ทำสัญญาให้ทุน ต้องนำส่งคืนกองทุนภายใน 45 วันนับแต่วันถัดจากวันสิ้นสุดปีงบประมาณ (ไม่รวมงบบริหารของ PMU) (2) เงินคงเหลือจากโครงการวิจัยที่ผู้รับทุนส่งคืน PMU ให้ PMU นำไปใช้เป็นเงินอุดหนุนเพื่อการวิจัยตามแผนงานและเป้าหมายของ PMU ได้โดยต้องแจ้งให้ กสว. ทราบ; ส่วน ''ดอกเบี้ยทั้งหมด'' ในบัญชีรับเงินงบประมาณจากกองทุนให้ตกเป็นของกองทุนและนำส่งคืนภายใน 45 วันนับแต่วันถัดจากวันสิ้นสุดปีงบประมาณ | วันประกาศ/มติ: มติ กสว. ครั้งที่ 3/2567 (15 พ.ค. 2567) | ประกาศ ณ วันที่ 15 พ.ค. 2567 (4 ข้อ) | เชื่อมคู่มือ/SOP: คู่มือระเบียบการเงิน พ.ศ. 2568 และระบบติดตามการคืนเงินกองทุน ววน. | กฎหมายระดับที่ 3: พ.ร.บ.วินัยการเงินการคลังของรัฐ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0103)', 2, '79965563ce31803f...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1NE1xNtdkr4uhYAy8t7EtxQ6cv2cIh_E2/view?usp=drivesdk');
INSERT INTO documents VALUES (17, 'TSRI-F01-04-012', 'TSRI-DOC-0017', 'TSRI-N017', 1, 'หมวดที่ 1', '6.3 การใช้จ่ายเงินอุดหนุนของPMU (ฉบับที่ 3).pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การใช้จ่ายเงินอุดหนุนของหน่วยบริหารและจัดการทุนซึ่งได้รับเงินอุดหนุนจากกองทุนส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม (ฉบับที่ 3) พ.ศ. 2568', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 ร่วมกับ F3 และ F5', 'พ.ร.บ.สภานโยบายฯ ม.41(16) | เชื่อมโยง: ออกตามข้อ 11 แห่งระเบียบสภานโยบายฯ บริหารกองทุน พ.ศ. 2562 (แก้ไขนิยาม PMU ในข้อ 4 ของประกาศ 6.1 พ.ศ. 2565)', 'แก้ไขบทนิยามคำว่า ''หน่วยบริหารและจัดการทุน'' ในข้อ 4 ของประกาศ 6.1 พ.ศ. 2565 เพื่อเพิ่ม ''กรมวิทยาศาสตร์และเทคโนโลยีกลาโหม สำนักงานปลัดกระทรวงกลาโหม (วท.กห.)'' ให้สอดคล้องกับการจัดประเภทหน่วยงานด้านการให้ทุน | วันประกาศ/มติ: มติ กสว. ครั้งที่ 74 (11/2568) เมื่อ 13 พ.ย. 2568 | ประกาศ ณ วันที่ 13 พ.ย. 2568 (3 ข้อ) | เชื่อมคู่มือ/SOP: SOP 0101 และระบบบริหารการเงินกองทุน ววน. | กฎหมายระดับที่ 3: พ.ร.บ.วินัยการเงินการคลังของรัฐ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0103)', 2, 'bfcad0edcfe3aee3...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1wqChQCI9zErK7X0cJZ-CAuGBUkYObeqE/view?usp=drivesdk');
INSERT INTO documents VALUES (18, 'TSRI-F01-04-013', 'TSRI-DOC-0018', 'TSRI-N018', 1, 'หมวดที่ 1', '7. การปรับงบประมาณระหว่างปี.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การปรับงบประมาณระหว่างปีงบประมาณ การจัดทำคำของบประมาณและการจัดสรรงบประมาณเพื่อการวิจัยและนวัตกรรมที่สำคัญและจำเป็นเร่งด่วน พ.ศ. 2564', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 ร่วมกับ F1', 'พ.ร.บ.สภานโยบายฯ ม.41(4),(7) และ (16) ประกอบ ม.57 และ พ.ร.บ.ส่งเสริมฯ ม.17(2) | เชื่อมโยง: เชื่อมโยงกับระเบียบสภานโยบายฯ บริหารกองทุน พ.ศ. 2562 และประกาศหลักเกณฑ์คำของบประมาณฯ', 'แบ่งเป็น 2 หมวด: หมวด 1 การปรับงบประมาณระหว่างปี กรณีกระทบ OKRs ตามโปรแกรม/แผนงาน/โครงการ ให้ยื่นคำขอปรับต่อ สกสว. ได้ ''ไตรมาสละ 1 ครั้ง'' เสนอคณะอนุกรรมการแผนและกรอบงบฯ กลั่นกรองก่อนเสนอ กสว. อนุมัติและทำคำรับรองฯ ใหม่ (ข้อ 6–8); หมวด 2 การจัดทำคำขอและจัดสรรงบเพื่อการวิจัยที่สำคัญและจำเป็นเร่งด่วนนอกแผนประจำปี เพื่อดำเนินการตามข้อสั่งการนายกรัฐมนตรี มติ ครม. หรือมติสภานโยบาย โดยต้องระบุผู้ใช้ประโยชน์ชัดเจนและคำนึงถึงเงินกองทุนคงเหลือ/กระแสเงินสด (ข้อ 9–12) | วันประกาศ/มติ: มติ กสว. ครั้งที่ 1/2564 (15 ม.ค. 2564) | ประกาศ ณ วันที่ 21 ม.ค. 2564 (13 ข้อ) | เชื่อมคู่มือ/SOP: คู่มือ FF บทที่ 3 ข้อ 5 (การปรับแผนและงบประมาณระหว่างปีงบประมาณ) | กฎหมายระดับที่ 3: พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102) และ พ.ร.บ.วินัยการเงินการคลังของรัฐ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0103)', 2, 'ba5e7bde72cdea24...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1C7QS2ylEiG1aqLhTBQpB6g2Q49-Nsj96/view?usp=drivesdk');
INSERT INTO documents VALUES (19, 'TSRI-F01-04-014', 'TSRI-DOC-0019', 'TSRI-N019', 1, 'หมวดที่ 1', '8. ส่งเสริมสนับสนุนความร่วมมือ.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การส่งเสริมและสนับสนุนความร่วมมือในการพัฒนาวิทยาศาสตร์ วิจัยและนวัตกรรม การนำผลงานวิจัยและนวัตกรรมไปใช้ประโยชน์ และการถ่ายทอดวิทยาการหรือเทคโนโลยี พ.ศ. 2566', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4', 'F4 (สำนักกลยุทธ์พัฒนาความร่วมมือนานาชาติและใช้ประโยชน์งานวิจัยระบบ ววน.) ร่วมกับ F3', 'พ.ร.บ.สภานโยบายฯ ม.41(11) และ (16) [ประกอบ ม.44(13), ม.54(6) และปลั๊กอิน พ.ร.บ.ส่งเสริมฯ ม.11] | เชื่อมโยง: ออกตามข้อ 11(2) แห่งระเบียบสภานโยบายฯ บริหารกองทุน พ.ศ. 2562 และเชื่อมข้อ 5 เข้ากับระเบียบสภานโยบายฯ ว่าด้วยการสนับสนุนทุนแก่ภาคเอกชนฯ พ.ศ. 2563', 'กำหนดหลักเกณฑ์การทำความร่วมมือระหว่างกองทุน ววน. กับหน่วยงาน 4 กลุ่ม (รัฐ, เอกชน, ประชาสังคม/มูลนิธิ/สมาคม, หน่วยงานต่างประเทศ — ข้อ 8) โดยหน่วยงานความร่วมมือต้องร่วมสนับสนุนเงิน (Matching/Co-funding) และห้ามนำงบที่ได้รับจัดสรรจากกองทุน ววน. มาใช้เป็นเงินสมทบ (ข้อ 7); ขั้นตอนประกอบด้วย (1) จัดทำ MOU (2) เสนอแผนความร่วมมือให้ กสว. เห็นชอบ และ (3) จัดทำคำรับรองความร่วมมือ (ข้อ 10) | วันประกาศ/มติ: มติ กสว. ครั้งที่ 11/2566 (17 พ.ย. 2566) | ประกาศ พ.ศ. 2566 (18 ข้อ) | เชื่อมคู่มือ/SOP: กระบวนงานความร่วมมือนานาชาติและพันธมิตรเชิงกลยุทธ์ของสำนัก F4 และ F3 | กฎหมายระดับที่ 3: พ.ร.บ.การส่งเสริมวิทยาศาสตร์ การวิจัยและนวัตกรรม พ.ศ. 2562 มาตรา 11 และมาตรา 28', 6, '89b8189a86bc6321...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1KKx7u6w6FKNv1g--cSBNqwtxAop2b9l8/view?usp=drivesdk');
INSERT INTO documents VALUES (20, 'TSRI-F01-04-015', 'TSRI-DOC-0020', 'TSRI-N020', 1, 'หมวดที่ 1', '9. มาตรการ TBIR.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง มาตรการสนับสนุนทุนสำหรับภาคเอกชน เพื่อพัฒนาผลงานวิจัยและนวัตกรรมตามความต้องการของภาครัฐหรือตามอุปสงค์ของตลาด พ.ศ. 2564', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4', 'F4 ร่วมกับ F3', 'พ.ร.บ.สภานโยบายฯ ม.41(8),(11) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.28 วรรคสอง | เชื่อมโยง: ออกตามระเบียบสภานโยบายฯ ว่าด้วยหลักเกณฑ์และวิธีการสนับสนุนทุนวิจัยและนวัตกรรมให้แก่ภาคเอกชนและภาคประชาสังคมฯ พ.ศ. 2563 (TSRI-DOC-0027 ในหมวด 2)', 'กำหนดกลไกสนับสนุนทุนสำหรับภาคเอกชนตามความต้องการภาครัฐหรืออุปสงค์ตลาด (Thai Business Innovation Research: TBIR) โดย กสว. กำหนดประเด็นวิจัย PMU ที่รับผิดชอบ และกรอบวงเงินเป็นรายปี (ข้อ 4–5); แบ่งการดำเนินการเป็น 3 ระยะ (ข้อ 6 วรรคสอง): ระยะที่ 1 การศึกษาความเป็นไปได้ (Feasibility Study), ระยะที่ 2 การพัฒนาต้นแบบ (Prototype Development) [ใช้เงินอุดหนุนกองทุนตามสัดส่วนร้อยละที่ กสว. กำหนด] และระยะที่ 3 การมุ่งเน้นใช้ประโยชน์เชิงพาณิชย์ (Commercialization) [ใช้กลไกและมาตรการอื่นสนับสนุน] | วันประกาศ/มติ: มติ กสว. ครั้งที่ 2/2564 (19 ก.พ. 2564) | ประกาศ ณ วันที่ 19 ก.พ. 2564 (11 ข้อ) | เชื่อมคู่มือ/SOP: แนวทางการจัดสรรงบ Strategic Fund (SF) สำหรับภาคเอกชนของสำนัก F3 และ F4 | กฎหมายระดับที่ 3: พ.ร.บ.ส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2564 (TRIUP Act) และ พ.ร.บ.การจัดซื้อจัดจ้างฯ พ.ศ. 2560 (หมวด 12: TSRI-DOC-0104) (เชื่อม พ.ร.บ.ส่งเสริมฯ ม.29(1))', 2, '8416ddd3e8bd351d...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1U3LJhbajSVlaKj93NWQ4eVC2-leMhiE-/view?usp=drivesdk');
INSERT INTO documents VALUES (21, 'TSRI-F01-04-016', 'TSRI-DOC-0021', 'TSRI-N021', 1, 'หมวดที่ 1', 'สิ่งที่ส่งมาด้วย 3.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณและการจัดสรรงบประมาณของหน่วยงานในระบบวิจัยและนวัตกรรม พ.ศ. 2563', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 (ทะเบียนประวัติหลักเกณฑ์งบประมาณ)', 'พ.ร.บ.สภานโยบายฯ ม.41(4) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) | เชื่อมโยง: ประกาศหลักเกณฑ์คำของบประมาณยุคแรก (ใช้คำว่า ''งานพื้นฐาน Fundamental Fund'')', 'กำหนดหลักเกณฑ์คำของบประมาณรุ่นแรกปี 2563 แบ่งเป็น FF และ SF (ยกเว้นโครงการความมั่นคงของกระทรวงกลาโหมต้องยื่นสำนักงบประมาณโดยตรง เว้นแต่เทคโนโลยีสองทาง Dual Use); ปัจจุบันถูกยกเลิกและแทนที่โดยประกาศ 2.1 พ.ศ. 2566–2569 | วันประกาศ/มติ: มติ กสว. ครั้งที่ 7/2563 และ 10/2563 | ประกาศ ณ วันที่ 12 ต.ค. 2563 (21 ข้อ) | เชื่อมคู่มือ/SOP: เก็บในโฟลเดอร์ ''ยกเลิก'' เพื่อใช้อ้างอิงประวัติวิวัฒนาการของหลักเกณฑ์คำของบประมาณ (Historical Traceability) | กฎหมายระดับที่ 3: พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102)', 3, 'aa48106877a23814...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1SO1JLakT7seyETDFzbmcgPD3ILm5XNd_/view?usp=drivesdk');
INSERT INTO documents VALUES (22, 'TSRI-F01-04-017', 'TSRI-DOC-0022', 'TSRI-N022', 1, 'หมวดที่ 1', 'สิ่งที่ส่งมาด้วย 4.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณและการจัดสรรงบประมาณของหน่วยงานในระบบวิจัยและนวัตกรรม (ฉบับที่ 2) พ.ศ. 2564', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 (ทะเบียนประวัติหลักเกณฑ์งบประมาณ)', 'พ.ร.บ.สภานโยบายฯ ม.41(4) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) | เชื่อมโยง: แก้ไขเพิ่มเติมข้อ 5(1) ของประกาศ พ.ศ. 2563', 'ปรับปรุงนิยามคำของบประมาณเพื่อสนับสนุนงานพื้นฐาน (Fundamental Fund) ในข้อ 5(1) ของประกาศปี 2563; ปัจจุบันถูกยกเลิกแล้ว | วันประกาศ/มติ: มติ กสว. ครั้งที่ 7/2564 (16 ก.ค. 2564) | ประกาศ ณ วันที่ 16 ก.ค. 2564 (3 ข้อ) | เชื่อมคู่มือ/SOP: เก็บในโฟลเดอร์ ''ยกเลิก'' เพื่อการตรวจสอบย้อนกลับ | กฎหมายระดับที่ 3: พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102)', 1, '653e639595ececc8...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1yPVOMcOpbJvGWtHgC7TNIg2CSue8KnAn/view?usp=drivesdk');
INSERT INTO documents VALUES (23, 'TSRI-F01-04-018', 'TSRI-DOC-0023', 'TSRI-N023', 1, 'หมวดที่ 1', 'สิ่งที่ส่งมาด้วย 5.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณและการจัดสรรงบประมาณของหน่วยงานในระบบวิจัยและนวัตกรรม (ฉบับที่ 3) พ.ศ. 2564', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 (ทะเบียนประวัติหลักเกณฑ์งบประมาณ)', 'พ.ร.บ.สภานโยบายฯ ม.41(4) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) และระเบียบบริหารกองทุนฯ ข้อ 11 | เชื่อมโยง: เปลี่ยนคำว่า ''งานพื้นฐาน'' เป็น ''งานมูลฐาน (Fundamental Fund)'' และกำหนดเพดานงบเสริมสร้างความเข้มแข็งไม่เกิน 5% (สูงสุด 5 ล้านบาท)', 'เป็นจุดเปลี่ยนคำศัพท์จาก ''งานพื้นฐาน'' เป็น ''งานมูลฐานตามพันธกิจของหน่วยรับงบประมาณ (Fundamental Fund)'' และวางรากฐานหมวดค่าใช้จ่าย FF (ห้ามขอรายจ่ายประจำ/Overhead, ขอค่าสาธารณูปโภคได้ <=1%, ของบเสริมสร้างความเข้มแข็งและธรรมาภิบาลได้ <=5% แต่ไม่เกิน 5 ล้านบาท); ปัจจุบันถูกยกเลิกและพัฒนาต่อเป็นประกาศปี 2566 และคู่มือ FF | วันประกาศ/มติ: มติ กสว. ครั้งที่ 10/2564 (15 ต.ค. 2564) | ประกาศ ณ วันที่ 15 ต.ค. 2564 (18 ข้อ) | เชื่อมคู่มือ/SOP: เนื้อหาถูกนำไปปรับปรุงในคู่มือ FF (TSRI-DOC-0099 บทที่ 2) | กฎหมายระดับที่ 3: พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102)', 11, '22c45d5235e84ff8...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/11vAx_zQdfv7atkHktSgQHYAXhta5ZNNW/view?usp=drivesdk');
INSERT INTO documents VALUES (24, 'TSRI-F01-04-019', 'TSRI-DOC-0024', 'TSRI-N024', 1, 'หมวดที่ 1', 'หลักเกณฑ์การจัดทำคำขอและจัดสรรงบประมาณของหน่วยงานในระบบวิจัยและนวัตกรรม-2565.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณและการจัดสรรงบประมาณของหน่วยงานในระบบวิจัยและนวัตกรรม พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2', 'F2 (ทะเบียนประวัติหลักเกณฑ์งบประมาณ)', 'พ.ร.บ.สภานโยบายฯ ม.41(4) และ (16) ประกอบ พ.ร.บ.ส่งเสริมฯ ม.17(2) | เชื่อมโยง: รวบรวมและยกเลิกประกาศปี 2563–2564 ทั้ง 3 ฉบับ ก่อนจะถูกยกเลิกโดยประกาศ 2.1 พ.ศ. 2566', 'ปรับปรุงหลักเกณฑ์คำขอและการจัดสรรงบประมาณ FF และ SF ประจำปี 2565 โดยยกเลิกประกาศปี 2563–2564 ทั้ง 3 ฉบับ และต่อมาถูกยกเลิกโดยข้อ 3 ของประกาศ กสว. เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณฯ พ.ศ. 2566 (ไฟล์ 2.1) | วันประกาศ/มติ: มติ กสว. ครั้งที่ 7/2565 (22 ก.ค. 2565) | ประกาศ ณ วันที่ 22 ก.ค. 2565 (23 ข้อ) | เชื่อมคู่มือ/SOP: ถูกแทนที่โดยประกาศ 2.1 พ.ศ. 2566 (แก้ไขเพิ่มเติมถึงฉบับที่ 3 พ.ศ. 2569) | กฎหมายระดับที่ 3: พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102)', 17, 'bbb7501d81390f7b...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1rqRFld1qGQLBpkpkGhKJVBpGsIymxmQK/view?usp=drivesdk');
INSERT INTO documents VALUES (25, 'TSRI-F02-01-001', 'TSRI-DOC-0025', 'TSRI-N025', 2, 'หมวดที่ 2', '1. พ.ร.บ.การส่งเสริมวิทยาศาสตร์ฯ พ.ศ. 2562.pdf', 'พระราชบัญญัติการส่งเสริมวิทยาศาสตร์ การวิจัยและนวัตกรรม พ.ศ. 2562', 'ระดับที่ 1: กฎหมายแม่บทและกฎหมายจัดตั้ง (4.1.1.1)', 'A1, A2, A3, A4', 'สำนัก F1 / F2 / F3', 'มาตรา 6, 7, 9, 12–19, 22–36 แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (ปลั๊กอินคู่กับ พ.ร.บ.สภานโยบายฯ ม.11, 44, 54–61)', 'กำหนดกลไกหลัก 6 ด้านของระบบ ววน.: 1) การจัดประเภทหน่วยงานในระบบ ววน. 5 ประเภท (ม.7) 2) ขอบเขตการทำวิจัยเองของ สกสว. เฉพาะนโยบายและระบบงาน (ม.9) 3) การจัดทำแผนด้าน ววน. 6 ด้านและการรับฟังความเห็น (ม.12–13) 4) การกลั่นกรองคำของบประมาณ 2 สาย (ม.16–17) และการแจ้งผลจัดสรร (ม.18) 5) การจัดซื้อจัดจ้างเพื่อการวิจัย (ม.19) และ 6) การจัดทำฐานข้อมูลกลาง ววน. การคุ้มครองข้อมูลลับ (ม.22–27) และโทษอาญา (ม.36) | ราชกิจจานุเบกษา เล่ม 136 ตอนที่ 68 ก (25 พ.ค. 2562)', 18, 'd7791ff5ede71798...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/115RIHyhH_S-Xl0BPxQNTrLd4GREUl-gM/view?usp=drivesdk');
INSERT INTO documents VALUES (26, 'TSRI-F02-01-002', 'TSRI-DOC-0026', 'TSRI-N026', 2, 'หมวดที่ 2', '2. พ.ร.บ.การส่งเสริมวิทยาศาสตร์ฯ (ฉ.2) พ.ศ. 2568.pdf', 'พระราชบัญญัติการส่งเสริมวิทยาศาสตร์ การวิจัยและนวัตกรรม (ฉบับที่ 2) พ.ศ. 2568', 'ระดับที่ 1: กฎหมายแม่บทและกฎหมายจัดตั้ง (4.1.1.1)', 'A2', 'สำนัก F1 / F2 / F3', 'มาตรา 3 แก้ไขเพิ่มเติมมาตรา 18 แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (เชื่อมโยง พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 ม.24–26 และประกาศ กสว. คำของบ ฉ.3 พ.ศ. 2569 ข้อ 44/1–44/2)', 'แก้ไขกลไกการรับเงินอุดหนุนจากกองทุน ววน. โดยเปลี่ยนจากสัญญารับทุนรายโครงการเป็น ''คำรับรองการปฏิบัติตามเงื่อนไขการรับเงินอุดหนุน'' (Multi-year Grant Commitment) และวางหลักเกณฑ์การตั้งงบประมาณผูกพันข้ามปีงบประมาณ (50:50 สำหรับโครงการต่อเนื่อง) | ราชกิจจานุเบกษา เล่ม 142 ตอนที่ 14 ก หน้า 24–26 (24 มี.ค. 2568)', 3, '1f00c3c0d36193e0...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1Q0ELQpdYOQSmEjVzFyCvT6Ko2NoJZA46/view?usp=drivesdk');
INSERT INTO documents VALUES (27, 'TSRI-F02-02-001', 'TSRI-DOC-0027', 'TSRI-N027', 2, 'หมวดที่ 2', '1. วิธีการสนับสนุนทุนวิจัยแก่ภาคเอกชน.pdf', 'ระเบียบสภานโยบายฯ ว่าด้วยหลักเกณฑ์และวิธีการสนับสนุนทุนวิจัยและนวัตกรรมแก่ภาคเอกชนและภาคประชาสังคมเพื่อให้นำผลงานวิจัยและนวัตกรรมไปใช้ประโยชน์ พ.ศ. 2563', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A2, A3, A4', 'สำนัก F1 / F2 / F3', 'ออกตามมาตรา 28 วรรคสอง แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (เชื่อมโยง พ.ร.บ.สภานโยบายฯ ม.11(9) และ ม.57)', 'กำหนดหลักเกณฑ์และวิธีการสนับสนุนทุนวิจัยและนวัตกรรมแก่ภาคเอกชนและภาคประชาสังคม 5 รูปแบบ ได้แก่ 1) ทุนอุดหนุน (Grant) 2) ทุนสมทบ (Matching Grant) 3) ทุนอุดหนุนแบบมีเงื่อนไขเรียกคืน (Recoverable Grant) 4) เงินกู้ยืมดอกเบี้ยต่ำหรือไร้ดอกเบี้ย (Loans) และ 5) รูปแบบอื่นตามที่สภานโยบายกำหนด | ราชกิจจานุเบกษา 9 ต.ค. 2563', 8, '534718bba9721e8c...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1hjt256qC6xJ7V3SDIr-TFsNOcg3itoho/view?usp=drivesdk');
INSERT INTO documents VALUES (28, 'TSRI-F02-02-002', 'TSRI-DOC-0028', 'TSRI-N028', 2, 'หมวดที่ 2', '2. แจ้ง นำส่ง เชื่อมโยง รายงานผลงานวิจัย.pdf', 'ระเบียบสภานโยบายฯ ว่าด้วยการแจ้ง การนำส่ง การเชื่อมโยงข้อมูล การรายงานผลงานวิจัยและนวัตกรรม และการเปิดเผยข้อมูลการวิจัยในระบบข้อมูลสารสนเทศกลาง พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4, A5', 'สำนัก F1 / F2 / F3', 'ออกตามมาตรา 22 วรรคสาม, มาตรา 23 วรรคหนึ่งและวรรคสาม, มาตรา 27 วรรคหนึ่ง และมาตรา 35 วรรคสอง แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562', 'กำหนดหน้าที่ของหน่วยงานในระบบ ววน. ในการแจ้ง นำส่ง เชื่อมโยงข้อมูล รายงานผลงานวิจัยและนวัตกรรม และการเปิดเผยข้อมูลการวิจัยในระบบข้อมูลสารสนเทศกลาง (NRIIS) ครอบคลุมชุดข้อมูลมาตรฐาน 15 รายการ และหลักเกณฑ์การแยกข้อมูลลับตามมาตรา 24–25 | ราชกิจจานุเบกษา 27 ม.ค. 2566', 5, 'de2514e4da9212ff...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1cuu7ZSaoVDvLaAjdDAn9IT0im5LD-4r9/view?usp=drivesdk');
INSERT INTO documents VALUES (29, 'TSRI-F02-02-003', 'TSRI-DOC-0029', 'TSRI-N029', 2, 'หมวดที่ 2', '3. การร่วมลงทุนระหว่างรัฐและเอกชน.pdf', 'ระเบียบสภานโยบายฯ ว่าด้วยการร่วมลงทุนระหว่างรัฐและเอกชนในโครงการซึ่งนำผลงานวิจัยและนวัตกรรมไปใช้ประโยชน์ พ.ศ. 2566', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A3, A4', 'สำนัก F1 / F2 / F3', 'ออกตามมาตรา 31 วรรคหนึ่ง แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 ประกอบมาตรา 11(9) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562', 'กำหนดหลักเกณฑ์การร่วมลงทุนระหว่างหน่วยงานของรัฐ/สถาบันอุดมศึกษากับภาคเอกชน (Joint Venture) ในโครงการซึ่งนำผลงานวิจัยและนวัตกรรมไปใช้ประโยชน์ การประเมินมูลค่าทรัพย์สินทางปัญญาเพื่อแปลงเป็นทุน และธรรมาภิบาลการบริหารกิจการร่วมค้า | ราชกิจจานุเบกษา 26 ม.ค. 2567', 2, '9de2a6c79a26675a...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1gb5ik3upvF9J-J03fvoLRus2h-PpGwAO/view?usp=drivesdk');
INSERT INTO documents VALUES (30, 'TSRI-F02-03-001', 'TSRI-DOC-0030', 'TSRI-N030', 2, 'หมวดที่ 2', 'ระเบียบจริยธรรมการวิจัยทั่วไป.pdf', 'ระเบียบคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยจริยธรรมการวิจัยทั่วไป พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1', 'สำนัก F1 / F2 / F3', 'ออกตามมาตรา 33(1) แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 ประกอบมาตรา 41(10) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562', 'กำหนดหลักจริยธรรมการวิจัยทั่วไป 5 ประการสำหรับนักวิจัยและหน่วยงานในระบบ ววน. (ความซื่อสัตย์ทางวิชาการ การเคารพศักดิ์ศรีและสิทธิของผู้เข้าร่วมการวิจัย ความรับผิดชอบต่อสังคม การจัดการผลประโยชน์ทับซ้อน และการกำกับดูแลโดยคณะกรรมการจริยธรรมการวิจัย) | ราชกิจจานุเบกษา 14 ธ.ค. 2565', 8, 'b5c3b27fcd830a83...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1Yx0YdHExPmD1Lal1lTdUNxxfNIU3N2-H/view?usp=drivesdk');
INSERT INTO documents VALUES (31, 'TSRI-F02-04-001', 'TSRI-DOC-0031', 'TSRI-N031', 2, 'หมวดที่ 2', '1. จัดทำฐานข้อมูล อววน..pdf', 'ประกาศสภานโยบายฯ เรื่อง การจัดทำฐานข้อมูลการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรม และหลักเกณฑ์ วิธีการ และเงื่อนไขการแจ้ง การนำส่ง การเชื่อมโยงข้อมูล การรายงานผลงานวิจัยและนวัตกรรม และการเปิดเผยข้อมูลต่อสาธารณชน พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A1, A5', 'สำนัก F1 / F2 / F3', 'ออกตามมาตรา 11(7) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และมาตรา 22 วรรคสาม, มาตรา 23, มาตรา 27 วรรคหนึ่ง แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562', 'กำหนดมาตรฐานการจัดทำฐานข้อมูลการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรม การเชื่อมโยงข้อมูลผ่าน API ระหว่าง สกสว. (ระบบ NRIIS) สอวช. และสำนักงานการวิจัยแห่งชาติ (วช.) รวมถึงกรอบเวลาการรายงานผลงานวิจัยต่อสาธารณชน | ราชกิจจานุเบกษา 27 ม.ค. 2566', 11, 'd8777b17c4d9ff65...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1_0yfIDMplRGtl-vFpP3PdgJHa-C6uMjY/view?usp=drivesdk');
INSERT INTO documents VALUES (32, 'TSRI-F02-04-002', 'TSRI-DOC-0032', 'TSRI-N032', 2, 'หมวดที่ 2', '2.1 จัดประเภทหน่วยงานในระบบ วน.pdf', 'ประกาศสภานโยบายฯ เรื่อง การจัดประเภทหน่วยงานในระบบวิจัยและนวัตกรรม พ.ศ. 2564', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A1, A2', 'สำนัก F1 / F2 / F3', 'ออกตามมาตรา 7 แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (เชื่อมโยงประกาศ กสว. เรื่องคุณสมบัติหน่วยงานรับงบประมาณ DOC-0014–0015)', 'จัดแบ่งหน่วยงานในระบบวิจัยและนวัตกรรมออกเป็น 5 ประเภทหลัก โดยจัดให้ สกสว. อยู่ในประเภทที่ (1) หน่วยงานด้านนโยบาย ยุทธศาสตร์ แผน และงบประมาณ ววน., กำหนดรายชื่อ PMU ในประเภทที่ (2), และกำหนดหน่วยรับงบประมาณในประเภทที่ (3)–(5) | ราชกิจจานุเบกษา 7 ก.พ. 2565', 10, '32342fd57c5db509...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1GVFrkJeIczub0oAP7aIOErKUpmGQsgsN/view?usp=drivesdk');
INSERT INTO documents VALUES (33, 'TSRI-F02-04-003', 'TSRI-DOC-0033', 'TSRI-N033', 2, 'หมวดที่ 2', '2.2 จัดประเภทหน่วยงานในระบบ วน. (ฉบับที่ 2).pdf', 'ประกาศสภานโยบายฯ เรื่อง การจัดประเภทหน่วยงานในระบบวิจัยและนวัตกรรม (ฉบับที่ 2) พ.ศ. 2566', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A1, A2', 'สำนัก F1 / F2 / F3', 'ออกตามมาตรา 7 แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (แก้ไขเพิ่มเติมประกาศจัดประเภทหน่วยงานฯ พ.ศ. 2564)', 'ปรับปรุงและเพิ่มเติมรายชื่อหน่วยงานในระบบวิจัยและนวัตกรรมประเภทที่ 3 (หน่วยงานวิจัยของรัฐ), ประเภทที่ 4 (สถาบันอุดมศึกษา) และประเภทที่ 5 (มูลนิธิและองค์กรไม่แสวงหากำไร) เพื่อรองรับการขอรับจัดสรรงบประมาณจากกองทุน ววน. | ราชกิจจานุเบกษา 9 ส.ค. 2566', 2, '5f7f624f9389f650...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1R2RVoJOtzZD_cCYgQkkZxQwI9mNSOjd9/view?usp=drivesdk');
INSERT INTO documents VALUES (34, 'TSRI-F02-04-004', 'TSRI-DOC-0034', 'TSRI-N034', 2, 'หมวดที่ 2', '2.3 จัดประเภทหน่วยงานในระบบ วน. (ฉบับที่ 3).pdf', 'ประกาศสภานโยบายฯ เรื่อง การจัดประเภทหน่วยงานในระบบวิจัยและนวัตกรรม (ฉบับที่ 3) พ.ศ. 2567', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A1, A2', 'สำนัก F1 / F2 / F3', 'ออกตามมาตรา 7 แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (ฉบับที่ 3 พ.ศ. 2567)', 'เพิ่มเติมรายชื่อหน่วยงานของรัฐ 9 แห่ง สถาบันอุดมศึกษา 2 แห่ง และมูลนิธิ 3 แห่ง เข้าสู่บัญชีหน่วยงานในระบบวิจัยและนวัตกรรมที่มีสิทธิเสนอคำของบประมาณผ่านระบบ NRIIS | ราชกิจจานุเบกษา 25 ธ.ค. 2567', 2, '7078c09dda5f9ce7...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1wQUdFTbAFum8LsEqMMcI0gPHzw5Q4zX5/view?usp=drivesdk');
INSERT INTO documents VALUES (35, 'TSRI-F02-04-005', 'TSRI-DOC-0035', 'TSRI-N035', 2, 'หมวดที่ 2', '2.4 จัดประเภทหน่วยงานในระบบ วน. (ฉบับที่ 4).pdf', 'ประกาศสภานโยบายฯ เรื่อง การจัดประเภทหน่วยงานในระบบวิจัยและนวัตกรรม (ฉบับที่ 4) พ.ศ. 2568', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A1, A2', 'สำนัก F1 / F2 / F3', 'ออกตามมาตรา 7 แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (ฉบับที่ 4 พ.ศ. 2568)', 'กำหนดให้กรมวิทยาศาสตร์และเทคโนโลยีกลาโหม เป็นหน่วยงานในระบบวิจัยและนวัตกรรม ประเภทที่ 2 (หน่วยงานให้ทุนวิจัยและนวัตกรรม / PMU ด้านความมั่นคงและเทคโนโลยีป้องกันประเทศ) | ราชกิจจานุเบกษา 11 พ.ย. 2568', 1, 'd3cfaf4a18d683b8...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1Dzg8-4hlNdGc6f8QwKeGZaqDIJHXRClo/view?usp=drivesdk');
INSERT INTO documents VALUES (36, 'TSRI-F02-04-006', 'TSRI-DOC-0036', 'TSRI-N036', 2, 'หมวดที่ 2', '2.5 จัดประเภทหน่วยงานในระบบ วน. (ฉบับที่ 5).pdf', 'ประกาศสภานโยบายฯ เรื่อง การจัดประเภทหน่วยงานในระบบวิจัยและนวัตกรรม (ฉบับที่ 5) พ.ศ. 2569', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A1, A2', 'สำนัก F1 / F2 / F3', 'ออกตามมาตรา 7 แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (ฉบับที่ 5 พ.ศ. 2569)', 'ปรับปรุงสถานะและชื่อของหน่วยบริหารและจัดการทุนด้านการพัฒนาระดับพื้นที่ (บพท.) เป็นองค์การมหาชนตามพระราชกฤษฎีกาจัดตั้งฯ พ.ศ. 2568 ในบัญชีหน่วยงานประเภทที่ 2 (PMU) | ราชกิจจานุเบกษา 3 ก.พ. 2569', 1, '1b5868e7de391894...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1CCWjmyVCR-BO4GhudnQSfjuOJcDm3A8v/view?usp=drivesdk');
INSERT INTO documents VALUES (37, 'TSRI-F03-01-001', 'TSRI-DOC-0037', 'TSRI-N037', 3, 'หมวดที่ 3', 'พ.ร.บ. ส่งเสริมการใช้ประโยชน์ผลงานวิจัยฯ พ.ศ. 2564.pdf', 'พระราชบัญญัติส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2564', 'ระดับที่ 3: กฎหมายที่เกี่ยวข้อง - พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ (4.1.1.3)', 'A4 (หลัก) / A3 / A5 / B1', 'F4 / F3 / F1 / F5', 'รัฐธรรมนูญ มาตรา 26 และมาตรา 37; เชื่อมโยง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และ พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 มาตรา 28–31', 'ปลดล็อกให้ผู้รับทุนหรือนักวิจัยเป็นเจ้าของผลงานวิจัยที่เกิดจากทุนภาครัฐ (ม.8) กำหนดหน้าที่เปิดเผยผลงาน (ม.7) บริหารจัดการและใช้ประโยชน์ภายใน 2 ปี (ม.12) จัดสรรรายได้ให้นักวิจัย (ม.14) ส่งเสริมเทคโนโลยีที่เหมาะสม (ม.18–19) อนุญาตให้บุคคลภายนอกใช้สิทธิ (ม.20) และมาตรการใช้สิทธิโดยรัฐในภาวะฉุกเฉิน (ม.21) | อ้างอิง: ให้ไว้ 7 พ.ย. 2564 / ราชกิจจานุเบกษา เล่ม 138 ตอนที่ 73 ก หน้า 93–104 วันที่ 8 พ.ย. 2564 (ใช้บังคับ 7 พ.ค. 2565)', 11, '55cb73fafebf252a...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1D2lVgZFf_C1awZXElyfhRsO02zlKlp_H/view?usp=drivesdk');
INSERT INTO documents VALUES (38, 'TSRI-F03-02-001', 'TSRI-DOC-0038', 'TSRI-N038', 3, 'หมวดที่ 3', '1. ส่งเสริมสนับสนุนการนำผลงานวิจัยไปใช้ประโยชน์.pdf', 'ระเบียบสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ ว่าด้วยการส่งเสริมและสนับสนุนการนำผลงานวิจัยและนวัตกรรมเกี่ยวกับเทคโนโลยีที่เหมาะสมไปใช้ประโยชน์ พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4 / A2 / A3', 'F4 / F2 / F3', 'อาศัยอำนาจตามมาตรา 19 วรรคหนึ่ง แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564 และมาตรา 11(9) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562', 'ข้อ 4 กำหนดให้ ''สกสว.'' เป็นหน่วยงานเฉพาะด้านนโยบาย ยุทธศาสตร์ แผนงาน จัดสรรงบประมาณ และติดตามประเมินผลเทคโนโลยีที่เหมาะสม; ข้อ 5 กำหนดให้ บพท., สวก., สนช. และ วช. เป็นหน่วยงานเฉพาะด้านการให้ทุนและจ่ายค่าตอบแทนการใช้ประโยชน์แก่นักวิจัย | อ้างอิง: ประกาศ 27 ธ.ค. 2565 / ราชกิจจานุเบกษา เล่ม 140 ตอนพิเศษ 50 ง วันที่ 3 มี.ค. 2566', 7, 'bcaf4cf1a53c42c2...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1Jn_IB6909cZcUCM_tnVgBFye6KLAeAZi/view?usp=drivesdk');
INSERT INTO documents VALUES (39, 'TSRI-F03-02-002', 'TSRI-DOC-0039', 'TSRI-N039', 3, 'หมวดที่ 3', '2. การขอใช้ประโยชน์ผลงานวิจัยโดยบุคคลภายนอก.pdf', 'ระเบียบสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ ว่าด้วยการขอใช้ประโยชน์ผลงานวิจัยและนวัตกรรมโดยบุคคลภายนอก พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4 / B1', 'F4 / F5', 'อาศัยอำนาจตามมาตรา 20 วรรคสอง แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564 และมาตรา 11(9) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562', 'กำหนดวิธีที่บุคคลภายนอกยื่นคำขอต่อ กสว. (ผ่าน สกสว.) เมื่อเจรจาขอใช้สิทธิจากเจ้าของผลงานแล้วตกลงกันไม่ได้ และเจ้าของมิได้ใช้ประโยชน์ภายใน 2 ปี: แจ้งเจ้าของโต้แย้งใน 30 วัน (ขยายได้ 2 ครั้งๆ ละ 30 วัน) สกสว. สอบสวนและสรุปสำนวนเสนอ กสว. ใน 60 วัน (ขยายได้ 30 วัน) | อ้างอิง: ประกาศ 27 ธ.ค. 2565 / ราชกิจจานุเบกษา เล่ม 140 ตอนพิเศษ 50 ง วันที่ 3 มี.ค. 2566', 5, '4468f1a814f1701d...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1yE-4-Tvlaw62-3cYltuMn-jHsAl02vnT/view?usp=drivesdk');
INSERT INTO documents VALUES (40, 'TSRI-F03-02-003', 'TSRI-DOC-0040', 'TSRI-N040', 3, 'หมวดที่ 3', '3. ระเบียบว่าด้วยการอุทธรณ์.pdf', 'ระเบียบสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ และคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการอุทธรณ์และการพิจารณาอุทธรณ์ตามกฎหมายว่าด้วยการส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1 / A4', 'F5 / F4', 'อาศัยอำนาจตามมาตรา 13 วรรคสี่ และมาตรา 20 วรรคสี่ แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564 ประกอบมาตรา 11(9) และมาตรา 41(9) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562', 'ยื่นอุทธรณ์ต่อ สกสว. ภายใน 30 วัน (แก้ไขคำอุทธรณ์ที่ไม่สมบูรณ์ใน 15 วัน); ข้อ 6 แบ่งผู้มีอำนาจวินิจฉัยอุทธรณ์ 3 ระดับ: (1) ผู้อำนวยการ สกสว. วินิจฉัยคำสั่งของพนักงาน สกสว., (2) กสว. วินิจฉัยคำสั่งไม่อนุญาตขยายเวลา ม.13 หรือคำสั่งของ ผู้อำนวยการ สกสว. (ใน 30 วัน), (3) สภานโยบาย วินิจฉัยคำสั่งอนุญาตให้บุคคลภายนอกใช้ประโยชน์ ม.20 (ใน 60 วัน) | อ้างอิง: ประกาศ 27 ธ.ค. 2565 / ราชกิจจานุเบกษา เล่ม 140 ตอนพิเศษ 50 ง วันที่ 3 มี.ค. 2566', 5, '3a11e967b097ae87...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/12JYplaUehsh93S9BZwOWqvEazh02eAhf/view?usp=drivesdk');
INSERT INTO documents VALUES (41, 'TSRI-F03-03-001', 'TSRI-DOC-0041', 'TSRI-N041', 3, 'หมวดที่ 3', '1. การใช้ประโยชน์ผลงานที่ไม่สมควรเป็นของบุคคลใด.pdf', 'ระเบียบคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการใช้ประโยชน์ผลงานวิจัยและนวัตกรรมซึ่งไม่สมควรให้เป็นของบุคคลใดหรือองค์กรใดเป็นการเฉพาะ พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4 / A1', 'F4 / F1', 'อาศัยอำนาจตามมาตรา 4 วรรคสอง แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'กำกับงานวิจัยตาม ม.4(4) ที่เป็นประโยชน์อย่างยิ่งต่อมวลมนุษยชาติหรือประชาชนชาวไทยโดยรวม หรือเป็นพื้นฐานสำคัญของการวิจัยอื่น (ซึ่งหน่วยงานรัฐประกาศกำหนดโดยความเห็นชอบของ กสว. ก่อนทำสัญญาให้ทุน): ให้ผู้ให้ทุนบริหารจัดการและเผยแพร่ให้ประชาชนหรือหน่วยงานใช้ประโยชน์ได้อย่างกว้างขวางและเท่าเทียม | อ้างอิง: ประกาศ 23 พ.ค. 2565 / ราชกิจจานุเบกษา เล่ม 139 ตอนพิเศษ 147 ง วันที่ 24 มิ.ย. 2565', 5, 'b4b798ad198d1edf...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1grghIYIkuLNjEZRn9GDaq4beC8XxVyQO/view?usp=drivesdk');
INSERT INTO documents VALUES (42, 'TSRI-F03-03-002', 'TSRI-DOC-0042', 'TSRI-N042', 3, 'หมวดที่ 3', '2. การกำหนดข้อสัญญาที่เป็นสาระสำคัญ.pdf', 'ระเบียบคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการกำหนดข้อสัญญาที่เป็นสาระสำคัญของสัญญาให้ทุน พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A3 / A4 / B1', 'F3 / F4 / F5', 'อาศัยอำนาจตามมาตรา 6 วรรคหนึ่ง แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'กำหนดรายการข้อสัญญาบังคับในสัญญาให้ทุนและสัญญาจ้างช่วงงานวิจัยบางส่วน (หากฝ่าฝืนเป็นโมฆะเฉพาะส่วนตาม ม.6 วรรคสาม-สี่): หน้าที่เปิดเผยผลงาน การขอเป็นเจ้าของ การบริหารจัดการ การจัดสรรรายได้ การโอนผลงาน สิทธิใช้เพื่อวิจัยของรัฐ (ม.16) และมาตรการฉุกเฉิน (ม.21); ข้อ 4 ห้ามมีข้อสัญญาให้ผู้รับทุนหรือนักวิจัยแบ่งปันรายได้หรือประโยชน์แก่ผู้ให้ทุน! | อ้างอิง: ประกาศ 23 พ.ค. 2565 / ราชกิจจานุเบกษา เล่ม 139 ตอนพิเศษ 147 ง วันที่ 24 มิ.ย. 2565', 2, '0e152b0fecdc3b0d...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1TVxA_G4EdC0RUxqd-EWnmQXteWVgBIzw/view?usp=drivesdk');
INSERT INTO documents VALUES (43, 'TSRI-F03-03-003', 'TSRI-DOC-0043', 'TSRI-N043', 3, 'หมวดที่ 3', '3. การเปิดเผยความเป็นเจ้าของการโอนผลงาน.pdf', 'ระเบียบคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการเปิดเผย ความเป็นเจ้าของ และการโอนผลงานวิจัยและนวัตกรรม พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4 / A3', 'F4 / F3', 'อาศัยอำนาจตามมาตรา 7 วรรคหนึ่ง มาตรา 8 วรรคสี่ และมาตรา 15 วรรคหนึ่งและวรรคสาม แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'หัวหน้าโครงการเปิดเผยต่อผู้รับทุนโดยเร็ว ผู้รับทุนเปิดเผยต่อผู้ให้ทุนภายใน 30 วันนับแต่ได้รับแจ้ง และไม่เกิน 90 วันนับแต่วันสิ้นสุดโครงการวิจัย; ยื่นขอเป็นเจ้าของพร้อมแผนใช้ประโยชน์ใน 90 วัน (ขยายได้ 2 ครั้งๆ ละ 30 วัน); ผู้ให้ทุนออกหนังสือแสดงความเป็นเจ้าของใน 30 วัน; การโอนผลงานต้องได้รับความยินยอมเว้นแต่โอนให้นิติบุคคลบริหารจัดการผลงาน (TLO/Holding) ที่ผู้รับทุนมอบหมาย | อ้างอิง: ประกาศ 23 พ.ค. 2565 / ราชกิจจานุเบกษา เล่ม 139 ตอนพิเศษ 147 ง วันที่ 24 มิ.ย. 2565', 8, '52bc551b04852bd9...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/12cbtfnkS3PtVUczxXWlKPEEUXuzN2wTu/view?usp=drivesdk');
INSERT INTO documents VALUES (44, 'TSRI-F03-03-004', 'TSRI-DOC-0044', 'TSRI-N044', 3, 'หมวดที่ 3', '4. การบริหารจัดการ การใช้ประโยชน์ การรายงาน.pdf', 'ระเบียบคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการบริหารจัดการ การใช้ประโยชน์ผลงานวิจัยและนวัตกรรม และการรายงาน พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4 / A5', 'F4 / F1', 'อาศัยอำนาจตามมาตรา 12 วรรคหนึ่ง และมาตรา 13 วรรคสอง แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'กำหนดหลักเกณฑ์การบริหารจัดการผลงาน การยื่นความคุ้มครอง IP และการรายงานผลต่อผู้ให้ทุนอย่างน้อยปีละ 1 ครั้ง (ภายในระยะเวลาไม่น้อยกว่า 5 ปีนับแต่วันที่เป็นเจ้าของ); การอนุญาตให้ใช้สิทธิแต่เพียงผู้เดียว (Exclusive License) แก่ผู้ไม่มีฐานการผลิตหรือประกอบธุรกิจในไทยต้องแจ้งผู้ให้ทุนล่วงหน้าไม่น้อยกว่า 30 วัน; กำหนดเกณฑ์ประเมิน ''ความพยายามในการใช้ประโยชน์'' เพื่อขอขยายเวลาตาม ม.13 | อ้างอิง: ประกาศ 23 พ.ค. 2565 / ราชกิจจานุเบกษา เล่ม 139 ตอนพิเศษ 147 ง วันที่ 24 มิ.ย. 2565', 7, '8a9ecf5bde32f002...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/19Ze4_FfUrRudSaNYUoKhKZl24wVCmivc/view?usp=drivesdk');
INSERT INTO documents VALUES (45, 'TSRI-F03-03-005', 'TSRI-DOC-0045', 'TSRI-N045', 3, 'หมวดที่ 3', '5. หลักเกณฑ์เงื่อนไขการจัดสรรรายได้นักวิจัย.pdf', 'ระเบียบคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยหลักเกณฑ์และเงื่อนไขในการจัดสรรรายได้ให้แก่นักวิจัย และการนำรายได้ไปใช้สำหรับการวิจัยและสร้างนวัตกรรม พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4 / A3', 'F4 / F3', 'อาศัยอำนาจตามมาตรา 14 วรรคหนึ่งและวรรคห้า แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'ผู้รับทุนที่เป็นหน่วยงานของรัฐหรือสถาบันอุดมศึกษาต้องออกระเบียบหรือข้อบังคับจัดสรรรายได้หลังหักค่าใช้จ่ายให้แก่นักวิจัย และกันรายได้ส่วนหนึ่งไว้ใช้สำหรับการวิจัยและสร้างนวัตกรรม โดยต้องดำเนินการให้แล้วเสร็จภายใน 180 วันนับแต่วันที่ระเบียบนี้ใช้บังคับ และนำส่งให้ สกสว. ทราบภายใน 60 วัน | อ้างอิง: ประกาศ 23 พ.ค. 2565 / ราชกิจจานุเบกษา เล่ม 139 ตอนพิเศษ 147 ง วันที่ 24 มิ.ย. 2565', 3, '7908dd96de3024c1...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1ru2WwGii7ey6vYZiJ8y4_y_V7aj6oZZV/view?usp=drivesdk');
INSERT INTO documents VALUES (46, 'TSRI-F03-03-006', 'TSRI-DOC-0046', 'TSRI-N046', 3, 'หมวดที่ 3', '6. การจ่ายค่าตอบแทนการใช้ประโยชน์แก่นักวิจัย.pdf', 'ระเบียบคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการจ่ายค่าตอบแทนการใช้ประโยชน์แก่นักวิจัยที่ดำเนินการอันก่อให้เกิดประโยชน์ต่อการนำผลงานวิจัยและนวัตกรรมเกี่ยวกับเทคโนโลยีที่เหมาะสมไปใช้ประโยชน์ พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4 / A2', 'F4 / F2', 'อาศัยอำนาจตามมาตรา 19 วรรคสอง แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'กำหนดหลักเกณฑ์ให้หน่วยงานเฉพาะ (ตาม ม.19 วรรคหนึ่ง) จ่ายเงินค่าตอบแทนการใช้ประโยชน์ (Utilization Compensation) แก่นักวิจัยที่ถ่ายทอดเทคโนโลยีที่เหมาะสมแก่เกษตรกร ชุมชน วิสาหกิจชุมชน วิสาหกิจเพื่อสังคม หรือผู้ด้อยโอกาส: พิจารณาอนุมัติคำขอภายใน 60 วัน (ขยายได้ไม่เกิน 2 ครั้งๆ ละ 30 วัน) | อ้างอิง: ประกาศ 22 ส.ค. 2565 / ราชกิจจานุเบกษา เล่ม 139 ตอนพิเศษ 235 ง วันที่ 3 ต.ค. 2565', 4, '57db23e0b2ed6684...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1ZJRDozgyiLW9lhZMzqYLw1dtSvpN2EYK/view?usp=drivesdk');
INSERT INTO documents VALUES (47, 'TSRI-F03-04-001', 'TSRI-DOC-0047', 'TSRI-N047', 3, 'หมวดที่ 3', '1. หลักเกณฑ์เงื่อนไขการให้ทุนหน่วยงานรัฐ.pdf', 'ประกาศสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ เรื่อง หลักเกณฑ์และเงื่อนไขการให้ทุนของหน่วยงานของรัฐตามกฎหมายว่าด้วยการส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A3 / A4 / B3', 'F3 / F4 / F5', 'อาศัยอำนาจตามมาตรา 3 วรรคสอง แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564 และมาตรา 11(9) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562', 'ตีความขอบเขต ''การให้ทุนของหน่วยงานของรัฐ'' ตาม ม.3: ใช้บังคับกับการให้ทุนวิจัยและนวัตกรรมทุกแหล่งเงินของรัฐ แต่ไม่รวมถึง (1) การให้ทุนการศึกษา และ (2) การจัดซื้อจัดจ้างหรือการจ้างที่ปรึกษาตาม พ.ร.บ.การจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 (หมวด 12: TSRI-DOC-0104) | อ้างอิง: ประกาศ 27 ธ.ค. 2565 / ราชกิจจานุเบกษา เล่ม 140 ตอนพิเศษ 50 ง วันที่ 3 มี.ค. 2566', 2, 'cf7cc60455090747...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1iy7Dg5msdS6YCYxsCe2BFy6dWuXzBjLD/view?usp=drivesdk');
INSERT INTO documents VALUES (48, 'TSRI-F03-04-002', 'TSRI-DOC-0048', 'TSRI-N048', 3, 'หมวดที่ 3', '2. สิทธิหน้าที่คนต่างด้าว.pdf', 'ประกาศสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ เรื่อง สิทธิและหน้าที่ของคนต่างด้าวซึ่งมีถิ่นที่อยู่ในราชอาณาจักรไทยที่จะได้รับการส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4 / B1', 'F4 / F5', 'อาศัยอำนาจตามมาตรา 11 แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'กำหนดเงื่อนไขให้คนต่างด้าวที่มีถิ่นที่อยู่ในไทยมีสิทธิเป็นเจ้าของผลงานวิจัยได้ แต่ต้องใช้ประโยชน์เพื่อพัฒนาการผลิตหรือเศรษฐกิจภายในประเทศไทยเป็นหลัก; กรณีนิติบุคคลไทยเปลี่ยนสภาพเป็นคนต่างด้าวและขาดคุณสมบัติ ต้องโอนผลงานคืนให้ผู้ให้ทุนหรือบุคคลที่มีคุณสมบัติภายใน 90 วัน | อ้างอิง: ประกาศ 27 ธ.ค. 2565 / ราชกิจจานุเบกษา เล่ม 140 ตอนพิเศษ 50 ง วันที่ 3 มี.ค. 2566', 3, '0431a4a28593f4ff...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1AjsKf8g0Uf_q9mgInNQsoWF52CIc-jk2/view?usp=drivesdk');
INSERT INTO documents VALUES (49, 'TSRI-F03-04-003', 'TSRI-DOC-0049', 'TSRI-N049', 3, 'หมวดที่ 3', '3. การรายงานผลงานผู้ให้ทุนเป็นเจ้าของ.pdf', 'ประกาศสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ เรื่อง หลักเกณฑ์ วิธีการ และเงื่อนไขเกี่ยวกับการรายงานผลงานวิจัยและนวัตกรรมที่ผู้ให้ทุนเป็นเจ้าของผลงานวิจัยและนวัตกรรม พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'A4 / A5', 'F4 / F1', 'อาศัยอำนาจตามมาตรา 17 วรรคสาม แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'กำหนดให้ผู้ให้ทุนที่เป็นเจ้าของผลงานวิจัย (ตาม ม.9 หรือ ม.12 วรรคสี่ หรือ ม.13) ต้องรายงานบัญชีผลงานและสถานะการใช้หรือไม่ใช้ประโยชน์ต่อ กสว. (ผ่านระบบข้อมูลของ สกสว.) อย่างน้อยปีละ 1 ครั้ง พร้อมเปิดเผยต่อสาธารณชนทางระบบอิเล็กทรอนิกส์ เพื่อให้ กสว. พิจารณาสั่งโอนหรืออนุญาตให้ผู้อื่นใช้สิทธิเพื่อประโยชน์สาธารณะตาม ม.17 วรรคหนึ่ง | อ้างอิง: ประกาศ 27 ธ.ค. 2565 / ราชกิจจานุเบกษา เล่ม 140 ตอนพิเศษ 50 ง วันที่ 3 มี.ค. 2566', 2, '7fb24e5bbd431e69...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1dufq31p3vKNEiaLevEqNTYHGMJjLs3uY/view?usp=drivesdk');
INSERT INTO documents VALUES (50, 'TSRI-F03-05-001', 'TSRI-DOC-0050', 'TSRI-N050', 3, 'หมวดที่ 3', 'การจ่ายค่าตอบแทนนักวิจัยที่ก่อประโยชน์ต่อการนำผลงานไปใช้.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง การจ่ายค่าตอบแทนแก่นักวิจัยที่ดำเนินการอันก่อให้เกิดประโยชน์ต่อการนำผลงานวิจัยและนวัตกรรมเกี่ยวกับเทคโนโลยีที่เหมาะสมไปใช้ประโยชน์ พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง คู่มือปฏิบัติงาน และ SOP (4.1.1.2)', 'A4 / A2', 'F4 / F2', 'อาศัยอำนาจตามข้อ 5 วรรคสอง และข้อ 13 วรรคหนึ่ง แห่งระเบียบ กสว. ว่าด้วยการจ่ายค่าตอบแทนการใช้ประโยชน์ฯ พ.ศ. 2565 (ตาม ม.19 วรรคสอง)', 'ขยายกลไกการจ่ายค่าตอบแทนการใช้ประโยชน์เทคโนโลยีที่เหมาะสมให้ครอบคลุมนักวิจัยที่สร้างผลงานจากทุนวิจัยก่อน พ.ร.บ. ใช้บังคับ หรือไม่ได้รับทุนตาม พ.ร.บ. นี้ แต่ได้นำผลงานเทคโนโลยีที่เหมาะสมไปถ่ายทอดและขยายผลในชุมชนจนเกิดผลสัมฤทธิ์ตามมาตรา 18 | อ้างอิง: ประกาศ 18 ต.ค. 2565 / ราชกิจจานุเบกษา เล่ม 139 ตอนพิเศษ 271 ง วันที่ 18 พ.ย. 2565', 2, 'fa22d46e6169aaa2...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/10eongz4ZHcdYTT_xK4x7y9vgx8itGlj_/view?usp=drivesdk');
INSERT INTO documents VALUES (51, 'TSRI-F03-06-001', 'TSRI-DOC-0051', 'TSRI-N051', 3, 'หมวดที่ 3', 'แนวทางการประกาศใช้พรบแก่คนต่างด้าวไม่อยู่ในไทย.pdf', 'แนวทางของสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ เกี่ยวกับการประกาศให้ใช้บังคับพระราชบัญญัติส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2564 แก่คนต่างด้าวซึ่งไม่มีถิ่นที่อยู่ในราชอาณาจักรไทย พ.ศ. 2565', 'ระดับที่ 2: กฎหมายลำดับรอง คู่มือปฏิบัติงาน และ SOP (4.1.1.2)', 'A4 / B1', 'F4 / F5', 'อาศัยอำนาจตามมาตรา 4(2) แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'กำหนดขั้นตอนการขออนุมัติยกเว้นเป็นรายกรณีตาม ม.4(2) ให้ใช้ พ.ร.บ. แก่คนต่างด้าวที่ไม่มีถิ่นที่อยู่ในไทย (เช่น โครงการวิจัยร่วมนานาชาติ): หน่วยงานผู้ให้ทุนต้องเสนอเหตุผลความจำเป็น ความคุ้มค่า และการถ่ายทอดเทคโนโลยีต่อ กสว. (ผ่าน สกสว.) เพื่อกลั่นกรองก่อนเสนอสภานโยบายประกาศกำหนดเป็นรายกรณี | อ้างอิง: ประกาศ ณ วันที่ 29 ธ.ค. 2565', 1, '4feac9337786e254...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1suHHZbJdvmA_qPsIxNIgP0HbZSLR4IhT/view?usp=drivesdk');
INSERT INTO documents VALUES (52, 'TSRI-F04-00-001', 'TSRI-DOC-0052', 'TSRI-N052', 4, 'หมวดที่ 4', '1.ประกาศแต่งตั้งผอ. สมปอง.pdf', 'ประกาศคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง แต่งตั้งผู้อำนวยการ สำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม (ลงวันที่ 24 ตุลาคม 2567)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายเลขานุการคณะกรรมการ / HR)', 'มาตรา 48 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และประกาศ กสว. เรื่อง หลักเกณฑ์และวิธีการสรรหาและแต่งตั้งผู้อำนวยการ สกสว. พ.ศ. 2563 (มติ กสว. ครั้งที่ 10/2567)', 'แต่งตั้งผู้อำนวยการ สกสว. ให้มีวาระการดำรงตำแหน่ง 4 ปี นับตั้งแต่วันที่ 1 พฤศจิกายน 2567 เป็นต้นไป เพื่อเป็นผู้บังคับบัญชาสูงสุดและบริหารกิจการของสำนักงานตามมาตรา 50', 1, '4aeba5ea76e2bbcb...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1O2rrd_v-qpJEkbXSVhmlg_q9kxFpgiUY/view?usp=drivesdk');
INSERT INTO documents VALUES (53, 'TSRI-F04-00-002', 'TSRI-DOC-0053', 'TSRI-N053', 4, 'หมวดที่ 4', '2.คำสั่งสกสว.ที่ บค. 5_2568 แต่งตั้งรองผู้อำนวยการ สกสว..pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 5/2568 (สั่ง ณ วันที่ 21 กุมภาพันธ์ 2568)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 49 ประกอบมาตรา 50(4) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 และมติ กสว. ครั้งที่ 11/2567', 'แต่งตั้งผู้บริหารระดับสูงของสำนักงานตามจำนวนที่ กสว. กำหนด เพื่อช่วยผู้อำนวยการปฏิบัติงานตามที่ได้รับมอบหมาย ตั้งแต่วันที่ 21 กุมภาพันธ์ 2568 เป็นต้นไป', 1, '492a8a7317057cce...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1Z6vi3lnTx1K5UGO5N0xz2irZ8OL9-zBd/view?usp=drivesdk');
INSERT INTO documents VALUES (54, 'TSRI-F04-00-003', 'TSRI-DOC-0054', 'TSRI-N054', 4, 'หมวดที่ 4', '3.คำสั่งสกสว.ที่ บค. 6_2568 มอบหมายรองผู้อำนวยการ.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 6/2568 เรื่อง การมอบหมายกำกับดูแลส่วนงานตามโครงสร้างใหม่ (สั่ง ณ วันที่ 21 กุมภาพันธ์ 2568)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายกลยุทธ์องค์กร / HR)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 และมติ อนก. ครั้งที่ 1/2568 เมื่อวันที่ 10 มกราคม 2568', 'แบ่งสายการกำกับดูแลส่วนงานหลักทั้ง 5 สำนัก (F1 สำนักยุทธศาสตร์ แผน ติดตามและประเมินผล, F2 สำนักกลยุทธ์งบประมาณและโครงสร้างพื้นฐานฯ, F3 สำนักกลยุทธ์พัฒนากองทุนและระบบนิเวศฯ, F4 สำนักกลยุทธ์พัฒนาความร่วมมือนานาชาติและใช้ประโยชน์งานวิจัยฯ, F5 สำนักบริหารและพัฒนาองค์กร + โครงการวิจัย Ongoing) และหน่วยภารกิจ Intelligence Units (IU)', 2, 'de9f79d701c12720...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/13C9F4t3hq3Z0gYFFiZL31w9Qv4dmc-ny/view?usp=drivesdk');
INSERT INTO documents VALUES (55, 'TSRI-F04-00-004', 'TSRI-DOC-0055', 'TSRI-N055', 4, 'หมวดที่ 4', '4.คำสั่งสกสว. ที่ บค.7_2569 เรื่อง แต่งตั้งบุคคลตามโครงสร้างตำแหน่ง.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 7/2569 เรื่อง แต่งตั้งบุคคลตามโครงสร้างตำแหน่ง พ.ศ. 2569 (สั่ง ณ วันที่ 25 มิถุนายน 2569, 9 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 และมติ อนก. ครั้งที่ 5/2569 เมื่อวันที่ 8 พฤษภาคม 2569', 'ยกเลิกคำสั่งที่ บค. 7/2568 และ บค. 8/2568 และจัดวางบุคลากรทั้งหมดเข้าสู่ตำแหน่งตามโครงสร้างใหม่ พ.ศ. 2569 ครบทั้ง 5 สำนัก (F1–F5), 6 หน่วยภารกิจ (IU1–IU6) และหน่วยตรวจสอบภายใน (IA)', 9, '3b99883c4e246551...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1A5cMgxLTFyqxiibYKoErbbT44O8QFD-O/view?usp=drivesdk');
INSERT INTO documents VALUES (56, 'TSRI-F04-00-005', 'TSRI-DOC-0056', 'TSRI-N056', 4, 'หมวดที่ 4', '5.คำสั่ง สกสว. ที่บค. 8_2569 เรื่อง  แก้ไขรายชื่อบุคคลและชื่อตำแหน่ง.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 8/2569 เรื่อง แก้ไขรายชื่อบุคคลและชื่อตำแหน่ง ในคำสั่งแต่งตั้งบุคคลตามโครงสร้างตำแหน่ง พ.ศ. 2569 (สั่ง ณ วันที่ 9 กรกฎาคม 2569)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'ปรับปรุงแก้ไขรายการตำแหน่งในฝ่ายขับเคลื่อนการใช้ประโยชน์และการสร้างผลกระทบ (F4.2) และตำแหน่งผู้อำนวยการสำนักบริหารและพัฒนาองค์กร (F5) ให้มีผลย้อนหลังตั้งแต่วันที่ 25 มิถุนายน 2569', 1, '619f2f3e20c747a5...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1dGbvx95UPaVv0V4NrHWvTJKqBoqTxXZb/view?usp=drivesdk');
INSERT INTO documents VALUES (57, 'TSRI-F04-00-006', 'TSRI-DOC-0057', 'TSRI-N057', 4, 'หมวดที่ 4', '6.คำสั่ง สกสว. ที่บค. 9_2569 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 9/2569 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร (สั่ง ณ วันที่ 6 กรกฎาคม 2569)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'แต่งตั้งผู้ผ่านการประเมินผลการปฏิบัติงานในตำแหน่งรักษาการครบ 6 เดือน ให้ดำรงตำแหน่งผู้อำนวยการสำนักกลยุทธ์พัฒนากองทุนและระบบนิเวศ ววน. (F3) และผู้อำนวยการหน่วยภารกิจยุทธศาสตร์ ววน. การพัฒนาวิทยาศาสตร์ เทคโนโลยี การวิจัยและนวัตกรรม (IU5) ตั้งแต่วันที่ 14 พฤษภาคม 2569', 1, '3bd4bc456a7dd976...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/13v0v-4QAz7-1F_UHVdb9XFLDXUbB9G9X/view?usp=drivesdk');
INSERT INTO documents VALUES (58, 'TSRI-F04-00-007', 'TSRI-DOC-0058', 'TSRI-N058', 4, 'หมวดที่ 4', '7.คำสั่งสกสว. ที่ บค.10_2569 แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 10/2569 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร (สั่ง ณ วันที่ 16 กรกฎาคม 2569)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'แต่งตั้งผู้อำนวยการหน่วยภารกิจยุทธศาสตร์ ววน. การพัฒนากำลังคนและสถาบัน (IU6) ตั้งแต่วันที่ 1 มิถุนายน 2569 เป็นต้นไป', 1, '30dc36ed53164c7a...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1eApXgc2u5DUVqWSAePVBW4v5RVRzaPP9/view?usp=drivesdk');
INSERT INTO documents VALUES (59, 'TSRI-F04-00-008', 'TSRI-DOC-0059', 'TSRI-N059', 4, 'หมวดที่ 4', '8.คำสั่ง บค. 13_69 แต่งตั้งบริหาร.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 13/2569 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร (สั่ง ณ วันที่ 7 ตุลาคม 2569)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'แต่งตั้งผู้อำนวยการสำนักกลยุทธ์งบประมาณและโครงสร้างพื้นฐาน ระบบ ววน. (F2) ต่อเนื่องตามสัญญาจ้างรายปีหลังอายุครบ 60 ปีบริบูรณ์ ตั้งแต่วันที่ 1 ตุลาคม 2569 เป็นต้นไป', 1, 'e6715b39d58c5cbb...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/17Etm9xsla_OKi1UfjGyEOWUJ3sprMh3M/view?usp=drivesdk');
INSERT INTO documents VALUES (60, 'TSRI-F04-00-009', 'TSRI-DOC-0060', 'TSRI-N060', 4, 'หมวดที่ 4', '9.คำสั่งสกสว. ที่ บค. 14_2569 แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 14/2569 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร (สั่ง ณ วันที่ 21 ตุลาคม 2569)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'แต่งตั้งผู้บริหารระดับหน่วยภารกิจ สังกัดหน่วยภารกิจฐานข้อมูลและระบบดิจิทัล (IU1) ตั้งแต่วันที่ 1 ตุลาคม 2569 เป็นต้นไป', 1, '036f73ecb56034e0...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1lNhNOUczXiw2-Xp9IoePIiyz59bmiV04/view?usp=drivesdk');
INSERT INTO documents VALUES (61, 'TSRI-F04-00-010', 'TSRI-DOC-0061', 'TSRI-N061', 4, 'หมวดที่ 4', '9.ระเบียบว่าด้วยการกำหนดตำแหน่ง ค่าจ้างฯ พ.ศ. 2569.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการกำหนดตำแหน่ง อัตราเงินเดือน ค่าจ้าง และเงินอื่นของพนักงานและลูกจ้าง สกสว. พ.ศ. 2569 (ประกาศ 25 พ.ค. 2569, 6 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B2, B1 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 47 ประกอบมาตรา 25 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 11, 12 และ 15 แห่งข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (มติ อนก. ครั้งที่ 5/2569 วันที่ 8 พ.ค. 2569; ยกเลิกระเบียบฯ พ.ศ. 2566)', 'กำหนดโครงสร้างระดับชั้นงาน (Level 1 ถึง Level 8) และระดับชั้นงานย่อย (Sub-Level 1A ถึง 8A) พร้อมบัญชีเงินเดือน พ.ศ. 2569 แยกสายวิชาการ (เจ้าหน้าที่ทั่วไป 16,000–26,300 บาท ถึงผู้ทรงคุณวุฒิพิเศษ 141,000–225,000 บาท) และสายวิชาชีพ (ระดับ 1–5)', 6, 'cb096164473fa549...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1Du2AbgamXxv9VanfS5ZOuQX46iNZ_zY9/view?usp=drivesdk');
INSERT INTO documents VALUES (62, 'TSRI-F04-00-011', 'TSRI-DOC-0062', 'TSRI-N062', 4, 'หมวดที่ 4', '10.ประกาศ สกสว. เรื่อง หลักเกณฑ์การปรับเข้าสู่ตำแหน่งฯ.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์การปรับเข้าสู่ตำแหน่งและบัญชีเงินเดือน พ.ศ. 2569 (ประกาศ ณ วันที่ 24 มิถุนายน 2569)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B2, B1 (F5 ฝ่ายทรัพยากรบุคคล)', 'อาศัยอำนาจตามข้อ 5 และข้อ 6 ของระเบียบ อนก. ว่าด้วยการกำหนดตำแหน่ง อัตราเงินเดือน ค่าจ้าง และเงินอื่นฯ พ.ศ. 2569 (ยกเลิกประกาศฯ ลงวันที่ 13 พ.ย. 2566)', 'กำหนดตารางเทียบโอนจากระบบเดิม (Sub-Grade 1A–6A) ไปสู่ระบบใหม่ (Level 1–8 / Sub-Level 1A–8A) ห้ามทำให้เงินเดือน ค่าจ้าง และเงินประจำตำแหน่งลดต่ำกว่าเดิม และเปิดให้พิจารณาปรับ Sub-Level สูงขึ้นได้อีก 1 ระดับ (แต่เมื่อเทียบโอนแล้วต้องไม่เกินระดับชั้นงาน 6)', 3, 'd13cc0737bf82708...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1-pcxxq8hRghUIoZrA_TVmX7EoFrc-w2_/view?usp=drivesdk');
INSERT INTO documents VALUES (63, 'TSRI-F04-00-012', 'TSRI-DOC-0063', 'TSRI-N063', 4, 'หมวดที่ 4', '11.ประกาศ สกสว. เรื่อง ส่วนงาน ของ สกสว.2569.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง ส่วนงานของสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม พ.ศ. 2569 (ประกาศ ณ วันที่ 19 มิถุนายน 2569)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2, A1–A5 (F5 และทุกสำนัก F1–F5)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 14/1 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (แก้ไขเพิ่มเติม ฉ.2 พ.ศ. 2566) และมติ อนก. ครั้งที่ 1/2568 (ยกเลิกประกาศส่วนงาน 29 ก.ย. 2566)', 'จัดแบ่งส่วนงานทางการของ สกสว. เป็น 12 ส่วนงานหลัก: 5 สำนัก (F1–F5 สำนักละ 4 ฝ่าย/กลุ่มงาน โดย F5 มี 4 กลุ่มงาน 10 ฝ่าย), 6 หน่วยภารกิจ (IU1 ฐานข้อมูลดิจิทัล, IU2 สนับสนุนงานอำนวยการ, IU3 พัฒนาเศรษฐกิจไทย, IU4 ยกระดับสังคม/สิ่งแวดล้อม, IU5 พัฒนา ววน., IU6 พัฒนากำลังคนและสถาบัน) และ 1 หน่วยตรวจสอบภายใน (IA)', 3, '2394f01dd530744d...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1ZD7wWNPLdbvRrU66XnEmjGdEqpwZo4q7/view?usp=drivesdk');
INSERT INTO documents VALUES (64, 'TSRI-F04-00-013', 'TSRI-DOC-0064', 'TSRI-N064', 4, 'หมวดที่ 4', '12.ภาพโครงสร้าง.pdf', 'แผนผังโครงสร้างองค์กรสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม (Organization Chart พ.ศ. 2569)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B4 (F5 ฝ่ายกลยุทธ์องค์กร & IA)', 'สอดคล้องกับประกาศ สกสว. เรื่อง ส่วนงานของ สกสว. พ.ศ. 2569 (TSRI-DOC-0063) และ พ.ร.บ.สภานโยบายฯ มาตรา 46, 48, 50 และ 63', 'แสดงสายการบังคับบัญชาและการกำกับดูแล: คณะกรรมการตรวจสอบกำกับหน่วยตรวจสอบภายใน (IA) เป็นอิสระ; ผู้อำนวยการ สกสว. และผู้บริหารกำกับดูแล 5 สำนักหลัก (F1–F5) และ 6 หน่วยภารกิจเชิงลึก (IU1–IU6)', 1, '182b928de5cb87e8...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/14pXIZ8eBTnygdPhAX8U6Ow0w-P4Vj39h/view?usp=drivesdk');
INSERT INTO documents VALUES (65, 'TSRI-F04-00-014', 'TSRI-DOC-0065', 'TSRI-N065', 4, 'หมวดที่ 4', 'คำสั่งสกสว ที่ บค. 26_2568 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ บค. 26/2568 เรื่อง แต่งตั้งบุคคลให้ดำรงตำแหน่งบริหาร (สั่ง ณ วันที่ 26 สิงหาคม 2568)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 18 ของข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563', 'แต่งตั้งผู้บริหารระดับผู้อำนวยการสำนักและผู้ช่วยผู้อำนวยการสำนักใน F1 (4 ราย), F2 (1 ราย) และ F5 (3 ราย) หลังผ่านการประเมินผลการปฏิบัติงานในตำแหน่งรักษาการครบ 6 เดือน โดยมีผลตั้งแต่วันที่ 1 พฤษภาคม 2568', 2, 'c3d3f438e88ea56f...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/19va2yfWl_2ohggCVD_WJUe4AhH53QKTI/view?usp=drivesdk');
INSERT INTO documents VALUES (66, 'TSRI-F05-00-001', 'TSRI-DOC-0066', 'TSRI-N066', 5, 'หมวดที่ 5', '1. ข้อบังคับ อนก บริหารงานบุคคล.pdf', 'ข้อบังคับคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการบริหารงานบุคคล สกสว. พ.ศ. 2563 (ประกาศ 30 ก.ย. 2563, 12 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล 5.3.2)', 'มาตรา 47 ประกอบมาตรา 25(4) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (มติ อนก. ครั้งที่ 6/2563 วันที่ 7 ส.ค. 2563; ยกเลิกข้อบังคับ สกว. พ.ศ. 2548)', 'กฎหมายแม่บทระดับสำนักงานด้านการบริหารทรัพยากรบุคคล (55 ข้อ): กำหนดนิยามพนักงาน ลูกจ้าง (สัญญาไม่เกิน 1 ปี) และเจ้าหน้าที่ของรัฐ, อัตรากำลัง, การบรรจุแต่งตั้ง, การประเมินผล, การพ้นจากงาน (อายุครบ 60 ปีบริบูรณ์เมื่อสิ้นปีงบประมาณ), สวัสดิการ และการรักษาวินัย', 12, '753055d3ba5b0fd1...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/14bSrZw55PRlxT-P_CfQyrfBlHSzwQy8F/view?usp=drivesdk');
INSERT INTO documents VALUES (67, 'TSRI-F05-00-002', 'TSRI-DOC-0067', 'TSRI-N067', 5, 'หมวดที่ 5', '2. ข้อบังคับ อนก บริหารงานบุคคล (ฉบับ 2).pdf', 'ข้อบังคับคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการบริหารงานบุคคล สกสว. (ฉบับที่ 2) พ.ศ. 2566 (ประกาศ 16 พ.ค. 2566, 4 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2, B1 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 47 ประกอบมาตรา 25 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (มติ อนก. ครั้งที่ 3/2566 เมื่อวันที่ 7 เมษายน 2566)', 'แก้ไขข้อ 11 (ให้สำนักงานทบทวนบัญชีเงินเดือนรายงานต่อ อนก. ทุก 5 ปี), เพิ่มหมวด 2/1 โครงสร้างและกรอบอัตรากำลัง (ข้อ 14–14/2 ให้ อนก. กำหนดโครงสร้างส่วนงานและกรอบอัตรากำลัง) และแก้ไขข้อ 15 แบ่งกลุ่มตำแหน่งเป็น 7 ประเภท (บริหาร, เชี่ยวชาญ, จัดการ, อาวุโสวิชาการ/วิชาชีพ, วิชาการ/วิชาชีพ, สนับสนุน, เจ้าหน้าที่ทั่วไป)', 4, '7d966c789d6f5c84...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1ZM7bd-OCGoPMwYB5K_x_Oj9nXSIi1yXb/view?usp=drivesdk');
INSERT INTO documents VALUES (68, 'TSRI-F05-00-003', 'TSRI-DOC-0068', 'TSRI-N068', 5, 'หมวดที่ 5', '3. ระเบียบ อนก วินัยและการดำเนินการทางวินัย.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยวินัยและการดำเนินการทางวินัย สกสว. พ.ศ. 2564 (6 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล & ฝ่ายกฎหมาย)', 'มาตรา 47 ประกอบมาตรา 25(4) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (มติ อนก. ครั้งที่ 2/2564 วันที่ 19 ก.พ. 2564)', 'กำหนดหลักธรรมาภิบาล 7 ประการ (ข้อ 7), ข้อปฏิบัติ 11 ประการ (ข้อ 8), ข้อห้าม 10 ประการ (ข้อ 9), ความผิดวินัยอย่างร้ายแรง (ข้อ 11), โทษทางวินัย 5 สถาน (ภาคทัณฑ์ ตัดเงินเดือน ลดเงินเดือน ปลดออก ไล่ออก) และขั้นตอนการสืบสวน/สอบสวนและการอุทธรณ์', 6, 'b1471d38d16c682d...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1CaY4goR5Sgvc3Db60CXL0Ly4_yCd7TKv/view?usp=drivesdk');
INSERT INTO documents VALUES (69, 'TSRI-F05-00-004', 'TSRI-DOC-0069', 'TSRI-N069', 5, 'หมวดที่ 5', '4. ประกาศ อนก สรรหา คัดเลือก และบรรจุเป็นพนักงานและลูกจ้าง.pdf', 'ประกาศคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์และวิธีการสรรหา คัดเลือก และบรรจุแต่งตั้งบุคคลเป็นพนักงานและลูกจ้าง สกสว. พ.ศ. 2564 (9 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'อาศัยอำนาจตามข้อ 16, ข้อ 22(1)–(2) และข้อ 26 แห่งข้อบังคับ อนก. ว่าด้วยการบริหารงานบุคคล พ.ศ. 2563', 'กำหนดกระบวนการสรรหาและคัดเลือกที่เป็นธรรม โปร่งใส องค์ประกอบคณะกรรมการสรรหา/คัดเลือก การบรรจุแต่งตั้งและการทดลองปฏิบัติงาน (ไม่น้อยกว่า 90 วัน แต่ไม่เกิน 180 วัน)', 9, '74c387eb800517ec...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1cu__pzzedb7eag9lRubwR7lAg5qhMHrI/view?usp=drivesdk');
INSERT INTO documents VALUES (70, 'TSRI-F05-00-005', 'TSRI-DOC-0070', 'TSRI-N070', 5, 'หมวดที่ 5', '5. ประกาศ สกสว. ว่าด้วย การยืมตัว.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์และวิธีการให้เจ้าหน้าที่ของรัฐมาปฏิบัติงานที่สำนักงาน พ.ศ. 2567 (6 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2, B1 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 53(2) แห่งข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (มติ อนก. ครั้งที่ 1/2567 วันที่ 14 ก.พ. 2567)', 'แยก ''การยืมตัว'' (แต่งตั้งให้ดำรงตำแหน่งในสำนักงานและได้รับเงินเดือน/สวัสดิการจากสำนักงาน ทำได้คราวละ 1 ปี) ออกจาก ''การช่วยปฏิบัติงาน'' (ไม่แต่งตั้งดำรงตำแหน่งและไม่รับเงินเดือนจากสำนักงาน) พร้อมกำหนดคณะกรรมการประเมินความเหมาะสม', 6, 'dc568de084f15069...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1CFSvSUKcseXePONohICArFEFEIy9Cw95/view?usp=drivesdk');
INSERT INTO documents VALUES (71, 'TSRI-F05-00-006', 'TSRI-DOC-0071', 'TSRI-N071', 5, 'หมวดที่ 5', '6.1 ประกาศ สกสว. วิธีการลาของพนักงานและลูกจ้าง.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์และวิธีการลาของพนักงานและลูกจ้าง พ.ศ. 2564 (7 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'อาศัยอำนาจตามข้อ 6, ข้อ 26(2)–(3) และข้อ 27 แห่งข้อบังคับ อนก. ว่าด้วยการบริหารงานบุคคล พ.ศ. 2563', 'กำหนดประเภทการลา หลักเกณฑ์การอนุมัติลา และจำนวนวันลาได้รับค่าจ้าง (ลาป่วย ลากิจ ลาพักผ่อนประจำปี ลาคลอดบุตร ลาอุปสมบท/ประกอบพิธีฮัจย์ ลาตรวจเลือกทหาร และลาเพื่อพัฒนา/ศึกษาฝึกอบรม)', 7, '14f52069c33a6bd9...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1YU2XZC6UYBJzLFUK9L8S6LkLZF5TodfR/view?usp=drivesdk');
INSERT INTO documents VALUES (72, 'TSRI-F05-00-007', 'TSRI-DOC-0072', 'TSRI-N072', 5, 'หมวดที่ 5', '6.2 ประกาศ สกสว. วิธีการลาของพนักงานและลูกจ้าง (ฉ.2) พ.ศ. 2569.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์และวิธีการลาของพนักงานและลูกจ้าง (ฉบับที่ 2) พ.ศ. 2569 (ประกาศ ณ วันที่ 30 มีนาคม 2569)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'อาศัยอำนาจตามข้อ 6, ข้อ 26(2)–(3) และข้อ 27 แห่งข้อบังคับ อนก. ว่าด้วยการบริหารงานบุคคล พ.ศ. 2563', 'แก้ไขข้อ 13 ขยายสิทธิลาคลอดบุตรทั้งก่อนและหลังคลอดโดยได้รับเงินเดือนค่าจ้างได้ไม่เกิน 120 วัน และมีสิทธิลาต่อเนื่องเพื่อเลี้ยงดูบุตรได้อีกไม่เกิน 15 วัน (โดยได้รับเงินเดือน) กรณีบุตรมีภาวะเจ็บป่วยเสี่ยงโรคแทรกซ้อน ผิดปกติ หรือพิการ', 1, '100bb594effa585a...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1GqCQmq1i_G403T0hHZWRc46WGRtuozjo/view?usp=drivesdk');
INSERT INTO documents VALUES (73, 'TSRI-F05-00-008', 'TSRI-DOC-0073', 'TSRI-N073', 5, 'หมวดที่ 5', '7. ประกาศ สกสว. วัน เวลา ชั่วโมงทำงาน.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง การกำหนด วัน เวลา ชั่วโมงทำงาน วันหยุดงาน และวันหยุดประจำปีของพนักงานและลูกจ้าง พ.ศ. 2564 (2 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'อาศัยอำนาจตามข้อบังคับ อนก. ว่าด้วยการบริหารงานบุคคล พ.ศ. 2563', 'กำหนดวันทำงานจันทร์–ศุกร์ สัปดาห์ละ 5 วัน วันละ 7 ชั่วโมงทำงาน โดยใช้ระบบเวลาทำงานเหลื่อมเวลา (Flexible Hours): เข้างานตั้งแต่ 07.00–09.30 น. และเลิกงานตั้งแต่ 15.00–17.30 น. (เวลาพักกลางวัน 12.00–13.00 น.)', 2, '415f9ba610fe55fb...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1xy6_02iJ6nh7L6gmLTYib1CWSMPmpF46/view?usp=drivesdk');
INSERT INTO documents VALUES (74, 'TSRI-F05-00-009', 'TSRI-DOC-0074', 'TSRI-N074', 5, 'หมวดที่ 5', '8. ประกาศ สกสว.นโยบายและแนวทางการปฏิบัติงานรูปแบบ WFH WFA.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง นโยบายและแนวทางการปฏิบัติงานรูปแบบ Work From Home (WFH) และ Work From Anywhere (WFA) (ประกาศ 21 ก.พ. 2568, ใช้บังคับ 1 มี.ค. 2568)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (ยกเลิกประกาศ WFH/WFA ลงวันที่ 1 ก.ย. 2567)', 'กำหนดสัดส่วนการเข้าปฏิบัติงานที่สำนักงาน ร้อยละ 80 ของวันทำการในแต่ละสัปดาห์ และอนุญาตให้ปฏิบัติงานรูปแบบ WFH หรือ WFA (ภายในประเทศ) ได้ไม่เกินร้อยละ 20 ของวันทำการต่อสัปดาห์ โดยต้องลงเวลาออนไลน์ (Check-in / Check-out) และห้ามขอต่อเนื่องจากการลาพักผ่อนเพื่อวัตถุประสงค์ในการลา', 3, '0b07c89c246ce155...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/19HAM20iocAKA1wo8oGzl3Di5zaM6vjtx/view?usp=drivesdk');
INSERT INTO documents VALUES (75, 'TSRI-F05-00-010', 'TSRI-DOC-0075', 'TSRI-N075', 5, 'หมวดที่ 5', '9. ระเบียบ อนก สวัสดิการพนักงานและลูกจ้าง.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยสวัสดิการของพนักงานและลูกจ้าง สกสว. พ.ศ. 2563 (มติ อนก. ครั้งที่ 7/2563 วันที่ 4 ก.ย. 2563, 14 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2, B3 (F5 ฝ่ายทรัพยากรบุคคล & การเงิน)', 'มาตรา 47 ประกอบมาตรา 25(4)(ช) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 35 แห่งข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 (ยกเลิกระเบียบ สกว. พ.ศ. 2551)', 'กำหนดสิทธิสวัสดิการค่ารักษาพยาบาล การตรวจสุขภาพประจำปี การประกันสุขภาพและอุบัติเหตุ เงินช่วยเหลือบุตร เงินช่วยเหลือการศึกษาบุตร เงินช่วยเหลือกรณีถึงแก่กรรม เงินตอบแทนความชอบในการทำงาน และกองทุนสำรองเลี้ยงชีพ', 14, 'f9ac6feb86d223a0...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1uCywpjJSbBMKQo_AyhxkonX6yHoeVjDj/view?usp=drivesdk');
INSERT INTO documents VALUES (76, 'TSRI-F05-00-011', 'TSRI-DOC-0076', 'TSRI-N076', 5, 'หมวดที่ 5', '10. ประกาศ อนก. กองทุนสำรองเลี้ยงชีพ สกสว..pdf', 'ประกาศคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยหลักเกณฑ์ วิธีการ และเงื่อนไขกองทุนสำรองเลี้ยงชีพ สกสว. พ.ศ. 2564 (3 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2, B3 (F5 ฝ่ายทรัพยากรบุคคล & การเงิน)', 'ข้อ 35 แห่งข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 และข้อ 36 แห่งระเบียบ อนก. ว่าด้วยสวัสดิการฯ พ.ศ. 2563 (มติ อนก. ครั้งที่ 1/2564 วันที่ 8 ม.ค. 2564)', 'ข้อ 5 กำหนดอัตราเงินสะสมและเงินสมทบ: สะสม 2–8% สำนักงานสมทบ 8% ของค่าจ้าง; สะสม 9–15% สำนักงานสมทบเท่ากับอัตราที่สะสมแต่ไม่เกิน 15%; ข้อ 7 อัตราการได้รับเงินสมทบตามอายุงาน (<1 ปี 0%, 1–<3 ปี 50%, 3–<5 ปี 75%, >=5 ปี 100%); แจ้งเปลี่ยนอัตราได้ปีละ 1 ครั้งในเดือนธันวาคม', 3, '1a0507a2b791ddbb...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1RAbZ6XrtW9IBBeRro6vaEp-EexgDuDjD/view?usp=drivesdk');
INSERT INTO documents VALUES (77, 'TSRI-F05-00-012', 'TSRI-DOC-0077', 'TSRI-N077', 5, 'หมวดที่ 5', '11. ระเบียบ อนก เครื่องแบบพิธีการ.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยเครื่องแบบพิธีการของผู้อำนวยการและพนักงาน สกสว. พ.ศ. 2566 (ประกาศ 10 มี.ค. 2566, 6 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2', 'B2 (F5 ฝ่ายทรัพยากรบุคคล)', 'มาตรา 47 ประกอบมาตรา 25(4) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (มติ อนก. ครั้งที่ 2/2566 เมื่อวันที่ 3 มีนาคม 2566)', 'กำหนดเครื่องแบบพิธีการ 3 ประเภท: (1) เครื่องแบบปกติขาว, (2) เครื่องแบบเต็มยศ, (3) เครื่องแบบครึ่งยศ พร้อมแบบตราสัญลักษณ์ประดับคอเสื้อและอินทรธนูลายไทย โดยให้กรรมการใน กสว. และคณะกรรมการประเมินผลฯ มีสิทธิแต่งโดยอนุโลม (ข้อ 10)', 6, 'ff400d89b265ea55...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1hgW4sEv2qHRd94qlRspRUF6S4jX65alA/view?usp=drivesdk');
INSERT INTO documents VALUES (78, 'TSRI-F05-00-013', 'TSRI-DOC-0078', 'TSRI-N078', 5, 'หมวดที่ 5', '12. ประกาศ สกสว. นโยบายปฏิบัติงานจากเหตุการณ์แผ่นดินไหว (ฉ.2).pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง นโยบายและแนวทางการปฏิบัติงานจากเหตุการณ์แผ่นดินไหว (ฉบับที่ 2) (ประกาศ ณ วันที่ 3 เมษายน 2568)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล & อาคารสถานที่)', 'อาศัยอำนาจตามมาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (ยกเลิกประกาศฉบับวันที่ 29 มีนาคม 2568)', 'กำหนดแนวทางบริหารความต่อเนื่องทางธุรกิจ (BCP) หลังตรวจสอบความมั่นคงแข็งแรงทางวิศวกรรมอาคารที่ตั้งสำนักงาน (ชั้น 14 และชั้น 15) โดยเปิดให้ผสมผสานการเข้าปฏิบัติงาน ณ สำนักงานและรูปแบบ WFH/WFA ในช่วงซ่อมแซมงานสถาปัตยกรรม', 2, '526d8fca2b756144...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1iSBDgVNEgFuRy9ZbajrJEl_rPz63N8EQ/view?usp=drivesdk');
INSERT INTO documents VALUES (79, 'TSRI-F06-00-001', 'TSRI-DOC-0079', 'TSRI-N079', 6, 'หมวดที่ 6', '1. ข้อบังคับ อนก การบริหารจัดการ การเงิน การบัญชีและทรัพย์สิน.pdf', 'ข้อบังคับคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการบริหารจัดการ การเงิน การบัญชีและทรัพย์สิน สกสว. พ.ศ. 2563 (6 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B3, B4', 'B3, B4 (F5 กลุ่มบัญชีและการเงิน 5.4.1–5.4.2)', 'มาตรา 47 ประกอบมาตรา 25(4)(ฉ) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (มติ อนก. ครั้งที่ 7/2563 เมื่อวันที่ 4 กันยายน 2563)', 'กฎหมายแม่บทด้านการเงิน การบัญชี และทรัพย์สินของสำนักงาน (แยกจากเงินกองทุน ววน. ตาม ม.45): กำหนดองค์ประกอบเงินและทรัพย์สินของสำนักงาน 5 ประเภท (ข้อ 6), ให้นำเงินฝากธนาคารในวันนั้นหรืออย่างช้าในวันทำการถัดไป (ข้อ 9), การนำเงินไปหาผลประโยชน์ (ข้อ 10), ประเภทรายจ่ายและการจัดทำงบการเงินส่งผู้สอบบัญชี', 6, '0bbc89c129c5cd35...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1NwyubnA2BnDWk_NQeT-MGRX_11Ehi9w3/view?usp=drivesdk');
INSERT INTO documents VALUES (80, 'TSRI-F06-00-002', 'TSRI-DOC-0080', 'TSRI-N080', 6, 'หมวดที่ 6', '2. ระเบียบ อนก การรับเงิน การจ่ายเงิน และการเก็บรักษาเงิน.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการรับเงิน การจ่ายเงิน และการเก็บรักษาเงิน สกสว. พ.ศ. 2563 (7 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B3, B4', 'B3, B4 (F5 ฝ่ายการเงิน & ฝ่ายบัญชี)', 'มาตรา 47 ประกอบมาตรา 25(4)(ฉ) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และข้อ 14 แห่งข้อบังคับ อนก. การบริหารจัดการ การเงิน การบัญชีและทรัพย์สิน พ.ศ. 2563 (มติ อนก. ครั้งที่ 7/2563 วันที่ 4 ก.ย. 2563)', 'กำหนดวิธีปฏิบัติในการออกใบเสร็จรับเงิน (ห้ามขูดลบแก้ไขจำนวนเงินหรือชื่อผู้ชำระเงิน ข้อ 7), การนำส่งเงินเข้าบัญชีธนาคารในชื่อ ''สำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม'' ภายในวันที่รับหรือวันทำการถัดไป (ข้อ 10–11), อำนาจอนุมัติจ่ายเงิน การยืมเงินทดรอง และการเก็บรักษาเงิน', 7, '07328149ab2114af...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1hGjPK7TqhIqEw1h3E_5bF8lynQgDHSZq/view?usp=drivesdk');
INSERT INTO documents VALUES (81, 'TSRI-F06-00-003', 'TSRI-DOC-0081', 'TSRI-N081', 6, 'หมวดที่ 6', '3. ประกาศ สกสว. อัตราค่าธรรมเนียมการจอดรถ.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง หลักเกณฑ์และอัตราค่าธรรมเนียมการจอดรถ พ.ศ. 2566 (ประกาศ ณ วันที่ 20 ธันวาคม 2566)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B3', 'B3 (F5 ฝ่ายอาคารสถานที่ & ฝ่ายการเงิน)', 'อาศัยอำนาจตามข้อ 5(1) แห่งระเบียบ อนก. ว่าด้วยการรับเงิน การจ่ายเงิน และการเก็บรักษาเงิน สกสว. พ.ศ. 2563', 'จัดเก็บค่าธรรมเนียมการจอดรถภายในอาคารแบบเหมาจ่ายอัตราเดือนละ 500 บาท (ตั้งแต่เดือนมกราคม 2567) โดยหักจากบัญชีเงินเดือนทุกเดือนเพื่อนำส่งนิติบุคคลอาคาร และทบทวนอัตราอย่างน้อยปีละ 1 ครั้ง', 2, '3f71810a88a7b058...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1YaqyfwGMHKp5b75O94gs2qUs4cd9n3dB/view?usp=drivesdk');
INSERT INTO documents VALUES (82, 'TSRI-F06-00-004', 'TSRI-DOC-0082', 'TSRI-N082', 6, 'หมวดที่ 6', '4. ระเบียบการเดินทางไปปฏิบัติงาน (สำเนาซ้ำกับ 005).pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยค่าใช้จ่ายในการเดินทางไปปฏิบัติงาน สกสว. พ.ศ. 2563 [รหัสสงวนเนื่องจากไฟล์ซ้ำระดับไบต์กับ TSRI-F06-00-005]', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B3', 'สำนัก F5 (ฝ่ายการเงิน)', 'ตรวจสอบตามฐานข้อมูล v0.3: มีค่า SHA-256 (b2a21caf21d5afcee547272656b9856b489593ee28460e363937ecdc817ae6af, ขนาด 2,808,223 ไบต์) ตรงกับ TSRI-F06-00-005 ทุกประการ', 'ถอนรหัส TSRI-F06-00-004 ออกจากบัญชีใช้งานเมื่อ 10 พ.ย. 2569 และให้ใช้อ้างอิงที่รหัส TSRI-F06-00-005 (TSRI-DOC-0083) เป็นฉบับหลัก ทำให้คลังข้อมูลทั้ง 11 หมวดมีเอกสารใช้งานจริงสุทธิ 100 ไฟล์ จาก 101 รหัสทะเบียน', 11, 'ตรงกับ DOC-0083', 'ซ้ำถอนออก (SHA-256 ตรงกับ 005)', 0, 'https://drive.google.com/drive/folders/1lGYjlvzdd-9CyjlBt2rdOdWdX-eLCLq9');
INSERT INTO documents VALUES (83, 'TSRI-F06-00-005', 'TSRI-DOC-0083', 'TSRI-N083', 6, 'หมวดที่ 6', '4. ระเบียบ อนก ค่าใช้จ่ายในการเดินทางไปปฏิบัติงาน.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยค่าใช้จ่ายในการเดินทางไปปฏิบัติงาน สกสว. พ.ศ. 2563 (มติ อนก. ครั้งที่ 7/2563 วันที่ 4 ก.ย. 2563, 10 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B3', 'B3 (F5 ฝ่ายการเงิน — เชื่อมคู่มือการเงิน DOC-0098)', 'มาตรา 47 ประกอบมาตรา 25(4)(ฉ) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และข้อ 11 แห่งข้อบังคับ อนก. การบริหารจัดการ การเงิน การบัญชีและทรัพย์สิน พ.ศ. 2563', 'กำหนดสิทธิและอัตราการเบิกค่าเบี้ยเลี้ยงเดินทาง ค่าเช่าที่พัก ค่ายานพาหนะ (รวมเงินชดเชยพาหนะส่วนตัว) และค่าใช้จ่ายอื่นในการเดินทางไปปฏิบัติงานทั้งในราชอาณาจักรและต่างประเทศ (จำแนกประเทศประเภท ก, ข และ ค) สำหรับผู้ปฏิบัติงาน ผู้บริหาร และที่ปรึกษา/ผู้เชี่ยวชาญ', 10, 'b2a21caf21d5afce...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/171ke2LFrLNo1fiFtT6CN6iaMoRKX0s9J/view?usp=drivesdk');
INSERT INTO documents VALUES (84, 'TSRI-F06-00-006', 'TSRI-DOC-0084', 'TSRI-N084', 6, 'หมวดที่ 6', '5. ระเบียบ อนก กำหนดค่าตอบแทน ค่าใช้จ่าย เบี้ยประชุม.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยหลักเกณฑ์การกำหนดค่าตอบแทน ค่าใช้จ่าย เบี้ยประชุมและประโยชน์ตอบแทนอื่นของ สกสว. พ.ศ. 2564 (3 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2, B3', 'B2, B3 (F5 ฝ่ายการเงิน & เลขานุการคณะกรรมการ)', 'มาตรา 47 ประกอบมาตรา 25(4)(ฉ) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (มติ อนก. ครั้งที่ 11/2564 เมื่อวันที่ 5 พฤศจิกายน 2564)', 'กำหนดเพดานอัตราเบิกจ่ายที่สำคัญ: (1) บุคคลภายนอกร่วมประชุม เต็มวัน <=6,000 บาท/ครึ่งวัน <=3,000 บาท (ประธาน <=8,000 บาท/วัน), (2) กลั่นกรองรายชิ้นงาน <=2,000 บาท (รวม <=20,000 บาท/รอบ) รายหน่วยงาน <=3,000 บาท (รวม <=30,000 บาท/รอบ), (3) วิทยากร <=3,000 บาท/ชม., (4) เบี้ยประชุมผู้ทรงคุณวุฒิ ประธาน 3,125 บาท/ครั้ง กรรมการ/ที่ปรึกษา 2,500 บาท/ครั้ง, (5) เหมาจ่ายเดินทางในจังหวัด <=600 บาท ข้ามจังหวัด <=800 บาท, (6) จัดเลี้ยงในสำนักงาน/รัฐ <=600 บาท/คน/วัน เอกชน <=1,800 บาท/คน/วัน (<=500 บาท/มื้อ), (7) ของที่ระลึก/พวงมาลา <=3,000 บาท', 3, '83c1e30c67fd87c2...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/18mQfYVot5OMhAuC9BKpg_qBVfTUBJLLj/view?usp=drivesdk');
INSERT INTO documents VALUES (85, 'TSRI-F06-00-007', 'TSRI-DOC-0085', 'TSRI-N085', 6, 'หมวดที่ 6', '6. ระเบียบ อนก การเบิกค่าใช้จ่าย ค่าบริการสื่อสารและโทรคมนาคม.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยการเบิกค่าใช้จ่ายที่เกี่ยวข้องกับค่าบริการสื่อสารและโทรคมนาคมจากการปฏิบัติงานภายนอก สกสว. พ.ศ. 2564 (3 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B3', 'B3 (F5 ฝ่ายการเงิน)', 'มาตรา 47 ประกอบมาตรา 25(4)(ฉ) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และข้อ 11 แห่งข้อบังคับ อนก. การเงินฯ พ.ศ. 2563 (มติ อนก. ครั้งที่ 1/2564 วันที่ 8 ม.ค. 2564; ยกเลิกระเบียบปี 2563)', 'ผู้ปฏิบัติงานที่ได้รับมอบหมายให้ปฏิบัติงานภายนอกสำนักงานรวมกันไม่น้อยกว่า 10 วันทำการในเดือนนั้น (ถือเป็นเต็มเดือน) เบิกค่าบริการสื่อสารและโทรคมนาคมได้เท่าที่จ่ายจริงแต่ไม่เกิน 500 บาท/เดือน โดยต้องยื่นเบิกภายใน 30 วันนับแต่วันที่ชำระเงิน (ไม่ใช้กับผู้ดำรงตำแหน่งบริหารที่ได้รับสนับสนุนอุปกรณ์/ค่าบริการแล้ว)', 3, 'd39e4d4bf6cf3558...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/132jZzewkfIW3t-X9TrRvWtgd2yAVoltX/view?usp=drivesdk');
INSERT INTO documents VALUES (86, 'TSRI-F06-00-008', 'TSRI-DOC-0086', 'TSRI-N086', 6, 'หมวดที่ 6', 'คำสั่ง สกสว ค่าใช้จ่ายเดินทางมาปฏิบัติงานของผู้บริหารที่ยืมตัวฯ.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง ค่าใช้จ่ายในการเดินทางมาปฏิบัติงานของผู้ดำรงตำแหน่งบริหารที่ยืมตัวมาปฏิบัติงานแบบไม่เต็มเวลาและไม่ได้มีภูมิลำเนาต้นสังกัดเดียวกับที่ตั้งสำนักงาน (สั่ง ณ วันที่ 3 มกราคม 2566)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B2, B3', 'B2, B3 (F5 ฝ่ายการเงิน & ฝ่ายทรัพยากรบุคคล)', 'มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 5 แห่งข้อบังคับ อนก. ว่าด้วยการบริหารจัดการ การเงิน การบัญชีและทรัพย์สิน พ.ศ. 2563', 'เบิกค่าเดินทางมาปฏิบัติงานที่สำนักงาน (ไป-กลับ) ได้ไม่เกิน 5 ครั้ง/เดือน; กรณีใช้รถยนต์ส่วนบุคคลเบิกเหมาจ่ายอัตรา 4 บาท/กิโลเมตร (ไม่เกินตั๋วเครื่องบินชั้นประหยัด); ค่าเช่าที่พักเบิกได้ไม่เกิน 2,600 บาท/วัน/คน และรวมไม่เกิน 13,000 บาท/เดือน', 1, 'd1fd464f66c661d1...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1fQD61WR9-q_QbHBjtlZJ_IcGa25yMoI4/view?usp=drivesdk');
INSERT INTO documents VALUES (87, 'TSRI-F07-00-001', 'TSRI-DOC-0087', 'TSRI-N087', 7, 'หมวดที่ 7', '1. ระเบียบ อนก ว่าด้วยประมวลจริยธรรม.pdf', 'ระเบียบคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ว่าด้วยประมวลจริยธรรมของคณะกรรมการ ผู้อำนวยการ และผู้ปฏิบัติงานของ สกสว. พ.ศ. 2564 (4 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายกลยุทธ์องค์กร / นิติการ / HR)', 'มาตรา 47 ประกอบมาตรา 25(4)(ง) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และ พ.ร.บ.มาตรฐานทางจริยธรรม พ.ศ. 2562 (มติ อนก. ครั้งที่ 4/2564 วันที่ 2 เมษายน 2564)', 'กำหนดมาตรฐานจริยธรรมอันเป็นค่านิยมหลัก 10 ประการ (ข้อ 5) และหน้าที่ปฏิบัติตน 7 ประการ (ข้อ 6); กลไกสอบสวนทางจริยธรรมตั้งคณะกรรมการสอบสวนไม่น้อยกว่า 3 คน (ข้อ 9) กรณีผู้ปฏิบัติงานฝ่าฝืนให้ ผอ.สกสว. สั่งลงโทษ กรณีกรรมการหรือ ผอ.สกสว. ฝ่าฝืนให้คณะอนุกรรมการธรรมาภิบาลเสนอ อนก.สกสว. (มติสั่งพักหน้าที่ชั่วคราวใช้เสียงไม่น้อยกว่า 3 ใน 4)', 4, 'e6c582b5bbf13365...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1hnwFp9XBr2es_Ri4EVytcNsWiT_2UGH5/view?usp=drivesdk');
INSERT INTO documents VALUES (88, 'TSRI-F07-00-002', 'TSRI-DOC-0088', 'TSRI-N088', 7, 'หมวดที่ 7', '2. ประกาศ สกสว. ข้อพึงปฏิบัติและไม่พึงปฏิบัติของบุคลากร.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง ข้อพึงปฏิบัติและไม่พึงปฏิบัติของบุคลากร สกสว. (ประกาศ ณ วันที่ 3 ธันวาคม 2567, 8 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B2', 'B1, B2 (F5 ฝ่ายทรัพยากรบุคคล & ฝ่ายกลยุทธ์องค์กร)', 'มาตรา 50(2) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 (ยกเลิกประกาศฉบับวันที่ 18 มกราคม 2566)', 'แปลงประมวลจริยธรรมและนโยบาย No Gift Policy สู่ตารางข้อพึงปฏิบัติ (Do) และข้อไม่พึงปฏิบัติ (Don''t) รายหมวด (ยึดมั่นสถาบันหลัก ซื่อสัตย์สุจริต/ไม่ขัดกันแห่งผลประโยชน์ กล้าตัดสินใจในสิ่งที่ถูกต้อง คุ้มครองข้อมูลส่วนบุคคล และรักษาสิ่งแวดล้อม)', 8, '30378cad9254d191...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1ijG6FyUiLpJ829aPtr9MWqGR_79jmIcG/view?usp=drivesdk');
INSERT INTO documents VALUES (89, 'TSRI-F07-00-003', 'TSRI-DOC-0089', 'TSRI-N089', 7, 'หมวดที่ 7', '3.1 ประกาศนโยบายไม่รับของขวัญ 2569_TH.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง นโยบายการไม่รับของขวัญและของกำนัลทุกชนิดจากการปฏิบัติหน้าที่ (No Gift Policy) ประจำปีงบประมาณ พ.ศ. 2569 (ประกาศ 27 พ.ย. 2568)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1', 'B1 (F5 ฝ่ายกลยุทธ์องค์กร)', 'หลักธรรมาภิบาลตามรัฐธรรมนูญ มาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 และเกณฑ์การประเมินคุณธรรมและความโปร่งใสในการดำเนินงานของหน่วยงานภาครัฐ (ITA)', 'ประกาศเจตนารมณ์ให้ผู้บริหาร เจ้าหน้าที่ และบุคลากร สกสว. ทุกคนไม่รับของขวัญและของกำนัลทุกชนิดหรือผลประโยชน์อื่นใดจากการปฏิบัติหน้าที่ ทั้งในขณะ ก่อน และหลังการปฏิบัติหน้าที่ เพื่อป้องกันผลประโยชน์ทับซ้อน', 1, '51f53fad6d002670...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1Ak8OVJQaFkNSfJoSCPCzIK80HuzkKwvi/view?usp=drivesdk');
INSERT INTO documents VALUES (90, 'TSRI-F07-00-004', 'TSRI-DOC-0090', 'TSRI-N090', 7, 'หมวดที่ 7', '3.2 ประกาศนโยบายไม่รับของขวัญ 2569_EN.pdf', 'Official Announcement: Thailand Science Research and Innovation (TSRI) Declaration of the ''No Gift Policy'' Fiscal Year 2026 (Issued 27 November 2025)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1', 'B1, A4 (F5 ฝ่ายกลยุทธ์องค์กร & F4 ความร่วมมือนานาชาติ)', 'คู่ฉบับภาษาอังกฤษของประกาศ No Gift Policy ประจำปีงบประมาณ พ.ศ. 2569 สำหรับสื่อสารต่อองค์กรพันธมิตรต่างประเทศและเกณฑ์ประเมิน ITA สากล', 'กำหนดให้ผู้บริหารและบุคลากรทุกระดับงดรับของขวัญ ของกำนัล หรือผลประโยชน์ใดๆ ทั้งก่อน ระหว่าง และหลังการปฏิบัติหน้าที่ เพื่อธำรงความเป็นกลางและความโปร่งใสระดับสากล', 1, '7e7b9af9b091611a...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1mpuy8QSzmsIrWVBCiEH__0_THYIAtTQ3/view?usp=drivesdk');
INSERT INTO documents VALUES (91, 'TSRI-F07-00-005', 'TSRI-DOC-0091', 'TSRI-N091', 7, 'หมวดที่ 7', '4. ประกาศสกสว. แจ้งช่องทางรับเรื่องร้องเรียน.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง ประชาสัมพันธ์การรับความเห็น ข้อร้องเรียน ตลอดจนข้อเสนอแนะต่อการตรวจสอบการดำเนินงานในองค์กร (ประกาศ ณ วันที่ 4 กรกฎาคม 2568)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1', 'B1, B4 (F5 ฝ่ายกฎหมาย & หน่วยตรวจสอบภายใน IA)', 'หลักการบริหารกิจการบ้านเมืองที่ดี และมาตรา 50 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562', 'เปิดช่องทางรับเรื่องร้องเรียนและข้อเสนอแนะ 6 ช่องทาง: (1) ยื่นด้วยตนเอง ณ สกสว., (2) ไปรษณีย์ถึง ผอ.สกสว. ชั้น 14 อาคาร SM Tower, (3) E-mail: complaint@tsri.or.th / appeal.tsri@gmail.com, (4) โทรศัพท์ 02-278-8200 ต่อ 8373, 8387, (5) เว็บไซต์ tsri.or.th/complaint และ (6) หน่วยตรวจสอบภายใน (IA) พร้อมมาตรการคุ้มครองข้อมูลส่วนบุคคลของผู้ร้องเรียน', 1, 'd0f6b78d5a042a84...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1K1HMHyKU2XBP9a9Qi4h-ZFyzcHUt0L8d/view?usp=drivesdk');
INSERT INTO documents VALUES (92, 'TSRI-F07-00-006', 'TSRI-DOC-0092', 'TSRI-N092', 7, 'หมวดที่ 7', '5. ประกาศ สกสว. นโยบายการกำกับองค์การที่ดี 2568.pdf', 'ประกาศสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง นโยบายการกำกับดูแลองค์การที่ดี (Organizational Governance) สกสว. พ.ศ. 2568 (2 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B4', 'B1, B4 (F5 ฝ่ายกลยุทธ์องค์กร & หน่วยตรวจสอบภายใน IA)', 'รัฐธรรมนูญ พ.ศ. 2560, พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546 และเกณฑ์คุณภาพการบริหารจัดการภาครัฐ (PMQA)', 'วางกรอบนโยบายและแนวปฏิบัติ Organizational Governance 4 ด้านหลัก: (1) ด้านรัฐ สังคม และสิ่งแวดล้อม, (2) ด้านผู้รับบริการและผู้มีส่วนได้ส่วนเสีย (เชื่อมระบบประเมินของ ป.ป.ช.), (3) ด้านองค์การ (บริหารความเสี่ยงและควบคุมภายใน) และ (4) ด้านผู้ปฏิบัติงาน (แผนพัฒนาบุคลากร Hard/Soft Skills)', 2, '513a2ff843de2d57...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1g9j-nLc3x_lCjAQXsCOv3IOMpUJDgm9B/view?usp=drivesdk');
INSERT INTO documents VALUES (93, 'TSRI-F07-00-007', 'TSRI-DOC-0093', 'TSRI-N093', 7, 'หมวดที่ 7', '6. ประกาศ อนก. เรื่อง นโยบายและแนวทางจัดการเรื่องร้องเรียน (ลงนาม).pdf', 'ประกาศคณะกรรมการอำนวยการสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม เรื่อง นโยบายและแนวทางการจัดการเรื่องร้องเรียน สกสว. (4 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1', 'B1, B2 (F5 ฝ่ายกฎหมาย / เลขานุการคณะกรรมการ)', 'อำนาจกำกับดูแลของคณะกรรมการอำนวยการ สกสว. ตามมาตรา 47 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 เชื่อมระเบียบวินัย พ.ศ. 2564 และระเบียบประมวลจริยธรรม พ.ศ. 2564', 'แบ่งระดับผู้มีอำนาจพิจารณาเรื่องร้องเรียนชัดเจน (หมวด 3 ข้อ 7–8): (1) กรณีร้องเรียนผู้บริหารหรือพนักงาน สกสว. ผู้มีอำนาจพิจารณาคือ ''ผู้อำนวยการ สกสว.''; (2) กรณีร้องเรียนกรรมการอำนวยการหรือผู้อำนวยการ สกสว. ผู้มีอำนาจพิจารณาคือ ''คณะกรรมการอำนวยการ สกสว.'' (ยื่นผ่านประธาน อนก.สกสว.) โดยตั้งคณะกรรมการตรวจสอบข้อเท็จจริงและคุ้มครองผู้แจ้งเบาะแส', 4, '7ef9a00b6730a375...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1qKM9bG1hc1-RnuXpGJO1c1ENq3bzZmCA/view?usp=drivesdk');
INSERT INTO documents VALUES (94, 'TSRI-F08-00-001', 'TSRI-DOC-0094', 'TSRI-N094', 8, 'หมวดที่ 8', 'คำสั่งที่ พด.70 2564 เรื่องมอบอำนาจดำเนินงานจัดซื้อจัดจ้าง.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ พด.70/2564 เรื่อง มอบอำนาจการดำเนินงานเกี่ยวกับการจัดซื้อจัดจ้างและการบริหารพัสดุ (สั่ง ณ วันที่ 19 มี.ค. 2564, ใช้บังคับ 22 มี.ค. 2564)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B3', 'B3, B1 (F5 ฝ่ายพัสดุ 5.2.1 & F2)', 'มาตรา 50(1) และ (2) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 16 แห่งข้อบังคับ อนก. การเงินฯ พ.ศ. 2563 และข้อ 7 แห่งระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560', 'มอบอำนาจอนุมัติจัดซื้อจัดจ้าง บริหารสัญญา และอนุมัติจำหน่ายพัสดุภายในวงเงินไม่เกิน 500,000 บาท โดยแยกชัดเจนระหว่าง: ข้อ 1 พัสดุของ ''สำนักงาน (สกสว.)'' ให้ผู้บริหารที่กำกับดูแลสำนักบริหารและพัฒนาองค์กร (F5) มีอำนาจอนุมัติ; และข้อ 2 พัสดุของ ''กองทุนส่งเสริม ววน.'' ให้ผู้บริหารที่กำกับดูแลสำนักบริหารงบประมาณ ววน. (F2) มีอำนาจอนุมัติ', 2, '37f454358bb00193...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1RzLinYfN-VbHheqcjX1zfo1dIJYagRbo/view?usp=drivesdk');
INSERT INTO documents VALUES (95, 'TSRI-F08-00-002', 'TSRI-DOC-0095', 'TSRI-N095', 8, 'หมวดที่ 8', 'คำสั่งที่ พด.71 2564 เรื่องแต่งตั้งเจ้าหน้าที่การจัดซื้อจัดจ้าง.pdf', 'คำสั่งสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม ที่ พด.71/2564 เรื่อง แต่งตั้งหัวหน้าเจ้าหน้าที่และเจ้าหน้าที่เกี่ยวกับการจัดซื้อจัดจ้างและการบริหารพัสดุ (สั่ง ณ วันที่ 19 มี.ค. 2564)', 'ระดับที่ 2: กฎหมายลำดับรอง ระเบียบ ประกาศ ข้อบังคับ คำสั่ง (4.1.1.2)', 'B1, B3', 'B3, B1 (F5 ฝ่ายพัสดุ 5.2.1)', 'มาตรา 50(1) และ (2) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบข้อ 16 แห่งข้อบังคับ อนก. การเงินฯ พ.ศ. 2563 และ พ.ร.บ.การจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 (หมวด 12: DOC-0104)', 'แต่งตั้งหัวหน้าเจ้าหน้าที่พัสดุ (1 ราย) และเจ้าหน้าที่พัสดุหลัก (2 ราย) ของ สกสว. และกองทุนส่งเสริม ววน. และในข้อ 1(4) แต่งตั้งให้ผู้ปฏิบัติงานอื่นของ สกสว. เป็นเจ้าหน้าที่พัสดุสำหรับวงเงินจัดซื้อจัดจ้างไม่เกิน 10,000 บาท ตามความจำเป็นและเหมาะสมเพื่อความคล่องตัวในการปฏิบัติงาน', 2, 'cf5e6e599d72b188...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1vxsiHhK4xvvVi7-YlvyyYP0CEfuoPzA7/view?usp=drivesdk');
INSERT INTO documents VALUES (96, 'TSRI-F09-00-001', 'TSRI-DOC-0096', 'TSRI-N096', 9, 'หมวดที่ 9', '♥คู่มือการดำเนินการทางวินัย สกสว.pdf', 'คู่มือการดำเนินการทางวินัย พนักงานและลูกจ้างของสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม (สกสว.) พ.ศ. 2568 (กันยายน 2568, 111 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง คู่มือปฏิบัติงาน และ SOP (4.1.1.2)', 'B2', 'B2 (F5 ฝ่ายกฎหมาย 5.3.3 & ฝ่ายทรัพยากรบุคคล 5.3.2)', 'เชื่อมโยง พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539 (ระดับที่ 3) เข้ากับข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563, ระเบียบ อนก. วินัยและการดำเนินการทางวินัย พ.ศ. 2564 และประกาศกองทุนสำรองเลี้ยงชีพ พ.ศ. 2564', 'วิเคราะห์องค์ประกอบความผิดวินัยครบทุกข้อ (ข้อ 7, 8, 9, 11, 13), ลำดับขั้นตอนตั้งแต่วินิจฉัยเบื้องต้น ตรวจสอบข้อเท็จจริง สืบสวน สอบสวนวินัยอย่างไม่ร้ายแรงและร้ายแรง การสั่งพักงาน การลงโทษ และการตัดสิทธิเงินสมทบกองทุนสำรองเลี้ยงชีพ พร้อมแบบพิมพ์คำสั่งและบันทึกมาตรฐาน 13 แบบ (แบบ วน.1 ถึง แบบ วน.8 และแบบสำนวนวินัย)', 111, '12889f7fd0775189...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1ynhZs2SR6CdVoStAOmaVGdhJk8AHVCnt/view?usp=drivesdk');
INSERT INTO documents VALUES (97, 'TSRI-F09-00-002', 'TSRI-DOC-0097', 'TSRI-N097', 9, 'หมวดที่ 9', 'คู่มือบริหารโครงการ ORG_update0766.pdf', 'คู่มือบริหารโครงการวิจัยเพื่อพัฒนาการปฏิบัติงานตามพันธกิจ (Operational Research Grant; ORG) (ปรับปรุง ก.ค. 2566, 50 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง คู่มือปฏิบัติงาน และ SOP (4.1.1.2)', 'A5, B1', 'A5, B1, B3 (F5 ฝ่ายแผนและงบประมาณสำนักงาน / การเงิน & F1)', 'มาตรา 43 แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบมาตรา 9 แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (ข้อยกเว้นให้ สกสว. สนับสนุนงานวิจัยเพื่อพัฒนาการปฏิบัติงานตามหน้าที่และอำนาจของหน่วยงานได้) และมาตรา 4(1) แห่ง พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'วางแนวทางบริหารโครงการ ORG ครบวงจร: เอกสารประกอบสัญญา 8 รายการ, การเปิดบัญชีโครงการ, การเบิกจ่าย 7 หมวดค่าใช้จ่าย (ค่าตอบแทน ค่าจ้าง ค่าวัสดุ ค่าใช้สอย ค่าครุภัณฑ์ ค่าใช้จ่ายอื่น ค่าบำรุงสถาบัน), การปรับแผน/ขยายเวลา, ทรัพย์สินทางปัญญา และแบบฟอร์มการเงิน/ครุภัณฑ์แนบท้าย 11 แบบ', 50, '0da83043e9d57033...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1DJ9KK15S6ELYJYpXTg-3AXWI-JD8NyS0/view?usp=drivesdk');
INSERT INTO documents VALUES (98, 'TSRI-F09-00-003', 'TSRI-DOC-0098', 'TSRI-N098', 9, 'หมวดที่ 9', 'คู่มือระเบียบการเงิน.pdf', 'คู่มือการปฏิบัติงาน และระเบียบปฏิบัติด้านการเงิน (ฉบับปรับปรุง 1 มิถุนายน 2568, 45 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง คู่มือปฏิบัติงาน และ SOP (4.1.1.2)', 'B3, B4', 'B3, B4 (F5 ฝ่ายการเงิน 5.4.2 & ฝ่ายบัญชี 5.4.1)', 'บูรณาการข้อบังคับและระเบียบการเงินในหมวดที่ 6 (DOC-0079 ถึง 0086) และระเบียบ กสว. รับ-จ่ายเงินกองทุน (DOC-0005) เข้าสู่ขั้นตอนปฏิบัติงานของสำนักบริหารและพัฒนาองค์กร (F5)', 'สรุปตารางคำสั่งมอบอำนาจการอนุมัติจ่ายเงิน 3 กลุ่ม: (1) เงินสำนักงานและเงินกองทุน, (2) เงินโครงการวิจัยเพื่อพัฒนาการปฏิบัติงาน (ORG) และ (3) เงินโครงการวิจัยต่อเนื่องของ สกว. เดิมตามบทเฉพาะกาล ม.71 (Ongoing) พร้อมตารางอัตราค่าเบี้ยเลี้ยง ค่าที่พัก ค่ายานพาหนะในประเทศ/ต่างประเทศ และขั้นตอนตรวจใบสำคัญจ่าย', 45, '651ffaae3e386836...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1Ds0ZVoOHgfNkWNuHcvKLN2KVl_5Qc2BI/view?usp=drivesdk');
INSERT INTO documents VALUES (99, 'TSRI-F09-00-004', 'TSRI-DOC-0099', 'TSRI-N099', 9, 'หมวดที่ 9', '(Final) คู่มือจัดทำคำขอและการบริหารงบประมาณทุ.pdf', 'คู่มือการจัดทำคำของบประมาณและการบริหารจัดการงบประมาณเพื่อสนับสนุนงานมูลฐานตามพันธกิจของหน่วยรับงบประมาณ (Fundamental Fund; FF) (ฉบับสมบูรณ์, 180 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง คู่มือปฏิบัติงาน และ SOP (4.1.1.2)', 'A2', 'A2, A5 (F2 สำนักกลยุทธ์งบประมาณฯ & F1)', 'มาตรา 41(4), (7) และมาตรา 44(6), (7) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562, มาตรา 17–18 แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (แก้ไขเพิ่มเติม ฉ.2 พ.ศ. 2568) และประกาศ กสว. เรื่อง หลักเกณฑ์การจัดทำคำของบประมาณฯ พ.ศ. 2566–2569', 'กำหนดคู่มือปฏิบัติการ 5 บทสำหรับหน่วยรับงบประมาณ FF: (1) หลักการจัดสรรงบแบบ Block Grant และการแบ่งกลุ่มหน่วยรับงบ/จุดมุ่งเน้น, (2) อัตราค่าใช้จ่าย 6 หมวด (รวมงบเสริมสร้างความเข้มแข็งและธรรมาภิบาล), (3) การทำคำรับรองฯ การปรับแผน และการคืนเงิน/ดอกเบี้ยผ่านระบบ NRIIS, (4) การติดตามประเมินผล และ (5) การจัดทำโครงการแบบผูกพันงบประมาณมากกว่า 1 ปี (Multi-year Promised Grant) สำหรับปีงบประมาณ พ.ศ. 2570', 180, 'd5d3ade39fee0cef...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/188ucymmUjrjyctBd5SRkzZkcpXil0Kf6/view?usp=drivesdk');
INSERT INTO documents VALUES (100, 'TSRI-F10-00-001', 'TSRI-DOC-0100', 'TSRI-N100', 10, 'หมวดที่ 10', '(Final) รายงานการประเมินผลสัมฤทธิ์ พรบ.การส่งเสริมการใช้ประโยชน์ฯ รวมภาคผนวก.pdf', 'รายงานวิจัยฉบับสมบูรณ์ โครงการประเมินผลสัมฤทธิ์ของพระราชบัญญัติการส่งเสริมวิทยาศาสตร์ การวิจัยและนวัตกรรม พ.ศ. 2562 รวมภาคผนวก (สัญญาเลขที่ ORG68F5006, 31 สิงหาคม 2568, 645 หน้า)', 'ระดับที่ 3: กฎหมายที่เกี่ยวข้อง - รายงานประเมินผลสัมฤทธิ์ ม.77 (4.1.1.3)', 'A4, A5', 'A5, A1–A4, B1 (F1, F2, F3, F4, F5)', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย พ.ศ. 2560 มาตรา 77 และ พ.ร.บ.หลักเกณฑ์การจัดทำร่างกฎหมายและการประเมินผลสัมฤทธิ์ของกฎหมาย พ.ศ. 2562 ประกอบ พ.ร.บ.สภานโยบายฯ มาตรา 44(8) และ พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562', 'ประเมินผลสัมฤทธิ์ของการบังคับใช้กฎหมายหลังครบรอบ 5 ปี ครอบคลุม 8 มาตรการหลัก: (1) การกำหนดนโยบาย ยุทธศาสตร์และแผน ววน., (2) การจัดสรรงบประมาณ ววน., (3) การจัดซื้อจัดจ้างเพื่อการวิจัยและพัฒนา, (4) การส่งเสริมบุคลากร ววน., (5) การบริหารจัดการข้อมูล ววน. และบทกำหนดโทษ, (6) การใช้ประโยชน์ผลงานวิจัยและนวัตกรรม (เชื่อม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564), (7) มาตรฐานและจริยธรรมการวิจัย และ (8) การบูรณาการระหว่างหน่วยงาน พร้อมข้อเสนอแนะเชิงเศรษฐศาสตร์ (GII / World Competitiveness) และกฎหมาย', 645, '2fc6c36bf0a2632c...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1wpVqJ-_KNwHuN9X5q5eiOs_vgnHZwlsD/view?usp=drivesdk');
INSERT INTO documents VALUES (101, 'TSRI-F11-00-001', 'TSRI-DOC-0101', 'TSRI-N101', 11, 'หมวดที่ 11', 'standard-operating-procedure-for-sri-budget-allocation.pdf', 'กระบวนการทำงานที่เป็นมาตรฐาน (Standard Operating Procedure; SOP) ในการบริหารจัดการระบบวิทยาศาสตร์ วิจัยและนวัตกรรม (ววน.) ในภาพรวมกระบวนการจัดสรรงบประมาณ (กันยายน 2569, 13 หน้า)', 'ระดับที่ 2: กฎหมายลำดับรอง คู่มือปฏิบัติงาน และ SOP (4.1.1.2)', 'A1, A2, A5', 'A2 (หลัก), A1, A5 (F2 & F1)', 'มาตรา 11(2), มาตรา 12(2), มาตรา 41(2),(4),(7) และมาตรา 44(4),(5),(6),(7) แห่ง พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ประกอบมาตรา 17(2) แห่ง พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562', 'กำหนดผังกระบวนงาน (Process Flow) และกรอบเวลาปฏิบัติงานจริงตามปฏิทินงบประมาณล่วงหน้า 2 ปี (ปี T ถึง T+2): (1) ก.ค.–ส.ค.(T) จัดทำกรอบวงเงินและทบทวนหลักเกณฑ์เสนอ กสว., (2) ก.ย.–ต.ค.(T->T+1, ~45 วัน) เปิดรับคำขอผ่านระบบ NRIIS (FF/SF) และ STARS (ST), (3) ต.ค.–พ.ย.(T+1, ~20 วัน) สกสว. กลั่นกรองคำขอ, (4) ธ.ค.–ม.ค.(T+1) เสนอ กสว. และ คกก.พิจารณางบประมาณ ม.12(2) และ Sign-off E-budgeting ส่งสำนักงบประมาณ, (5) เม.ย.–พ.ค.(T+1) จัดสรรขั้น Pre-ceiling ให้หน่วยงานปรับคำชี้แจงใน 15 วัน และตรวจใน 10 วัน, (6) มิ.ย.–ส.ค.(T+1) ชี้แจง กมธ.งบประมาณ ปรับยอดตามมติ กมธ. และแจ้งจัดสรรเพื่อทำคำรับรองฯ (พร้อม SOP ย่อย 1.1–1.3 และ 2.1–2.3)', 13, 'b63206948cd52edc...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1LxbDcP0gTJxnqMI_d5f4ayWKJ9hOIVA1/view?usp=drivesdk');
INSERT INTO documents VALUES (102, 'TSRI-F12-01-001', 'TSRI-DOC-0102', 'LAW-REL-001-2561', 12, 'หมวดที่ 12 (12.1 งบประมาณ)', 'LAW-REL-001-2561_พระราชบัญญัติวิธีการงบประมาณ_พ.ศ.-2561_v0.1.pdf', 'พระราชบัญญัติวิธีการงบประมาณ พ.ศ. 2561 (ราชกิจจานุเบกษา 11 พฤศจิกายน 2561)', 'ระดับที่ 3: กฎหมายที่เกี่ยวข้อง (4.1.1.3)', 'A2, A3, B3', 'สำนัก F1, F2 และ F5', 'เชื่อมโยง พ.ร.บ.สภานโยบายฯ มาตรา 12(2), 41(2)–(5), 44(4)–(7), 57–58 และ พ.ร.บ.การส่งเสริม ววน. มาตรา 16–18 (รวมฉบับที่ 2 พ.ศ. 2568)', 'กำหนดสถานะของ สกสว. และกองทุน ววน. ในฐานะหน่วยรับงบประมาณและเงินนอกงบประมาณ (มาตรา 4), การจัดทำคำขอตั้งงบประมาณรายจ่ายประจำปีและการผูกพันงบประมาณข้ามปี (มาตรา 24–26 เชื่อมโยงคำรับรอง Multi-year มาตรา 18 และ SOP จัดสรรงบ DOC-0101), การโอนและเปลี่ยนแปลงงบประมาณ และการชี้แจงต่อสำนักงบประมาณและคณะกรรมาธิการพิจารณางบประมาณของรัฐสภา', 18, '5306b477b3eb87f6...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1sLNk82r3gTNjZv1fUXxyJ95leh8BXURO/view?usp=drivesdk');
INSERT INTO documents VALUES (103, 'TSRI-F12-02-001', 'TSRI-DOC-0103', 'LAW-REL-002-2561', 12, 'หมวดที่ 12 (12.2 การเงิน-การคลัง)', 'LAW-REL-002-2561_พระราชบัญญัติวินัยการเงินการคลังของรัฐ_พ.ศ.-2561_v0.1.pdf', 'พระราชบัญญัติวินัยการเงินการคลังของรัฐ พ.ศ. 2561 (ราชกิจจานุเบกษา 19 เมษายน 2561)', 'ระดับที่ 3: กฎหมายที่เกี่ยวข้อง (4.1.1.3)', 'A2, A3, B3, B4', 'สำนัก F5 (ฝ่ายการเงิน/บัญชี), F3 และหน่วยตรวจสอบภายใน (IA)', 'เชื่อมโยง พ.ร.บ.สภานโยบายฯ มาตรา 45, 51 (อนุโลมมาตรา 38–39), 54–63 และข้อบังคับ/ระเบียบการเงินหมวดที่ 6', 'กำหนดกรอบวินัยการเงินการคลังสำหรับหน่วยงานของรัฐและทุนหมุนเวียน/เงินนอกงบประมาณ (มาตรา 4, 6–9), การแยกบัญชีเงินสำนักงาน (ม.45) ออกจากเงินกองทุน ววน. (ม.55), การจัดทำบัญชีและส่งรายงานการเงินต่อผู้สอบบัญชีและ สตง. (มาตรา 68–72 เชื่อมเส้นตาย 90 วัน และ 180 วัน) และการจัดให้มีระบบการควบคุมภายในและการตรวจสอบภายใน (มาตรา 79 เชื่อมกระบวนงาน P27 ของหน่วย IA)', 23, 'df3f51c596383e90...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1Lftoxkb6Fqv8XsnfaxznjYsxTgd3GP0Q/view?usp=drivesdk');
INSERT INTO documents VALUES (104, 'TSRI-F12-03-001', 'TSRI-DOC-0104', 'LAW-REL-003-2560', 12, 'หมวดที่ 12 (12.3 การจัดซื้อจัดจ้าง-พัสดุ)', 'LAW-REL-003-2560_พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ_พ.ศ.-2560_v0.1.pdf', 'พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 (ราชกิจจานุเบกษา 24 กุมภาพันธ์ 2560)', 'ระดับที่ 3: กฎหมายที่เกี่ยวข้อง (4.1.1.3)', 'B3, A2, A4', 'สำนัก F5 (ฝ่ายบริหารพัสดุ), F2 และทุกสำนัก', 'เชื่อมโยง พ.ร.บ.การส่งเสริม ววน. มาตรา 19, พ.ร.บ.สภานโยบายฯ มาตรา 45, 47→25(4)(ช), 50 และคำสั่งมอบอำนาจหมวดที่ 8 (พด.70–71/2564)', 'กำหนดหลักเกณฑ์การจัดซื้อจัดจ้างและการบริหารพัสดุของหน่วยงานของรัฐ (มาตรา 4, 6–8), ข้อยกเว้นและหลักเกณฑ์พิเศษสำหรับการจัดซื้อจัดจ้างเพื่อการวิจัยและพัฒนา (เชื่อมโยงมาตรา 19 แห่ง พ.ร.บ.การส่งเสริม ววน.), การกำหนดราคากลาง การบริหารสัญญาจ้างที่ปรึกษา/จ้างวิจัยภายใน (ทุน ORG คู่มือ DOC-0097) และการมอบอำนาจอนุมัติสั่งซื้อสั่งจ้างตามคำสั่ง พด.70/2564 (<=500,000 บาท แยก F5 vs F2) และ พด.71/2564 (<=10,000 บาท)', 42, '422da461beab8cfb...', 'ใช้งานจริง (G1 80% · รอรับรอง G2 75%)', 1, 'https://drive.google.com/file/d/1u1fSHVo8tWIcKHLt1_YkHCtZFOneognb/view?usp=drivesdk');
INSERT INTO crosslist_items VALUES ('CL-01', 'A1 (การจัดทำแผน ววน.)', 'สำนัก F1 (สำนักยุทธศาสตร์ฯ) / P01–P02', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.44(3), 41(1), 11(1) (TSRI-F01-01-001) ↔ พ.ร.บ.ส่งเสริม ววน. ม.6, 12(1)–(6), 13–15 (TSRI-F02-01-001)
INSERT INTO crosslist_items VALUES ('CL-02', 'A2 (การตั้งงบประมาณและกลั่นกรองคำขอ FF/SF)', 'สำนัก F1 & F2 / P03–P06', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.44(4)–(7), 41(2)–(5), 12(2) และ ฉ.2 พ.ศ. 2568 แก้ ม.12(1) (TSRI-F01-01-001, 002) ↔ พ.ร.บ.ส่งเสริม ววน. ม.16, 17(1)–(2)
INSERT INTO crosslist_items VALUES ('CL-03', 'A2 (การจัดสรรงบปลายน้ำและคำรับรอง Multi-year ม.18)', 'สำนัก F2 & F5 / P06–P07', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.41(7), 57(1) ↔ พ.ร.บ.ส่งเสริม ววน. (ฉ.2) พ.ศ. 2568 แก้ ม.18 (TSRI-F02-01-002)
INSERT INTO crosslist_items VALUES ('CL-04', 'B1 / A2 (ขอบเขตการทำวิจัยเองของ สกสว. ทุน ORG)', 'ทุกสำนัก (F1–F5, IU1–IU6) / P05, P23', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.43 วรรคสอง (ห้ามแข่งขันกับหน่วยรับงบ) ↔ พ.ร.บ.ส่งเสริม ววน. ม.7(1),(2) และ ม.9 วรรคหนึ่ง
INSERT INTO crosslist_items VALUES ('CL-05', 'A3 (การพัฒนากองทุน การหาผลประโยชน์ และการแยก 2 บัญชี)', 'สำนัก F3 & F5 / P10–P12, P25', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.45 (เงินและทรัพย์สินสำนักงาน) vs ม.54–59 (เงินและทรัพย์สินกองทุน ววน.)
INSERT INTO crosslist_items VALUES ('CL-06', 'A3 (การกำกับดูแล PMU และการใช้จ่ายเงินอุดหนุนของหน่วยบริหารทุน)', 'สำนัก F3 & F1 / P08–P12', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.41(8),(9),(13) ↔ พ.ร.บ.ส่งเสริม ววน. ม.7(2), 8, 9 (TSRI-F02-01-001)
INSERT INTO crosslist_items VALUES ('CL-07', 'A4 (การสร้างความร่วมมือต่างประเทศและการรับทุนต่างชาติ)', 'สำนัก F4 (สำนักขับเคลื่อนฯ) / P13–P14, P17', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.44(13) + ม.45(3),(4) + ม.55(3),(4) ↔ พ.ร.บ.ส่งเสริม ววน. ม.5(4), 11(6)
INSERT INTO crosslist_items VALUES ('CL-08', 'A4 (การขับเคลื่อนการใช้ประโยชน์ผลงานวิจัย TRIUP และรางวัล TBIR)', 'สำนัก F4 / P15–P18', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.44(11), 41(11), 54(4) ↔ พ.ร.บ.ส่งเสริม ววน. ม.28–31 ↔ พ.ร.บ.ส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2564 (TRIUP Act) (TSRI-F03-01-001)
INSERT INTO crosslist_items VALUES ('CL-09', 'A5 (ระบบฐานข้อมูลกลาง NRIIS มาตรฐานการวิจัย และโทษอาญา ม.36)', 'สำนัก F1 & หน่วยภารกิจ IU1 / P10, P19–P20', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.41(10),(14), 44(12),(14), 64–65 ↔ พ.ร.บ.ส่งเสริม ววน. ม.15, 22–27, 32–33 และบทกำหนดโทษอาญา ม.36 (จำคุกไม่เกิน 5 ปี / ปรับไม่เกิน 100,000 บาท)
INSERT INTO crosslist_items VALUES ('CL-10', 'B1 (โครงสร้างองค์กร 4 เสาหลัก อำนาจสั่งการ และการมอบอำนาจปี 2569)', 'สำนัก F5 (สำนักบริหารและพัฒนาองค์กร) / P21, P23', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.40–50 (ม.47 อนุโลม ม.25–27 อำนาจ อนก., ม.49 อนุโลม ม.29–33, 35–36 อำนาจ ผอ.)
INSERT INTO crosslist_items VALUES ('CL-11', 'B2 (การบริหารงานบุคคล โครงสร้างตำแหน่งปี 2569 สวัสดิการ และวินัย)', 'สำนัก F5 (ฝ่ายบริหารทรัพยากรบุคคล) / P24', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.43 วรรคสาม (ไม่ใช่ข้าราชการ), ม.47→25(4), ม.50(3)–(5)
INSERT INTO crosslist_items VALUES ('CL-12', 'B3 (การเงินการคลังสำนักงาน พัสดุวิจัย ม.19 และคำสั่งมอบอำนาจ พด.70–71/2564)', 'สำนัก F5 (ฝ่ายการเงิน/พัสดุ) & F2 / P25', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.45, 47→25(4)(ฉ)(ช) ↔ พ.ร.บ.ส่งเสริม ววน. ม.19 (พัสดุวิจัย) ↔ พ.ร.บ.จัดซื้อจัดจ้างฯ 2560 (หมวด 12: DOC-0104)
INSERT INTO crosslist_items VALUES ('CL-13', 'B4 (การบัญชี การตรวจสอบภายใน IA และรายงานประจำปี 2 เส้นทางคู่ขนาน)', 'สำนัก F5 & หน่วยตรวจสอบภายใน (IA) / P25–P27', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.51→38–39 (งบสำนักงานส่งผู้สอบบัญชีใน 90 วัน), ม.52 (รายงานประจำปีสำนักงาน) vs ม.60–63 (งบกองทุนส่ง สตง. ใน 180 วัน & คกก.ตรวจสอบ) vs ม.44(14) (รายงานกองทุน) ↔ พ.ร.บ.วินัยการเงินการคลังฯ 2561 ม.79
INSERT INTO crosslist_items VALUES ('CL-14', 'บทเฉพาะกาล (การบริหารสัญญารับโอน สกว. อดีต–ปัจจุบัน–อนาคต)', 'สำนัก F5 & F1 / P10, P25', 'ระดับที่ 1: พ.ร.บ.สภานโยบายฯ ม.66–80 (โดยเฉพาะ ม.71, 74–76, 80) ↔ พ.ร.บ.ส่งเสริม ววน. ม.37–39
INSERT INTO crosslist_items VALUES ('CL-15', 'A5 / A1 (การประเมินผลสัมฤทธิ์ของกฎหมายตามรัฐธรรมนูญ มาตรา 77)', 'สำนัก F1 & F5 / P01, P19, P23', 'ระดับที่ 1: รัฐธรรมนูญ มาตรา 77 & พ.ร.บ.หลักเกณฑ์การจัดทำร่างกฎหมายและการประเมินผลสัมฤทธิ์ของกฎหมาย พ.ศ. 2562
INSERT INTO interview_questions VALUES ('Q01 (PROC)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'ทุกกลุ่ม (เน้น 4.2.2 & 4.2.3)', 'ในกระบวนงานที่ท่านรับผิดชอบ ขั้นตอนเริ่มต้นจนถึงสิ้นสุดมีกี่ขั้นตอนหลัก และแต่ละขั้นตอนอ้างอิงระเบียบ ประกาศ คู่มือ หรือ SOP ฉบับใดเป็นฐานในการปฏิบัติงาน?', 'เชื่อมโยงคลังข้อมูลทั้ง 12 หมวด (TSRI-DOC-0001 ถึง 0104) โดยเฉพาะหมวด 9 คู่มือ (4 เล่ม) และหมวด 11 SOP จัดสรรงบ (DOC-0101)', 'D1 (ข้อกำหนดกฎหมาย), D2 (กฎรอง/SOP), D4 (การปฏิบัติจริง)', '• C1: มีคู่มือ/SOP ครอบคลุมครบทุกขั้นตอนหรือไม่
INSERT INTO interview_questions VALUES ('Q02 (AUTH)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'ทุกกลุ่ม (4.2.1, 4.2.2, 4.2.3)', 'ใครคือผู้มีอำนาจอนุมัติหรือให้ความเห็นชอบในขั้นตอนสุดท้ายของงานนี้ และใช้อำนาจตามมาตราใดของ พ.ร.บ. หรือตามคำสั่งมอบอำนาจฉบับใด (เช่น คำสั่ง พด.70/2564 หรือ พด.71/2564)?', 'พ.ร.บ.สภานโยบายฯ ม.44 (กสว.), ม.47 (อนก.), ม.50 (ผอ.สกสว.) และคำสั่งมอบอำนาจหมวด 4 (DOC-0053–60) & หมวด 8 (DOC-0094–95)', 'D1 (ฐานอำนาจ), D2 (คำสั่งมอบอำนาจ), D5 (ลายมือชื่อในเอกสารอนุมัติ)', '• C1: มีคำสั่งมอบอำนาจเป็นหนังสือชัดเจนหรือไม่
INSERT INTO interview_questions VALUES ('Q03 (ROLE)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.1 & 4.2.2', 'ในงานที่มีจุดตัดระหว่างสำนักหรือระหว่างคณะกรรมการ (กสว. vs อนก.สกสว.) มีการแบ่งแยกบทบาทหน้าที่ผู้เสนอ ผู้กลั่นกรอง และผู้อนุมัติอย่างไรเพื่อไม่ให้เกิดการก้าวล่วงอำนาจ?', 'พ.ร.บ.สภานโยบายฯ ม.44 vs ม.47 vs ม.50 และประกาศแบ่งส่วนงาน สกสว. พ.ศ. 2569 (TSRI-F04-00-012 / DOC-0063)', 'D1 (โครงสร้างอำนาจ 4 เสาหลัก), D2 (ประกาศแบ่งส่วนงานปี 2569), D4 (การชงเรื่องเข้าบอร์ด)', '• C1: วาระการประชุมระบุฐานอำนาจของคณะกรรมการถูกต้องหรือไม่
INSERT INTO interview_questions VALUES ('Q04 (COND)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.2 & 4.2.3', 'เงื่อนไขบังคับก่อน (Pre-conditions) ที่ต้องตรวจสอบให้ครบถ้วนก่อนอนุมัติหรือจัดสรรงบประมาณ/ทำคำรับรอง/เบิกจ่าย มีอะไรบ้าง และมี Checklist ตรวจสอบหรือไม่?', 'พ.ร.บ.ส่งเสริม ววน. ม.12, 17, 18 (ฉ.2 พ.ศ. 2568), ประกาศคำของบ >50 ข้อ (DOC-0007–0013) และคู่มือคำของบ FF (DOC-0099)', 'D1 (เงื่อนไขตามกฎหมาย), D2 (Checklist ตามคู่มือ), D5 (ใบตรวจรับ/แบบคำรับรองในแฟ้ม)', '• C1: มีแบบตรวจสอบเงื่อนไขครบทุกข้อตามประกาศ กสว. หรือไม่
INSERT INTO interview_questions VALUES ('Q05 (EXCEPT)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'ทุกกลุ่ม (4.2.1, 4.2.2, 4.2.3)', 'ข้อห้ามหรือข้อยกเว้นตามกฎหมายในงานของท่านมีอะไรบ้าง (เช่น ห้าม สกสว. ทำวิจัยแข่งขันกับหน่วยรับงบตาม ม.43 วรรคสอง หรือข้อยกเว้นการยึดเป็นเจ้าของผลงานตาม TRIUP ม.8) และมีวิธีคัดกรองอย่างไร?', 'พ.ร.บ.สภานโยบายฯ ม.43 วรรคสอง, พ.ร.บ.ส่งเสริม ววน. ม.9, พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ (TRIUP) ม.7–8 และคู่มือทุน ORG (DOC-0097)', 'D1 (บทบัญญัติข้อห้าม/ข้อยกเว้น), D3 (ความเข้าใจผู้ปฏิบัติ), D4 (การคัดกรองจริง)', '• C1: คู่มือ ORG และคู่มือ TRIUP ระบุเกณฑ์ข้อยกเว้นชัดเจนหรือไม่
INSERT INTO interview_questions VALUES ('Q06 (BALANCE)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.1 & 4.2.2 (รวม IA)', 'มีกลไกการตรวจสอบถ่วงดุล (Check & Balance) หรือการสอบทานความถูกต้องโดยหน่วยงานอิสระ (เช่น หน่วยตรวจสอบภายใน IA คณะกรรมการตรวจสอบ หรือคณะกรรมการประเมินอิสระ ม.64) ในขั้นตอนใดบ้าง?', 'พ.ร.บ.สภานโยบายฯ ม.60–65, ข้อบังคับการเงินและบัญชี 2563 (DOC-0079), ระเบียบการเงิน 2563 (DOC-0080)', 'D1 (กลไกถ่วงดุลตามกฎหมาย), D2 (กฎบัตร/ระเบียบการเงิน), D5 (รายงานผลการตรวจสอบ IA/สตง.)', '• C1: มีกลไกถ่วงดุลครบตามที่ พ.ร.บ. กำหนดหรือไม่
INSERT INTO interview_questions VALUES ('Q07 (KNOW)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.2 & 4.2.3', 'ในการปฏิบัติงานรายวัน ท่านใช้เอกสารฉบับใดเป็นคู่มืออ้างอิงหลัก และมีประเด็นข้อกฎหมายหรือระเบียบใดที่บุคลากรยังสับสนหรือตีความไม่ตรงกัน?', 'เชื่อมโยงหมวดที่ 9 คู่มือการดำเนินงาน 4 เล่ม (DOC-0096 ถึง 0099) และหมวดที่ 11 SOP (DOC-0101) สู่การออกแบบสื่อระยะที่ 4', 'D2 (คู่มือ/SOP), D3 (ความเข้าใจของผู้ปฏิบัติงาน)', '• C1: มีคู่มือที่อัปเดตเป็นปัจจุบัน (สะท้อน พ.ร.บ. ฉ.2 พ.ศ. 2568 และโครงสร้างปี 2569) หรือไม่
INSERT INTO interview_questions VALUES ('Q08 (EVID)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.2 & 4.2.3', 'หลักฐานเชิงประจักษ์ (Empirical Evidence) ที่ใช้พิสูจน์ว่าได้ปฏิบัติตามกฎหมายในขั้นตอนนี้คือเอกสารหรือข้อมูลดิจิทัลใด (เช่น บันทึกใน NRIIS/STARS, คำรับรอง ม.18, ใบสำคัญจ่าย, รายงานประชุม) และจัดเก็บไว้ที่ใด?', 'ครอบคลุมทั้ง 9 Clusters และห่วงโซ่หลักฐาน CHAIN-01 ถึง CHAIN-06', 'D4 (การปฏิบัติจริง), D5 (หลักฐานเชิงประจักษ์ในแฟ้ม/ระบบ)', '• C1: มีการจัดเก็บหลักฐานครบตามรายการที่ระเบียบกำหนดหรือไม่
INSERT INTO interview_questions VALUES ('Q09 (TIME)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.2 & 4.2.3', 'งานของท่านมีกรอบเวลาบังคับตามกฎหมายหรือระเบียบหรือไม่ (เช่น คืนเงิน PMU ใน 45 วัน, ปิดงบสำนักงาน 90 วัน / กองทุน 180 วัน, กลั่นกรองคำของบ 20 วัน, แจ้งผลงาน TRIUP) และสามารถทำได้ทันตามกำหนดหรือไม่?', 'ม.51→39 (90 วัน), ม.61 (180 วัน), ประกาศ PMU (45 วัน), ระเบียบชดใช้ทุน สกว. (เตือน 30 วัน / บอกเลิก 15 วัน), SOP งบ (45/20/20/15/10 วัน)', 'D1/D2 (กรอบเวลามาตรฐาน), D4/D5 (วันเวลาที่บันทึกจริงในระบบ/รับ-ส่งหนังสือ)', '• C1: มีปฏิทินควบคุมกำหนดเวลา (SLA / Deadline Alert) หรือไม่
INSERT INTO interview_questions VALUES ('Q10 (TRANS)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.2 & 4.2.3', 'เมื่อมีการแก้ไขกฎหมายหรือเปลี่ยนโครงสร้าง/ระเบียบใหม่ (เช่น พ.ร.บ. ฉ.2 พ.ศ. 2568, โครงสร้างส่วนงานปี 2569, หรือสัญญารับโอนจาก สกว.) ท่านมีวิธีตรวจสอบการบังคับใช้ตาม ''วันที่เกิดเหตุ'' อย่างไร?', 'บทเฉพาะกาล พ.ร.บ.สภานโยบายฯ ม.66–80, ระเบียบชดใช้ทุน สกว. 2564 (DOC-0005), ประกาศแบ่งส่วนงานปี 2569 (DOC-0063)', 'D1/D2 (บทเฉพาะกาลและวันบังคับใช้), D3 (การเลือกใช้เกณฑ์ตามวันเกิดเหตุ), D5 (บันทึกการพิจารณา)', '• C1: มีตารางเทียบเคียงเกณฑ์เก่า–เกณฑ์ใหม่ตามช่วงเวลาหรือไม่
INSERT INTO interview_questions VALUES ('Q11 (M77)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'กลุ่ม 4.2.1 & 4.2.2', 'จากรายงานการประเมินผลสัมฤทธิ์ของกฎหมายตามรัฐธรรมนูญ มาตรา 77 (645 หน้า) ใน 8 มาตรการหลัก สำนักของท่านได้นำข้อค้นพบไปปรับปรุงหลักเกณฑ์หรือกระบวนงานใดแล้วบ้าง?', 'หมวดที่ 10 รายงานการประเมินผลสัมฤทธิ์ พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (TSRI-F10-00-001 / DOC-0100)', 'D1 (รัฐธรรมนูญ ม.77), D2 (การปรับแก้กฎรอง), D4 (การขับเคลื่อนหลังประเมิน)', '• C1: มีแผนขับเคลื่อนข้อเสนอแนะทั้ง 8 มาตรการหรือไม่
INSERT INTO interview_questions VALUES ('Q12 (VALID)', 'ชุดคำถามแกนกลาง (Check & Balance 12 ข้อ)', 'ทุกกลุ่ม (4.2.1, 4.2.2, 4.2.3)', 'หากต้องจัดลำดับความสำคัญในการปรับปรุงกฎระเบียบ คู่มือ หรือพัฒนาระบบสื่อการเรียนรู้และคลังข้อสอบวัดสมรรถนะในระยะที่ 4 เรื่องใดคือ 3 อันดับแรกที่จำเป็นที่สุดสำหรับหน่วยงานของท่าน?', 'เชื่อมโยงผลการประเมิน C1 / C2 / A สู่การออกแบบคัมภีร์กฎหมาย 2 ฉบับ อินโฟกราฟิก 8 ชิ้น คลิป 15 คลิป และข้อสอบ 12 ชุด', 'D3 (ความต้องการพัฒนาสมรรถนะ), D4 (ข้อเสนอแนะเชิงปฏิบัติการ)', '• C1: ระบุหัวข้อกฎระเบียบและขั้นตอนที่ต้องการสื่อการเรียนรู้ได้ชัดเจน
INSERT INTO interview_questions VALUES ('QH01', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'คณะกรรมการ (กสว./อนก.) และผู้บริหารองค์กร (N=13)', '[ธรรมาภิบาล 4 เสาหลัก] ท่านมองว่าการแบ่งขอบเขตอำนาจระหว่าง สภานโยบายฯ, กสว. (ม.44), อนก.สกสว. (ม.47) และผู้อำนวยการ สกสว. (ม.50) ในทางปฏิบัติมีความชัดเจนเพียงใด และมีจุดใดที่เกิดการทับซ้อนหรือช่องว่างในการตัดสินใจ?', 'พ.ร.บ.สภานโยบายฯ ม.11, 44, 47, 50 และประกาศแบ่งส่วนงานปี 2569 (TSRI-F04-00-012)', 'D1, D2, D4 (Governance & Authority Alignment)', 'ประเมิน C1 (ความครบถ้วนของกรอบอำนาจ), C2 (การไม่ก้าวล่วงอำนาจระหว่างบอร์ด) และ A (ความคล่องตัวเชิงธรรมาภิบาล)', 'เชื่อมโยง CL-10 (Cluster B1) และคลิปที่ 1, 11');
INSERT INTO interview_questions VALUES ('QH02', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'กสว. / ผู้บริหารกำกับสำนัก F1', '[การจัดทำแผน ววน.] กระบวนการจัดทำแผนด้าน ววน. ให้ครบ 6 องค์ประกอบตาม ม.12 และการรับฟังความเห็นตาม ม.13 สามารถชี้นำการจัดสรรงบประมาณของประเทศได้จริงเพียงใด และผลประเมิน ม.77 สะท้อนจุดที่ต้องปรับปรุงอย่างไร?', 'พ.ร.บ.สภานโยบายฯ ม.44(3) ↔ พ.ร.บ.ส่งเสริม ววน. ม.6, 12–15 ↔ รายงาน ม.77 (TSRI-F10-00-001)', 'D1, D4, D5 (Strategic Alignment)', 'ประเมิน C1 (องค์ประกอบแผน 6 ด้าน), C2 (ขั้นตอนการเสนอเห็นชอบ) และ A (การเชื่อมโยงแผนสู่งบประมาณ)', 'เชื่อมโยง CL-01 & CL-15 (Cluster A1/A5) และคลิปที่ 1, 2');
INSERT INTO interview_questions VALUES ('QH03', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'คกก.งบประมาณ ม.12(2) / ผู้บริหารกำกับสำนัก F1–F2', '[งบประมาณต้นน้ำ 2 สาย] การกลั่นกรองคำของบประมาณระบบ ววน. ตามวงจรล่วงหน้า 2 ปี (ปี T ถึง T+2) และการแยกช่องทางหน่วยรับงบ ววน. กับส่วนราชการตาม ม.17 มีความท้าทายเชิงระบบอย่างไรหลังการแก้ไข พ.ร.บ. ฉบับที่ 2 พ.ศ. 2568?', 'พ.ร.บ.สภานโยบายฯ (ฉ.2) พ.ศ. 2568 แก้ ม.12(1) ↔ พ.ร.บ.ส่งเสริม ววน. ม.16–17 ↔ SOP จัดสรรงบ (DOC-0101)', 'D1, D2, D4 (Upstream Budget Governance)', 'ประเมิน C1 (เกณฑ์คำของบ >50 ข้อ), C2 (กรอบเวลาและองค์กรกลั่นกรอง) และ A (การบูรณาการกับสำนักงบประมาณ)', 'เชื่อมโยง CL-02 (Cluster A2) และคลิปที่ 3, 5');
INSERT INTO interview_questions VALUES ('QH04', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'กสว. / ผู้บริหารกำกับสำนัก F2', '[การจัดสรรปลายน้ำและคำรับรอง ม.18] การเปลี่ยนจากระบบสัญญารายโครงการมาสู่ ''คำรับรองการจัดสรรงบประมาณ'' และการตั้งงบผูกพันข้ามปี (Multi-year Promised Grant) ตาม ม.18 ที่แก้ไขใหม่ ช่วยปลดล็อกคอขวดของหน่วยรับงบได้เพียงใด?', 'พ.ร.บ.ส่งเสริม ววน. (ฉ.2) พ.ศ. 2568 แก้ ม.18 (TSRI-F02-01-002) & ประกาศคำของบ ฉ.3 พ.ศ. 2569 (DOC-0011)', 'D1, D2, D4, D5 (Downstream Allocation & Multi-year Grant)', 'ประเมิน C1 (แบบคำรับรองและเกณฑ์ 50:50), C2 (การอนุมัติโดย กสว. ก่อนแจ้งจัดสรร) และ A (ความคล่องตัวของหน่วยรับงบ)', 'เชื่อมโยง CL-03 (Cluster A2) และคลิปที่ 5');
INSERT INTO interview_questions VALUES ('QH05', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'ผู้อำนวยการ สกสว. / ผู้บริหารกำกับสำนัก F1–F5', '[ขอบเขตการทำวิจัยเองของ สกสว.] สกสว. มีนโยบายและเกณฑ์กำกับดูแลโครงการวิจัยภายใน (ทุน ORG) อย่างไรเพื่อให้มั่นใจว่าเป็นไปเพื่อพัฒนางานนโยบายของ สกสว. ตาม ม.9 และไม่แข่งขันกับหน่วยรับงบตาม ม.43 วรรคสอง?', 'พ.ร.บ.สภานโยบายฯ ม.43 วรรคสอง ↔ พ.ร.บ.ส่งเสริม ววน. ม.7, 9 ↔ คู่มือบริหารโครงการ ORG (DOC-0097)', 'D1, D2, D4 (Internal Research Boundary)', 'ประเมิน C1 (คู่มือ ORG 50 หน้า), C2 (การไม่ทำวิจัยแข่งขันกับหน่วยรับงบ) และ A (การนำผลวิจัย ORG ไปใช้ประโยชน์จริง)', 'เชื่อมโยง CL-04 (Cluster B1/A2) และคลิปที่ 4');
INSERT INTO interview_questions VALUES ('QH06', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'กสว. / ผู้บริหารกำกับสำนัก F3 & F5', '[การพัฒนากองทุนและกำกับ PMU] กลไกการนำเงินกองทุนไปหาผลประโยชน์ การแยกบัญชีเงินกองทุน (ม.55) ออกจากเงินสำนักงาน (ม.45) และการกำกับดูแลการใช้จ่ายเงินอุดหนุนของ PMU (รวมถึงการคืนเงินใน 45 วัน) มีความรัดกุมเพียงใด?', 'ม.45 vs ม.54–59, ระเบียบบริหารกองทุน (DOC-0003), ประกาศหาผลประโยชน์ (DOC-0015), ประกาศ PMU ฉ.1–3 (DOC-0016–18)', 'D1, D2, D4, D5 (Fund Development & PMU Governance)', 'ประเมิน C1 (เกณฑ์หาผลประโยชน์และประกาศ PMU), C2 (การแยก 2 บัญชีและการคืนเงิน 45 วัน) และ A (ประสิทธิภาพการบริหารกองทุน)', 'เชื่อมโยง CL-05 & CL-06 (Cluster A3) และคลิปที่ 6, 7');
INSERT INTO interview_questions VALUES ('QH07', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'กสว. / ผู้บริหารกำกับสำนัก F4', '[การขับเคลื่อนการใช้ประโยชน์ TRIUP และความร่วมมือ] การบังคับใช้ พ.ร.บ.ส่งเสริมการใช้ประโยชน์ผลงานวิจัยฯ พ.ศ. 2564 (และกฎรอง 14 ฉบับ) รวมถึงการทำความตกลงความร่วมมือต่างประเทศ สามารถผลักดันผลงานวิจัยสู่ภาคเศรษฐกิจและสังคมได้ตามเป้าหมายหรือไม่?', 'หมวดที่ 3 พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ 2564 และกฎรองรวม 15 ไฟล์ (DOC-0037–0051) & ประกาศความร่วมมือ 2566 (DOC-0020)', 'D1, D2, D4 (Research Utilization & International Cooperation)', 'ประเมิน C1 (ความครบถ้วนของกฎรอง TRIUP 14 ฉบับ), C2 (การให้ผู้รับทุนเป็นเจ้าของผลงานตามเงื่อนไข) และ A (แรงจูงใจในการนำผลงานไปใช้ประโยชน์)', 'เชื่อมโยง CL-07 & CL-08 (Cluster A4) และคลิปที่ 8, 9');
INSERT INTO interview_questions VALUES ('QH08', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'คกก.ติดตามประเมินผล / ผู้บริหารกำกับสำนัก F1 & IU1', '[ฐานข้อมูลกลาง NRIIS และการประเมินผล] ระบบฐานข้อมูลกลาง (NRIIS) มีมาตรการคุ้มครองความลับตาม ม.24–25 (ซึ่งมีโทษอาญาตาม ม.36) และการเชื่อมโยงข้อมูลเพื่อใช้ประเมินผลสัมฤทธิ์ตาม ม.64–65 และ ม.77 อย่างไร?', 'พ.ร.บ.สภานโยบายฯ ม.64–65 ↔ พ.ร.บ.ส่งเสริม ววน. ม.22–27, 36 ↔ ระเบียบข้อมูล ววน. (DOC-0028, 0031)', 'D1, D2, D4, D5 (Data Governance & M&E)', 'ประเมิน C1 (ระเบียบฐานข้อมูลและชั้นความลับ), C2 (การรักษาความลับและส่งข้อมูลครบถ้วน) และ A (คุณภาพข้อมูลเพื่อการตัดสินใจ)', 'เชื่อมโยง CL-09 & CL-15 (Cluster A5) และคลิปที่ 10');
INSERT INTO interview_questions VALUES ('QH09', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'อนก.สกสว. / ผู้อำนวยการ สกสว. / ผู้บริหารกำกับสำนัก F5', '[โครงสร้างปี 2569 บริหารบุคคล และจริยธรรม] การปรับโครงสร้างส่วนงานและบัญชีเงินเดือนใหม่ พ.ศ. 2569 (Level 1–8 / 1A–8A) ควบคู่กับข้อบังคับบุคคล วินัย และประมวลจริยธรรม (No Gift Policy) ช่วยเสริมสร้างสมรรถนะและธรรมาภิบาลของบุคลากรอย่างไร?', 'หมวดที่ 4 โครงสร้างปี 2569 (DOC-0061–64), หมวดที่ 5 บุคคล (DOC-0066–78), หมวดที่ 7 จริยธรรม (DOC-0087–93) & คู่มือวินัย (DOC-0096)', 'D1, D2, D4 (Organization, HR & Ethics Governance)', 'ประเมิน C1 (ความครบถ้วนของระเบียบปี 2569 และคู่มือวินัย), C2 (การปฏิบัติตามขั้นตอนสรรหา/ประเมิน/วินัย) และ A (ความเหมาะสมของโครงสร้างอัตราเงินเดือนและสวัสดิการ)', 'เชื่อมโยง CL-10 & CL-11 (Cluster B1/B2) และคลิปที่ 11, 12');
INSERT INTO interview_questions VALUES ('QH10', 'แบบสัมภาษณ์ผู้บริหาร (FORM-WS03-001: กลุ่ม 4.2.1)', 'คกก.ตรวจสอบ / ผู้บริหารกำกับสำนัก F5 / หัวหน้าหน่วย IA', '[การเงิน พัสดุ และการตรวจสอบภายใน] กลไกการควบคุมภายในสำหรับคำสั่งมอบอำนาจพัสดุ (พด.70–71/2564) การปิดบัญชีคู่ขนาน (สำนักงาน 90 วัน vs กองทุน 180 วัน) และการบริหารสัญญารับโอนจาก สกว. มีความเสี่ยงใดที่ต้องเฝ้าระวังเป็นพิเศษ?', 'ม.51→38–39 (90 วัน), ม.60–63 (180 วัน), หมวด 6 การเงิน (DOC-0079–86), หมวด 8 พัสดุ (DOC-0094–95), คู่มือการเงิน (DOC-0098), ระเบียบชดใช้ทุน สกว. (DOC-0005)', 'D1, D2, D4, D5 (Financial Control, Procurement & Internal Audit)', 'ประเมิน C1 (คู่มือการเงินและตารางมอบอำนาจ), C2 (การอนุมัติถูกสายเงินและการส่งงบการเงินทัน 90/180 วัน) และ A (ประสิทธิภาพการควบคุมภายใน)', 'เชื่อมโยง CL-12, CL-13 & CL-14 (Cluster B3/B4) และคลิปที่ 13, 14, 15');
INSERT INTO interview_questions VALUES ('QO01', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F1 (P01–P02)', '[Walkthrough การจัดทำแผน ววน.] ขอเดินตามเอกสารจริงในการจัดทำ/ทบทวนแผนด้าน ววน.: ตรวจสอบว่ามีการรวบรวมข้อมูลครบ 6 องค์ประกอบตาม ม.12(1)–(6) บันทึกการรับฟังความเห็นตาม ม.13 และมติเห็นชอบตามลำดับขั้นอย่างไร?', 'พ.ร.บ.ส่งเสริม ววน. ม.12–15 (TSRI-F02-01-001) & รายงานประเมิน ม.77 (TSRI-F10-00-001)', 'D2, D3, D4, D5 (ตรวจแฟ้มแผน ววน. และรายงานการรับฟังความเห็น)', 'ตรวจรายการหลักฐานเทียบ Checklist ม.12(1)–(6) และบันทึกเวลาการเสนอเรื่อง', 'เชื่อมโยง CASE-A1-01 และ CHAIN-01');
INSERT INTO interview_questions VALUES ('QO02', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F1 & F2 (P03–P05)', '[Walkthrough คำของบและการคัดแยก FF/SF] ขอเดินตามเอกสารจริงในระบบ NRIIS/STARS: เมื่อหน่วยรับงบยื่นคำขอภายใน 45 วัน เจ้าหน้าที่ใช้ Checklist ใดตรวจเงื่อนไขตามประกาศ กสว. (>50 ข้อ) และคัดแยกคำขอ FF (8 โปรแกรม) กับ SF อย่างไร?', 'ประกาศ กสว. หลักเกณฑ์คำของบ 7 ฉบับ (DOC-0007–0013), คู่มือคำของบ FF 180 หน้า (DOC-0099) & SOP จัดสรรงบ (DOC-0101)', 'D2, D3, D4, D5 (ตรวจบันทึกการกลั่นกรองใน NRIIS/STARS กรอบ 20+20 วัน)', 'ตรวจความครบถ้วนของแบบตรวจคัดกรองและการปฏิบัติตามกรอบเวลาใน SOP', 'เชื่อมโยง CASE-A2-01, CHAIN-01 และคลิปที่ 3, 4');
INSERT INTO interview_questions VALUES ('QO03', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F2 (P06–P07)', '[Walkthrough การจัดสรร Pre-ceiling และคำรับรอง ม.18] ขอเดินตามเอกสารจริงตั้งแต่แจ้งยอด Pre-ceiling (ปรับใน 15 วัน ตรวจใน 10 วัน) การปรับตามมติ กมธ.งบประมาณ จนถึงการออก ''คำรับรองการจัดสรรงบประมาณ'' และการผูกพันงบข้ามปี (50:50) ทำอย่างไร?', 'พ.ร.บ.ส่งเสริม ววน. (ฉ.2) พ.ศ. 2568 แก้ ม.18 (DOC-0026) & ประกาศคำของบ ฉ.3 พ.ศ. 2569 ข้อ 44, 44/1, 44/2, 49 (DOC-0011)', 'D1, D2, D4, D5 (ตรวจแฟ้มคำรับรอง ม.18 และตารางคุมวงเงินผูกพันข้ามปี)', 'ตรวจความถูกต้องของแบบคำรับรอง ม.18 และมติ กสว. อนุมัติจัดสรร', 'เชื่อมโยง CASE-A2-01, CHAIN-01 และคลิปที่ 5');
INSERT INTO interview_questions VALUES ('QO04', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F2 & F5 (P07, P25)', '[Walkthrough การเบิกจ่ายเงินอุดหนุนและระงับจัดสรร] ในกรณีที่หน่วยรับงบประมาณขอเปลี่ยนแปลงรายละเอียดโครงการหรือปฏิบัติไม่เป็นไปตามคำรับรอง ม.18 เจ้าหน้าที่ใช้เกณฑ์ใดในการพิจารณาอนุมัติแก้ไขหรือเสนอระงับการจัดสรรงบประมาณ?', 'ประกาศคำของบ ข้อ 44–49 (DOC-0007, 0011), ระเบียบรับจ่ายเงินกองทุน 2566 (DOC-0006) & คู่มือการเงินสายที่ 3 (DOC-0098)', 'D2, D3, D4, D5 (ตรวจแฟ้มขออนุมัติเปลี่ยนแปลงและหลักฐานการโอนเงินกองทุน)', 'ตรวจความตรงกันของอำนาจอนุมัติ (ผอ.สำนัก F2 <=500,000 บาท ตาม พด.70/2564) และเงื่อนไขคำรับรอง', 'เชื่อมโยง CHAIN-01 & CHAIN-04');
INSERT INTO interview_questions VALUES ('QO05', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน ทุกสำนัก (P05, P23)', '[Walkthrough โครงการวิจัยภายใน ORG] ขอเดินตามแฟ้มโครงการทุน ORG (เช่น สัญญา ORG68F5006): มีการตรวจสอบขอบเขตงานตาม ม.43 วรรคสอง (ไม่แข่งขันกับหน่วยรับงบ) และ ม.9 อย่างไร และใช้แบบฟอร์มตามคู่มือบริหารโครงการ ORG (50 หน้า) ครบถ้วนหรือไม่?', 'พ.ร.บ.สภานโยบายฯ ม.43 วรรคสอง, พ.ร.บ.ส่งเสริม ววน. ม.9 & คู่มือบริหารโครงการ ORG (TSRI-F09-00-002 / DOC-0097)', 'D1, D2, D4, D5 (ตรวจแฟ้มสัญญา ORG, TOR, รายงานการตรวจรับ)', 'ตรวจการอ้างอิงฐานอำนาจ ม.43 วรรคสอง และ ม.9 ในบันทึกขออนุมัติโครงการ ORG', 'เชื่อมโยง CL-04, CASE-A2-01 และคลิปที่ 4');
INSERT INTO interview_questions VALUES ('QO06', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F3 & F5 (P08–P12)', '[Walkthrough การกำกับ PMU และการคืนเงิน 45 วัน] ขอเดินตามแฟ้มกำกับดูแล PMU และการบริหารเงินกองทุน: เจ้าหน้าที่ตรวจสอบการแยกบัญชีเงินอุดหนุนของ PMU การขอขยายเวลาใช้จ่าย (<=1 ปี) และการส่งคืนเงินเหลือจ่ายพร้อมดอกเบี้ยภายใน 45 วันอย่างไร?', 'ประกาศ กสว. การใช้จ่ายเงินอุดหนุนของ PMU ฉ.1–3 (DOC-0016–0018), ระเบียบบริหารกองทุน (DOC-0003) & ประกาศหาผลประโยชน์ (DOC-0015)', 'D2, D3, D4, D5 (ตรวจทะเบียนคุมเงินเหลือจ่ายและใบนำส่งเงินคืนคลัง/กองทุนภายใน 45 วัน)', 'ตรวจวันที่สิ้นสุดสัญญาเทียบกับวันที่ PMU ส่งคืนเงินและดอกเบี้ย (<=45 วัน)', 'เชื่อมโยง CASE-A3-01, CHAIN-04 และคลิปที่ 6, 7');
INSERT INTO interview_questions VALUES ('QO07', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F4 (P13–P18)', '[Walkthrough การใช้ประโยชน์ผลงานวิจัย TRIUP] ขอเดินตามแฟ้มการแจ้งผลงานวิจัยและการขอเป็นเจ้าของผลงานตาม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564: มีการตรวจระยะเวลาแจ้งผลงาน เงื่อนไขข้อยกเว้น ม.8 และการรายงานการใช้ประโยชน์ตามกฎรองทั้ง 14 ฉบับอย่างไร?', 'หมวดที่ 3 พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564 และกฎรอง 14 ฉบับ (TSRI-F03-01-001 ถึง 06-001 / DOC-0037–0051)', 'D1, D2, D4, D5 (ตรวจหนังสือแจ้งผลงานวิจัย คำขอเป็นเจ้าของ และรายงานการใช้ประโยชน์)', 'ตรวจความครบถ้วนของเอกสารตามคู่มือ TRIUP 2 เล่ม (DOC-0050, 0051) และกรอบเวลาตามประกาศ กสว.', 'เชื่อมโยง CASE-A4-01, CHAIN-02 และคลิปที่ 8, 9');
INSERT INTO interview_questions VALUES ('QO08', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F1 & หน่วยภารกิจ IU1 (P10, P19–P20)', '[Walkthrough ระบบฐานข้อมูล NRIIS และชั้นความลับ ม.36] ขอเดินตามกระบวนการรับส่งข้อมูลในระบบ NRIIS: มีการกำหนดสิทธิ์การเข้าถึงข้อมูลที่มีชั้นความลับตาม ม.24–25 เพื่อป้องกันการเปิดเผยข้อมูลโดยมิชอบ (โทษอาญา ม.36) และการตรวจความครบถ้วนของข้อมูลประเมินผลอย่างไร?', 'พ.ร.บ.ส่งเสริม ววน. ม.22–27, 36 (DOC-0025), ระเบียบสภานโยบายฯ ข้อมูล ววน. (DOC-0028), ระเบียบ กสว. ฐานข้อมูล (DOC-0031)', 'D1, D2, D4, D5 (ตรวจ Log การกำหนดสิทธิ์ผู้ใช้งาน NRIIS และบันทึกข้อตกลงรักษาความลับ)', 'ตรวจการแบ่งชั้นความลับและการตั้งค่า Access Control ในระบบฐานข้อมูลกลาง', 'เชื่อมโยง CASE-A5-01, CHAIN-06 และคลิปที่ 10');
INSERT INTO interview_questions VALUES ('QO09', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F5 ด้านโครงสร้าง/บุคคล/จริยธรรม (P21–P24)', '[Walkthrough งานบุคคล โครงสร้างปี 2569 และวินัย] ขอเดินตามแฟ้มงานบุคคลและวินัย: การจัดระดับตำแหน่งตามระเบียบปี 2569 (Level 1–8 / 1A–8A), การทดลองงาน (90–180 วัน), การปฏิบัติงานที่บ้าน (WFH 80:20) และการดำเนินการทางวินัยตามคู่มือวินัย (111 หน้า แบบ วน.1–วน.8) ทำอย่างไร?', 'หมวด 4 โครงสร้างปี 2569 (DOC-0061–64), หมวด 5 บุคคล (DOC-0066–78), หมวด 7 จริยธรรม (DOC-0087–93) & คู่มือวินัย (DOC-0096)', 'D2, D3, D4, D5 (ตรวจคำสั่งบรรจุ/แต่งตั้ง, แบบประเมิน, และสำนวนการสอบสวนวินัย)', 'ตรวจการใช้ข้อบังคับให้ตรงวันเกิดเหตุและการใช้แบบฟอร์มมาตรฐาน วน.1–วน.8', 'เชื่อมโยง CASE-B1-01, CASE-B2-01, CHAIN-03 และคลิปที่ 11, 12');
INSERT INTO interview_questions VALUES ('QO10', 'แบบสัมภาษณ์ปฏิบัติการ & Walkthrough (FORM-WS03-002: กลุ่ม 4.2.2 & 4.2.3)', 'หัวหน้าฝ่ายและผู้ปฏิบัติงาน สำนัก F5 ด้านการเงิน/พัสดุ/สัญญา สกว. & หน่วย IA (P25–P27)', '[Walkthrough การเงิน พัสดุ ปิดบัญชี 90/180 วัน และสัญญา สกว.] ขอเดินตามใบสำคัญจ่ายและแฟ้มพัสดุ: การตรวจแหล่งเงินและอำนาจอนุมัติตาม พด.70–71/2564 (<=500,000 บาท แยก F5 กับ F2), การปิดงบสำนักงานใน 90 วัน vs กองทุน 180 วัน และการติดตามหนี้โครงการรับโอน สกว. (เตือน 30 วัน / บอกเลิก 15 วัน) ทำอย่างไร?', 'หมวด 6 การเงิน (DOC-0079–86), หมวด 8 พัสดุ (DOC-0094–95), คู่มือการเงิน (DOC-0098), ระเบียบชดใช้ทุน สกว. (DOC-0005)', 'D1, D2, D4, D5 (ตรวจใบสั่งซื้อ/จ้าง, ใบสำคัญจ่าย, งบทดลอง 2 บัญชี, แฟ้มติดตามหนี้ สกว.)', 'ตรวจลายมือชื่อผู้อนุมัติเทียบแหล่งเงิน (ม.45 vs ม.55) และวันครบกำหนดส่งงบการเงิน', 'เชื่อมโยง CASE-B3-01, CASE-B4-01, CHAIN-04, CHAIN-05 และคลิปที่ 13, 14, 15');
INSERT INTO learning_clips VALUES (1, 'CLIP-01', 'A1 (การจัดทำแผน ววน.)', 'คณะกรรมการ (กสว. / อนก.)', '80 : 20', 'คลิปยาว 3–5 นาที (Concept + Case)', 'แยกบทบาทผู้เสนอแผนและผู้เห็นชอบ: เส้นแบ่งอำนาจ สภานโยบายฯ – กสว. – สำนักงาน', 'เข้าใจโครงสร้างอำนาจในการจัดทำและให้ความเห็นชอบแผนด้าน ววน. ตาม ม.11(1), ม.41(1) และ ม.44(3) โดยไม่ก้าวล่วงบทบาทระหว่างฝ่ายจัดการและฝ่ายกำกับนโยบาย', '• Hook (0:00–0:45): กรณีศึกษาเมื่อฝ่ายเลขานุการเสนอร่างแผนที่ปรับแก้ตัวชี้วัดโดยยังไม่ผ่านการรับฟังความเห็นตาม ม.13
INSERT INTO learning_clips VALUES (2, 'CLIP-02', 'A1 (การจัดทำแผน ววน.)', 'ผู้บริหารระดับสูง', '60 : 40', 'คลิปยาว 3–5 นาที (Concept + Case)', 'อ่านมติและเงื่อนไขแผนด้าน ววน. 6 องค์ประกอบ: จุดเชื่อมจากยุทธศาสตร์สู่งบประมาณ', 'ตรวจสอบความครบถ้วนขององค์ประกอบแผนด้าน ววน. ทั้ง 6 ด้านตาม พ.ร.บ.ส่งเสริม ววน. ม.12(1)–(6) และการเชื่อมโยงสู่กรอบวงเงินงบประมาณประจำปี', '• Hook (0:00–0:45): ทำไมแผนด้าน ววน. ที่ขาดการกำหนดสัดส่วนงบประมาณตาม ม.12(5) จึงทำให้ขั้นตอนตั้งงบประมาณสะดุด?
INSERT INTO learning_clips VALUES (3, 'CLIP-03', 'A2 (การตั้งและจัดสรรงบประมาณ)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปยาว 3–5 นาที (Walkthrough + Case)', 'กลั่นกรองคำของบประมาณ FF ตามคู่มือ 180 หน้า และประกาศ กสว. (>50 ข้อ)', 'ปฏิบัติตามขั้นตอนและกรอบเวลากลั่นกรองคำของบประมาณ Fundamental Fund (FF) ในระบบ NRIIS ตามคู่มือคำของบ FF และ SOP จัดสรรงบประมาณได้อย่างถูกต้อง', '• Hook (0:00–0:45): สถานการณ์เมื่อหน่วยรับงบประมาณยื่นคำขอ FF ล่าช้าหรือผิดหมวดจาก 8 โปรแกรม 16 แผนงาน
INSERT INTO learning_clips VALUES (4, 'CLIP-04', 'A2 & B1 (ขอบเขตการทำวิจัยเอง ทุน ORG)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'ตรวจคำขอ SF และข้อยกเว้นการทำวิจัยเองของ สกสว. (ทุน ORG) ตามมาตรา 43 วรรคสอง', 'จำแนกขอบเขตโครงการวิจัยที่ สกสว. ทำได้เอง (เฉพาะเพื่อพัฒนานโยบายและงานของ สกสว. ตาม ม.9) ออกจากโครงการที่ห้ามทำแข่งขันกับหน่วยรับงบประมาณตาม ม.43 วรรคสอง', '• 0:00–0:15: กฎเหล็ก ม.43 วรรคสอง ''สกสว. ต้องไม่ทำวิจัยแข่งขันกับหน่วยรับงบประมาณ''
INSERT INTO learning_clips VALUES (5, 'CLIP-05', 'A2 (การจัดสรรปลายน้ำและคำรับรอง ม.18)', 'ผู้บริหารระดับกลาง (ผอ.สำนัก)', '45 : 55', 'คลิปยาว 3–5 นาที (Concept + Case)', 'ไล่วงเงินจาก Pre-ceiling ถึงคำรับรอง ม.18 และงบผูกพันข้ามปี (Multi-year 50:50)', 'กำกับกระบวนการแจ้งยอด Pre-ceiling การปรับคำชี้แจงตามมติ กมธ.งบประมาณ และการออกคำรับรองการจัดสรรงบประมาณตาม ม.18 ที่แก้ไขใหม่ พ.ศ. 2568', '• Hook (0:00–0:45): จุดเปลี่ยนสำคัญเมื่อ พ.ร.บ.ส่งเสริม ววน. (ฉ.2) พ.ศ. 2568 เปลี่ยนจาก ''สัญญารายโครงการ'' เป็น ''คำรับรองการจัดสรรงบประมาณ''
INSERT INTO learning_clips VALUES (6, 'CLIP-06', 'A3 (การพัฒนากองทุนและแยก 2 บัญชี)', 'ผู้บริหารระดับกลาง (ผอ.สำนัก)', '45 : 55', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'จำแนกแหล่งเงินกองทุน (ม.55) ออกจากเงินสำนักงาน (ม.45) และการรับบริจาค', 'คัดแยกรายรับและค่าใช้จ่ายของกองทุน ววน. (ม.54–59) ออกจากเงินของสำนักงาน สกสว. (ม.45) ได้อย่างถูกต้องตามระเบียบบริหารกองทุน', '• 0:00–0:15: เงินบริจาคหรือผลประโยชน์ที่เกิดขึ้น ต้องเข้าบัญชีไหน?
INSERT INTO learning_clips VALUES (7, 'CLIP-07', 'A3 (การหาผลประโยชน์และกำกับ PMU)', 'ผู้บริหารระดับสูง', '60 : 40', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'ตรวจการนำเงินกองทุนไปหาผลประโยชน์และกฎเหล็กคืนเงิน PMU ภายใน 45 วัน', 'กำกับดูแลการนำเงินกองทุนไปหาผลประโยชน์ตามประกาศ กสว. พ.ศ. 2563 และการติดตามให้ PMU ส่งคืนเงินเหลือจ่ายพร้อมดอกเบี้ยภายใน 45 วัน', '• 0:00–0:15: PMU สิ้นสุดปีงบประมาณแล้ว เงินเหลือจ่ายและดอกเบี้ยต้องจัดการอย่างไร?
INSERT INTO learning_clips VALUES (8, 'CLIP-08', 'A4 (การขับเคลื่อนการใช้ประโยชน์ TRIUP)', 'ผู้บริหารระดับกลาง (ผอ.สำนัก)', '45 : 55', 'คลิปยาว 3–5 นาที (Concept + Case)', 'ตรวจสิทธิในผลงานวิจัยตามสัญญาทุนและ พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ (TRIUP) พ.ศ. 2564', 'วินิจฉัยสิทธิการเป็นเจ้าของผลงานวิจัยของผู้รับทุนและนักวิจัยตามหลักเกณฑ์ของ TRIUP Act และเงื่อนไขข้อยกเว้นที่ผู้ให้ทุนขอถือสิทธิเองตามมาตรา 8', '• Hook (0:00–0:45): เมื่อมหาวิทยาลัยผู้รับทุนต้องการนำผลงานวิจัยไปจดสิทธิบัตรและอนุญาตให้เอกชนใช้สิทธิ สกสว. ต้องตรวจอะไรบ้าง?
INSERT INTO learning_clips VALUES (9, 'CLIP-09', 'A4 (การแจ้งผลงานและรายงานการใช้ประโยชน์ TRIUP)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'การเปิดเผยผลงานวิจัยและการรายงานการใช้ประโยชน์ภายในระยะเวลาที่กำหนด', 'ตรวจสอบระยะเวลาและแบบฟอร์มในการแจ้งเกิดผลงานวิจัย การยื่นขอเป็นเจ้าของ และการรายงานผลการใช้ประโยชน์ตามประกาศ กสว.', '• 0:00–0:15: นักวิจัยได้ผลงานวิจัยใหม่ ต้องแจ้งภายในกี่วัน และรายงานผลอย่างไร?
INSERT INTO learning_clips VALUES (10, 'CLIP-10', 'A5 (ฐานข้อมูล NRIIS และการประเมินผล ม.77)', 'ผู้บริหารระดับกลาง (ผอ.สำนัก / หัวหน้าหน่วย IU1)', '45 : 55', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'ติดตามตัวชี้วัด ฐานข้อมูลกลาง NRIIS (โทษอาญา ม.36) และผลประเมิน ม.77', 'กำกับการส่งข้อมูลเข้าสู่ระบบฐานข้อมูลกลาง NRIIS การรักษาความลับตามมาตรา 24–25 (โทษอาญา ม.36) และการนำผลประเมิน ม.77 ไปใช้พัฒนาหลักเกณฑ์', '• 0:00–0:15: ข้อมูลโครงการวิจัยที่ยังไม่เปิดเผยใน NRIIS หากรั่วไหลมีโทษอาญาถึงขั้นจำคุก!
INSERT INTO learning_clips VALUES (11, 'CLIP-11', 'B1 (โครงสร้างองค์กรปี 2569 และการมอบอำนาจ)', 'ผู้บริหารระดับสูง', '60 : 40', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'แยกการกำกับส่วนงานตามประกาศปี 2569 ออกจากคำสั่งมอบอำนาจอนุมัติรายธุรกรรม', 'จำแนกขอบเขตการมอบหมายผู้บริหารกำกับดูแลสำนัก (F1–F5) ตามโครงสร้างปี 2569 ออกจากอำนาจอนุมัติจัดซื้อจัดจ้างและสั่งจ่ายเงินรายธุรกรรม', '• 0:00–0:15: การได้รับมอบหมายให้กำกับดูแลสำนัก หมายถึงมีอำนาจอนุมัติพัสดุและสั่งจ่ายเงินทุกวงเงินหรือไม่?
INSERT INTO learning_clips VALUES (12, 'CLIP-12', 'B2 (การบริหารงานบุคคลและวินัย)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'ใช้ข้อบังคับบุคคล โครงสร้างตำแหน่งปี 2569 และคู่มือวินัยตาม ''วันที่เกิดเหตุ''', 'เลือกใช้ข้อบังคับบริหารงานบุคคล ระเบียบกำหนดตำแหน่งและเงินเดือน พ.ศ. 2569 และคู่มือการดำเนินการทางวินัย (111 หน้า) ให้ถูกต้องตามวันที่เกิดข้อเท็จจริง', '• 0:00–0:15: เมื่อเกิดกรณีร้องเรียนหรือพิจารณาสิทธิบุคลากรข้ามปี จะใช้ระเบียบฉบับปีไหน?
INSERT INTO learning_clips VALUES (13, 'CLIP-13', 'B3 (การเงินและพัสดุ 2 สายเงิน)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปยาว 3–5 นาที (Walkthrough + Case)', 'ตรวจแหล่งเงินและวงเงินอนุมัติพัสดุ 500,000 บาท (พด.70/2564) ตามคู่มือการเงิน 3 สาย', 'ตรวจสอบแหล่งเงินและผู้มีอำนาจลงนามอนุมัติจัดซื้อจัดจ้าง/สั่งจ่ายเงินตามคำสั่ง พด.70/2564, พด.71/2564 และคู่มือการเงิน 45 หน้า โดยไม่สับสนระหว่างงบสำนักงานและงบกองทุน', '• Hook (0:00–0:45): กรณีศึกษาเมื่อเจ้าหน้าที่ชงเรื่องจัดจ้างวงเงิน 400,000 บาท โดยใช้เงินกองทุน ววน. แต่เสนอให้ ผอ.สำนัก F5 เป็นผู้อนุมัติ!
INSERT INTO learning_clips VALUES (14, 'CLIP-14', 'B4 (การบัญชีและรายงานการเงินคู่ขนาน)', 'บุคลากรระดับปฏิบัติการ', '30 : 70', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'แยกบัญชีสำนักงาน (ส่งใน 90 วัน) และบัญชีกองทุน ววน. (ส่งใน 180 วัน)', 'ปฏิบัติตามกรอบเวลาและขั้นตอนการจัดทำงบการเงินและรายงานประจำปีแยก 2 เส้นทางคู่ขนานตามที่ พ.ร.บ.สภานโยบายฯ กำหนด', '• 0:00–0:15: ทำไมการปิดบัญชีของ สกสว. จึงมีทั้งเส้นตาย 90 วัน และ 180 วัน?
INSERT INTO learning_clips VALUES (15, 'CLIP-15', 'B4 (การตรวจสอบภายในและประเมินผลอิสระ)', 'คณะกรรมการ (กสว. / อนก. / คกก.ตรวจสอบ)', '80 : 20', 'คลิปสั้น 30–60 วินาที (Micro-learning)', 'สายการรายงานตรงของผู้ตรวจสอบภายใน (IA) และการประเมินผลอิสระตามมาตรา 64', 'กำกับดูแลความเป็นอิสระของหน่วยตรวจสอบภายใน (P27) ตามมาตรา 62–63 และกลไกการประเมินผลการดำเนินงานของ กสว. และ สกสว. โดยคณะกรรมการประเมินอิสระตามมาตรา 64–65', '• 0:00–0:15: หน่วยตรวจสอบภายใน (IA) ขึ้นตรงต่อใครเพื่อหลักประกันความเป็นอิสระ?
INSERT INTO exam_items VALUES ('ITEM-001', 'A1 | คลิปที่ 1 (80:20)', 'คณะกรรมการ / ผู้บริหาร / ปฏิบัติการแผน (F1)', 'ในการประชุมเพื่อพิจารณาร่างแผนด้านวิทยาศาสตร์ วิจัยและนวัตกรรม (ววน.) ของประเทศ ฝ่ายเลขานุการได้เสนอร่างแผนที่ปรับปรุงใหม่โดยขอให้คณะกรรมการอำนวยการ สกสว. (อนก.สกสว.) มีมติให้ความเห็นชอบร่างแผนดังกล่าวเพื่อเสนอคณะรัฐมนตรีต่อไป ข้อใดวินิจฉัยขั้นตอนและฐานอำนาจได้ถูกต้องที่สุด?', 'A. ถูกต้อง เพราะ อนก.สกสว. มีอำนาจกำกับดูแลการดำเนินงานของสำนักงานตามมาตรา 47
INSERT INTO exam_items VALUES ('ITEM-002', 'A1 | คลิปที่ 2 (60:40)', 'ผู้บริหารระดับสูง / สำนัก F1', 'ในการตรวจทานความครบถ้วน (Completeness: C1) ของร่างแผนด้าน ววน. ก่อนเสนอ กสว. ตามมาตรา 44(3) ประกอบ พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 มาตรา 12 และมาตรา 13 ข้อใดคือเงื่อนไขบังคับที่หากขาดไปจะทำให้กระบวนการจัดทำแผนไม่สมบูรณ์ตามกฎหมาย?', 'A. ต้องมีองค์ประกอบครบทั้ง 6 ด้านตามมาตรา 12(1)–(6) และต้องจัดให้มีการรับฟังความคิดเห็นของผู้เกี่ยวข้องตามมาตรา 13
INSERT INTO exam_items VALUES ('ITEM-003', 'A2 | คลิปที่ 3 (30:70)', 'บุคลากรระดับปฏิบัติการ / สำนัก F1 & F2', 'ตาม SOP กระบวนการจัดทำกรอบวงเงินและการจัดสรรงบประมาณกองทุน ววน. (TSRI-F11-00-001) และคู่มือคำของบประมาณ FF (TSRI-F09-00-004) เมื่อปิดระบบรับคำของบประมาณ (เปิดรับประมาณ 45 วัน) แล้ว ขั้นตอนการกลั่นกรองคำของบประมาณเบื้องต้นและการเปิดให้หน่วยงานแก้ไขคำขอมีกรอบเวลามาตรฐานอย่างไร?', 'A. กลั่นกรองภายใน 7 วัน และให้หน่วยงานแก้ไขภายใน 7 วัน
INSERT INTO exam_items VALUES ('ITEM-004', 'A2 & B1 | คลิปที่ 4 (30:70)', 'บุคลากรระดับปฏิบัติการ / ทุกสำนัก (ทุน ORG)', 'สำนักหนึ่งของ สกสว. ประสงค์จะตั้งโครงการวิจัยภายใน (ทุน ORG) โดยใช้งบประมาณกองทุน ววน. ในหมวด Strategic Fund (SF) เพื่อพัฒนาชุดเทคโนโลยีต้นแบบแข่งกับมหาวิทยาลัยในระบบ ววน. เจ้าหน้าที่ผู้ตรวจคำขอควรให้ความเห็นตามกฎหมายและคู่มือบริหารโครงการ ORG (TSRI-F09-00-002) อย่างไร?', 'A. อนุมัติได้ทันทีหากวงเงินไม่เกิน 500,000 บาท ตามคำสั่ง พด.70/2564
INSERT INTO exam_items VALUES ('ITEM-005', 'A2 | คลิปที่ 5 (45:55)', 'ผู้บริหารระดับกลาง / สำนัก F2', 'ภายหลังการบังคับใช้ พ.ร.บ.การส่งเสริม ววน. (ฉบับที่ 2) พ.ศ. 2568 ซึ่งแก้ไขเพิ่มเติมมาตรา 18 ประกอบประกาศ กสว. เรื่องหลักเกณฑ์การจัดทำคำของบประมาณ (ฉบับที่ 3) พ.ศ. 2569 ข้อ 44, 44/1 และ 44/2 กลไกการจัดสรรงบประมาณและการผูกพันงบประมาณข้ามปี (Multi-year Promised Grant) เปลี่ยนแปลงไปอย่างไร?', 'A. ยกเลิกการจัดสรรงบประมาณแบบ Block Grant ทั้งหมดและกลับไปทำสัญญารายโครงการทุกบาท
INSERT INTO exam_items VALUES ('ITEM-006', 'A3 | คลิปที่ 6 (45:55)', 'ผู้บริหารระดับกลาง / สำนัก F3 & F5', 'เมื่อมีผู้บริจาคเงินหรือทรัพย์สินให้แก่ สกสว. โดยมีวัตถุประสงค์เพื่อใช้ในการส่งเสริมและสนับสนุนการวิจัยและนวัตกรรมของประเทศ (ไม่ได้บริจาคเพื่อใช้เป็นค่าใช้จ่ายบริหารสำนักงาน) เจ้าหน้าที่ต้องนำเงินดังกล่าวเข้าบัญชีใดและอยู่ภายใต้กรอบระเบียบใด?', 'A. นำเข้าบัญชีเงินสำนักงานตามมาตรา 45 และใช้จ่ายตามข้อบังคับของ อนก.สกสว.
INSERT INTO exam_items VALUES ('ITEM-007', 'A3 | คลิปที่ 7 (60:40)', 'ผู้บริหารระดับสูง / สำนัก F3', 'หน่วยบริหารและจัดการทุน (PMU) แห่งหนึ่งได้รับจัดสรรเงินอุดหนุนจากกองทุน ววน. เมื่อสิ้นสุดระยะเวลาการใช้จ่ายเงินอุดหนุนตามที่กำหนดแล้ว ปรากฏว่ายังมีเงินอุดหนุนเหลือจ่ายและมีดอกผลที่เกิดจากเงินฝากธนาคารของโครงการ ตามประกาศ กสว. เรื่องแนวทางการใช้จ่ายเงินอุดหนุนของ PMU (TSRI-F01-04-010 ถึง 012) PMU ต้องดำเนินการอย่างไร?', 'A. PMU สามารถนำเงินเหลือจ่ายและดอกเบี้ยไปสมทบเป็นงบบริหารสำนักงานของ PMU ในปีถัดไปได้ทันที
INSERT INTO exam_items VALUES ('ITEM-008', 'A4 | คลิปที่ 8 (45:55)', 'ผู้บริหารระดับกลาง / สำนัก F4', 'ตาม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2564 (TRIUP Act: TSRI-F03-01-001) และประกาศ กสว. ที่เกี่ยวข้อง เมื่อหน่วยรับงบประมาณสร้างผลงานวิจัยจากทุนของกองทุน ววน. สำเร็จ หลักการพื้นฐานเกี่ยวกับความเป็นเจ้าของผลงานวิจัยคือข้อใด?', 'A. ผลงานวิจัยตกเป็นของ สกสว. ในฐานะผู้ให้ทุนทุกกรณีโดยไม่มีข้อยกเว้น
INSERT INTO exam_items VALUES ('ITEM-009', 'A4 | คลิปที่ 9 (30:70)', 'บุคลากรระดับปฏิบัติการ / สำนัก F4', 'เมื่อผู้รับทุนได้รับอนุมัติให้เป็นเจ้าของผลงานวิจัยตาม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564 แล้ว หน้าที่ตามกฎหมายที่ผู้รับทุนต้องปฏิบัติอย่างต่อเนื่องต่อผู้ให้ทุน และเจ้าหน้าที่สำนัก F4 ต้องตรวจติดตามตามประกาศ กสว. ในหมวดที่ 3 คือข้อใด?', 'A. ไม่ต้องดำเนินการใดๆ อีกเนื่องจากความเป็นเจ้าของโอนขาดไปแล้ว
INSERT INTO exam_items VALUES ('ITEM-010', 'A5 | คลิปที่ 10 (45:55)', 'ผู้บริหารระดับกลาง / สำนัก F1 & หน่วยภารกิจ IU1', 'เจ้าหน้าที่ผู้ดูแลระบบฐานข้อมูลกลางด้าน ววน. (NRIIS) ล่วงรู้ข้อมูลอันเป็นความลับของโครงการวิจัยที่ยังไม่เปิดเผยต่อสาธารณะเนื่องจากการปฏิบัติหน้าที่ แล้วนำข้อมูลดังกล่าวไปเปิดเผยแก่บุคคลภายนอกโดยมิชอบด้วยกฎหมาย ตาม พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 มาตรา 24–25 และมาตรา 36 มีผลทางกฎหมายอย่างไร?', 'A. มีโทษทางวินัยตักเตือนเป็นหนังสือเท่านั้น ไม่มีโทษทางอาญา
INSERT INTO exam_items VALUES ('ITEM-011', 'B1 | คลิปที่ 11 (60:40)', 'ผู้บริหารระดับสูง / สำนัก F5', 'ตามประกาศคณะกรรมการอำนวยการ สกสว. เรื่องการแบ่งส่วนงานและขอบเขตหน้าที่ของส่วนงาน พ.ศ. 2569 (TSRI-F04-00-012 / DOC-0063) โครงสร้างส่วนงานของ สกสว. แบ่งออกเป็นกี่สำนัก กี่หน่วยภารกิจ และหน่วยตรวจสอบภายในมีสายการรายงานอย่างไร?', 'A. แบ่งเป็น 3 สำนัก 2 หน่วยภารกิจ โดยหน่วยตรวจสอบภายในสังกัดฝ่ายการเงิน
INSERT INTO exam_items VALUES ('ITEM-012', 'B2 | คลิปที่ 12 (30:70)', 'บุคลากรระดับปฏิบัติการ / สำนัก F5 (งานบุคคลและวินัย)', 'ตามข้อบังคับ อนก.สกสว. ว่าด้วยการบริหารงานบุคคลและวินัย (หมวดที่ 5) ประกอบคู่มือการดำเนินการทางวินัย พ.ศ. 2568 (TSRI-F09-00-001 จำนวน 111 หน้า) ข้อใดระบุกรอบเวลาการดำเนินการทางวินัยและสิทธิการอุทธรณ์ได้ถูกต้อง?', 'A. สืบสวนข้อเท็จจริงภายใน 30 วัน (ขยายได้ไม่เกิน 15 วัน), สอบสวนวินัยภายใน 60 วัน (ขยายได้ 2 ครั้ง ครั้งละไม่เกิน 30 วัน) และผู้ถูกลงโทษมีสิทธิยื่นอุทธรณ์ต่อ อนก.สกสว. ภายใน 30 วันนับแต่วันทราบคำสั่ง
INSERT INTO exam_items VALUES ('ITEM-013', 'B3 | คลิปที่ 13 (30:70)', 'บุคลากรระดับปฏิบัติการ / สำนัก F5 & F2 (การเงินและพัสดุ)', 'ในการจัดซื้อจัดจ้างและการสั่งจ่ายเงินวงเงิน 450,000 บาท หากรายการแรกเป็น ''การจัดซื้อครุภัณฑ์สำนักงานโดยใช้งบประมาณของสำนักงาน (มาตรา 45)'' และรายการที่สองเป็น ''การเบิกจ่ายเงินอุดหนุนภายใต้ภารกิจกองทุน ววน. (มาตรา 55)'' ตามคำสั่ง สกสว. ที่ พด. 70/2564 (TSRI-F08-00-001) และคู่มือการเงิน (TSRI-F09-00-003) ใครคือผู้รับมอบอำนาจอนุมัติในแต่ละรายการ?', 'A. ผู้อำนวยการสำนักบริหารและพัฒนาองค์กร (F5) มีอำนาจอนุมัติได้ทั้งสองรายการเพราะดูแลงานพัสดุทั้งหมด
INSERT INTO exam_items VALUES ('ITEM-014', 'B4 | คลิปที่ 14 (30:70)', 'บุคลากรระดับปฏิบัติการ / สำนัก F5 (ฝ่ายบัญชี)', 'ในการปิดบัญชีและจัดส่งรายงานการเงินประจำปีของ สกสว. ตาม พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 ข้อใดระบุเส้นตายและผู้รับรายงานการเงินของ ''งบสำนักงาน สกสว.'' เปรียบเทียบกับ ''งบกองทุน ววน.'' ได้ถูกต้องตามกฎหมาย?', 'A. ส่งทั้งสองงบให้กรมบัญชีกลางภายใน 60 วันนับแต่วันสิ้นปีงบประมาณ
INSERT INTO exam_items VALUES ('ITEM-015', 'B4 | คลิปที่ 15 (80:20)', 'คณะกรรมการ / ผู้บริหาร / หน่วยตรวจสอบภายใน (IA)', 'ตาม พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 มาตรา 62–65 กลไกการตรวจสอบและประเมินผลการดำเนินงานของกองทุน ววน. และ สกสว. กำหนดให้มีองค์กรใดทำหน้าที่ตรวจสอบภายในและองค์กรใดทำหน้าที่ประเมินผลการดำเนินงานอย่างเป็นอิสระ?', 'A. ให้ผู้บริหารสำนัก F5 เป็นผู้ประเมินตนเองทั้งหมดโดยไม่ต้องมีคณะกรรมการภายนอก
INSERT INTO legal_chains_24 VALUES ('PLUG-01', 'ชุดที่ 1: ระบบแผนและงบประมาณ ววน. (หมวด 1 & 2)', 'การจัดทำแผนด้าน ววน. 6 องค์ประกอบ และการแปลงสู่แผนปฏิบัติการหน่วยงาน', 'พ.ร.บ.สภานโยบายฯ: พ.ร.บ.สภานโยบายฯ ม.11(1) [สภานโยบายให้ความเห็นชอบแผน], ม.41(1) [กสว. เสนอแนะและให้ความเห็นชอบร่างแผน], ม.44(3) [สกสว. จัดทำแผนด้าน ววน. ของประเทศ] | พ.ร.บ.ส่งเสริม ววน.: พ.ร.บ.ส่งเสริมฯ ม.5(1), ม.6 [แผนเป็นแนวทางกำกับทิศทางและจัดสรรงบ], ม.12(1)–(6) และวรรคสอง [บังคับองค์ประกอบขั้นต่ำ 6 ด้าน + แผนงานย่อย + กรอบวงเงิน + ผลลัพธ์ที่คาดว่าจะได้รับ], ม.13–14 [สอวช. ตรวจแผนปฏิบัติการหน่วยงาน]', 'SOP การจัดสรรงบประมาณ กองทุน ววน. (TSRI-DOC-0101 ขั้นตอนเริ่มต้น: แผนด้าน ววน. ของประเทศ), ประกาศ กสว. หลักเกณฑ์คำของบประมาณฯ ข้อ 5–6 (OKRs แผน ววน.) และคู่มือ FF บทที่ 1', 'รัฐธรรมนูญ พ.ศ. 2560 (ยุทธศาสตร์ชาติ 20 ปี และแผนแม่บท), พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102) (ความสอดคล้องของคำของบประมาณกับแผนด้าน ววน.)', 'ตรวจความครบถ้วน 6 องค์ประกอบของแผนด้าน ววน. ตาม ม.12(1)–(6) และกรอบวงเงินรายแผนงานตาม ม.12 วรรคสอง ก่อนเข้าสู่รอบจัดทำคำของบประมาณปี T+2', 'Cluster A1 (สำนัก F1: สำนักยุทธศาสตร์แผน ติดตามและประเมินผล)');
INSERT INTO legal_chains_24 VALUES ('PLUG-02', 'ชุดที่ 1: ระบบแผนและงบประมาณ ววน. (หมวด 1 & 2)', 'การจัดประเภทหน่วยงาน 6 ประเภท ข้อห้ามทำวิจัยเอง (ยกเว้น ORG) และตัวชี้วัดผลสัมฤทธิ์', 'พ.ร.บ.สภานโยบายฯ: พ.ร.บ.สภานโยบายฯ ม.43 วรรคหนึ่ง [สกสว. มีวัตถุประสงค์ส่งเสริม สนับสนุน และขับเคลื่อนระบบการวิจัยและนวัตกรรม ''แต่จะต้องไม่ดำเนินการวิจัยเอง''], ม.41(8) และ ม.44(9) [ประเมินผลการดำเนินงานหน่วยงานในระบบ ววน.] | พ.ร.บ.ส่งเสริม ววน.: พ.ร.บ.ส่งเสริมฯ ม.7(1)–(6) [จัดประเภทหน่วยงาน 6 ประเภท โดยวรรคสามบังคับให้ดำเนินการตามตัวชี้วัดผลสัมฤทธิ์ที่ กสว. กำหนด] ↔ ม.9 วรรคหนึ่ง [ห้ามหน่วยงานตาม ม.7(1) และ (2) ทำวิจัยและสร้างนวัตกรรมเอง ''เว้นแต่เป็นการวิจัยหรือสร้างนวัตกรรมเพื่อพัฒนาการปฏิบัติงานตามหน้าที่และอำนาจของหน่วยงานนั้น''] และ ม.9 วรรคสอง [ห้ามขัดแย้งผลประโยชน์ส่วนบุคคลกับส่วนรวม]', 'ประกาศสภานโยบายฯ เรื่อง การจัดประเภทหน่วยงานในระบบ ววน. พ.ศ. 2564 และฉบับที่ 2–5 (TSRI-DOC-0032 ถึง 0036 จัด สกสว. เป็นประเภทที่ 1), ประกาศ กสว. หลักเกณฑ์คำของบฯ พ.ศ. 2566 ข้อ 5 และ คู่มือบริหารโครงการ ORG (TSRI-DOC-0097), คู่มือระเบียบการเงิน ข้อ 2.2 (คำสั่งมอบอำนาจ ORG)', 'พ.ร.บ.มาตรฐานทางจริยธรรม พ.ศ. 2562 (การป้องกันผลประโยชน์ทับซ้อนตาม ม.9 วรรคสอง), พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539', 'จุดออกข้อสอบ Scenario 30:70 ยอดนิยม: สกสว. ทำวิจัยเองไม่ได้ตาม ม.43 วรรคหนึ่ง แต่เมื่อปลั๊กอินกับ พ.ร.บ.ส่งเสริมฯ ม.9 วรรคหนึ่ง จึงให้ทุนหรือทำวิจัยเพื่อพัฒนาการปฏิบัติงานตามหน้าที่และอำนาจ (โครงการรหัส ORG) ได้', 'Cluster B1 และ A1–A5 (ทุกสำนัก F1–F5, หน่วยภารกิจ IU1–IU6 และ IA)');
INSERT INTO legal_chains_24 VALUES ('PLUG-03', 'ชุดที่ 1: ระบบแผนและงบประมาณ ววน. (หมวด 1 & 2)', 'ระบบงบประมาณสองช่องทาง (ม.17(1) vs ม.17(2)) และคำรับรองเงื่อนไขเงินอุดหนุนข้ามปี (ม.18 แก้ไขปี 2568)', 'พ.ร.บ.สภานโยบายฯ: พ.ร.บ.สภานโยบายฯ ม.11(4), ม.12(1) [แก้ไขปี 2568 กองทุนอุดมศึกษา] vs ม.12(2) [คกก.พิจารณางบประมาณด้าน ววน.], ม.41(2)–(7), ม.44(4)–(7), ม.54–57 [การจัดสรรเงินกองทุนส่งเสริม ววน.] | พ.ร.บ.ส่งเสริม ววน.: พ.ร.บ.ส่งเสริมฯ ม.16 [กสว. จัดทำประมาณการกรอบวงเงินรวมตามแผนแต่ละด้านระบุปีและวงเงิน], ม.17(1) [งบรายจ่ายประจำและตามภารกิจที่มิใช่โครงการ ววน. ยื่นสำนักงบประมาณโดยตรง], ม.17(2) [งบโครงการพัฒนา ววน. ยื่นต่อ กสว. โดยดูผลการดำเนินงานปีที่ผ่านมาประกอบ], ม.18 (แก้ไขโดย พ.ร.บ. ฉบับที่ 2 พ.ศ. 2568) [ทำ ''คำรับรองการปฏิบัติตามเงื่อนไขของการรับเงินอุดหนุน'' ให้ดำเนินโครงการเกิน 1 ปีงบประมาณได้]', 'SOP การจัดสรรงบประมาณ กองทุน ววน. ล่วงหน้า 2 ปี T+2 (TSRI-DOC-0101), ประกาศ กสว. หลักเกณฑ์การจัดทำคำของบประมาณฯ ฉบับที่ 1–3 (ถึงปี 2569: TSRI-DOC-0011), คู่มือจัดทำคำขอและการบริหารงบประมาณ FF (TSRI-DOC-0099 บทที่ 3 ข้อ 1.5 คำรับรองฯ และบทที่ 5 Multi-year Promised Grant)', 'พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102) (การตั้งงบประมาณรายจ่ายประจำปีและการผูกพันงบประมาณข้ามปี), พ.ร.บ.วินัยการเงินการคลังของรัฐ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0103)', 'จุดเปลี่ยนสำคัญปี 2568: ห้ามใช้คำว่า ''ทำข้อตกลง'' ตาม ม.18 เดิมในเอกสารรุ่นใหม่ ต้องใช้คำว่า ''คำรับรองการปฏิบัติตามเงื่อนไขของการรับเงินอุดหนุน'' ตาม พ.ร.บ. (ฉบับที่ 2) พ.ศ. 2568 มาตรา 3', 'Cluster A2 (สำนัก F2: สำนักกลยุทธ์งบประมาณและโครงสร้างพื้นฐานระบบ ววน. ร่วมกับ F1 และ F5)');
INSERT INTO legal_chains_24 VALUES ('PLUG-04', 'ชุดที่ 1: ระบบแผนและงบประมาณ ววน. (หมวด 1 & 2)', 'การจัดซื้อจัดจ้างเพื่อการวิจัยและพัฒนา และการบริหารพัสดุ 2 ฐานเงิน (สำนักงาน vs กองทุน)', 'พ.ร.บ.สภานโยบายฯ: พ.ร.บ.สภานโยบายฯ ม.45 [เงินและทรัพย์สินของสำนักงาน สกสว.], ม.47 โยง ม.25(2) [ข้อบังคับ อนก. ว่าด้วยการจัดหาและบริหารพัสดุของสำนักงาน], ม.50(1),(2) [อำนาจ ผอ.สกสว.], ม.55 และ ม.57 [เงินกองทุนส่งเสริม ววน.] | พ.ร.บ.ส่งเสริม ววน.: พ.ร.บ.ส่งเสริมฯ ม.19 วรรคหนึ่ง [การจัดซื้อจัดจ้างเพื่อการวิจัยและพัฒนา การสร้างนวัตกรรม และการพัฒนาวิทยาศาสตร์ เทคโนโลยี ให้เป็นไปตามหลักเกณฑ์ที่คณะกรรมการนโยบายการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐประกาศกำหนด] และวรรคสอง [สภานโยบายอาจขอให้ตรา พ.ร.ฎ. ยกเว้น พ.ร.บ.พัสดุฯ ทั้งหมดหรือบางส่วนได้]', 'ข้อบังคับ อนก.สกสว. ว่าด้วยการบริหารจัดการ การเงิน การบัญชีและทรัพย์สิน พ.ศ. 2563 ข้อ 16 (TSRI-DOC-0079), คำสั่ง สกสว. ที่ พด.70/2564 (มอบอำนาจจัดซื้อจัดจ้างแยกสายสำนักงานและสายกองทุน วงเงิน 500,000 บาท: TSRI-DOC-0094), คำสั่ง สกสว. ที่ พด.71/2564 (แต่งตั้งเจ้าหน้าที่พัสดุ วงเงิน 10,000 บาท: TSRI-DOC-0095), คู่มือ FF บทที่ 2 และบทที่ 3 ข้อ 8.3 (ครุภัณฑ์วิจัย)', 'พ.ร.บ.การจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 (หมวด 12: TSRI-DOC-0104) (มาตรา 6, 7 และประกาศคณะกรรมการนโยบายฯ เรื่องหลักเกณฑ์การจัดซื้อจัดจ้างเพื่อการวิจัยและพัฒนา) และระเบียบกระทรวงการคลังฯ พ.ศ. 2560 ข้อ 7', 'แยก 2 มิติชัดเจน: (1) พัสดุเพื่อการวิจัยของหน่วยรับงบประมาณ ใช้เกณฑ์เฉพาะตาม ม.19 พ.ร.บ.ส่งเสริมฯ (2) พัสดุภายในของ สกสว. และกองทุน ใช้ข้อบังคับ อนก. ข้อ 16 ประกอบ พ.ร.บ.พัสดุฯ 2560 และคำสั่ง พด.70/2564', 'Cluster B3 และ A2 (สำนัก F5 งานพัสดุ ร่วมกับ F2)');
INSERT INTO legal_chains_24 VALUES ('PLUG-05', 'ชุดที่ 1: ระบบแผนและงบประมาณ ววน. (หมวด 1 & 2)', 'การพัฒนาบุคลากรวิจัยและนวัตกรรม สิทธิประโยชน์ 10 มาตรการ และรางวัลผลงานวิจัย', 'พ.ร.บ.สภานโยบายฯ: พ.ร.บ.สภานโยบายฯ ม.11(2),(3), ม.41(1), ม.44(1),(3),(12), ม.52 [บทบาทของ วช. ในการให้ทุนและรางวัล], ม.54(3) [วัตถุประสงค์กองทุนในการพัฒนาบุคลากร] | พ.ร.บ.ส่งเสริม ววน.: พ.ร.บ.ส่งเสริมฯ ม.5(7), ม.10 [รัฐจัดสรรงบส่วนหนึ่งของโครงการเทคโนโลยีสมัยใหม่จากต่างประเทศเพื่อสร้างความสามารถถ่ายทอดเทคโนโลยีและผลิตวัสดุอุปกรณ์ในประเทศ], ม.20(1)–(10) [กระทรวง กสว. และ สอวช. โดยความเห็นชอบของสภานโยบายและ ครม. ส่งเสริมบุคลากร 10 ด้าน เช่น ไปทำวิจัยในหน่วยงานอื่น/ต่างประเทศโดยถือเป็นการปฏิบัติหน้าที่ต้นสังกัด ดึงดูดผู้เชี่ยวชาญต่างชาติ], ม.21 [วช. ให้รางวัลและประกาศเกียรติคุณตามหลักเกณฑ์และวิธีการที่ กสว. กำหนด]', 'ระเบียบ กสว. ว่าด้วยการเร่งรัดและติดตามให้มีการชดใช้ทุนคืน พ.ศ. 2564 (TSRI-DOC-0006), ประกาศ กสว. เรื่อง การส่งเสริมและสนับสนุนความร่วมมือด้าน ววน. ระหว่างหน่วยงานภายในประเทศและต่างประเทศ พ.ศ. 2566 (TSRI-DOC-0016), แผนด้าน ววน. ยุทธศาสตร์การพัฒนากำลังคน', 'กฎหมายว่าด้วยระเบียบข้าราชการพลเรือนและข้าราชการพลเรือนในสถาบันอุดมศึกษา (การนับเวลาปฏิบัติงานและการเลื่อนตำแหน่งตาม ม.20(3)–(5)), กฎหมายว่าด้วยคนเข้าเมือง (การตรวจลงตราพิเศษตาม ม.20(7))', 'ระวังการสับสนบทบาทตาม ม.21: ผู้มีอำนาจให้รางวัลผลงานวิจัยและประกาศเกียรติคุณคือ ''วช.'' แต่ต้องเป็นไปตามหลักเกณฑ์และวิธีการที่ ''กสว.'' กำหนด', 'Cluster A1, A3 และ A4 (สำนัก F1, F3 และ F4 ร่วมกับ วช. และ สอวช.)');
INSERT INTO legal_chains_24 VALUES ('PLUG-06', 'ชุดที่ 1: ระบบแผนและงบประมาณ ววน. (หมวด 1 & 2)', 'ระบบฐานข้อมูลสารสนเทศกลาง (วช. ↔ สกสว. ↔ สอวช.) การรักษาความลับ และสภาพบังคับ/โทษอาญา', 'พ.ร.บ.สภานโยบายฯ: พ.ร.บ.สภานโยบายฯ ม.11(7) [สภานโยบายกำหนดแนวทางจัดทำฐานข้อมูล], ม.41(13), ม.44(2) [สกสว. จัดทำฐานข้อมูลและดัชนีด้าน ววน. ของประเทศเพื่อใช้ในการปฏิบัติงาน], ม.44(12) [จัดทำรายงานประจำปีเกี่ยวกับสถานภาพการวิจัย] | พ.ร.บ.ส่งเสริม ววน.: พ.ร.บ.ส่งเสริมฯ ม.22–25 [หน่วยงานในระบบ ววน. และสถาบันอุดมศึกษาแจ้ง/เชื่อมโยงข้อมูลวิจัย 6 รายการและรายงานฉบับสมบูรณ์ต่อ วช. เพื่อจัดทำฐานข้อมูลกลาง และเชื่อมโยงกับระบบของ สอวช. และ สกสว. โดยห้ามอ้างอิงข้อมูลขัดแย้งกับฐานข้อมูลตาม ม.24], ม.26 [สกสว. วิเคราะห์สังเคราะห์ข้อมูลการพัฒนาวิทยาศาสตร์ เทคโนโลยีตามแผน ววน. เสนอความเห็นต่อ กสว. และสภานโยบาย], ม.27 [การเปิดเผยข้อมูลไม่เป็นเหตุฟ้องร้องดำเนินคดี], ม.35 [สภาพบังคับที่เป็นผลร้ายต่อหน่วยงานที่ไม่ส่งข้อมูลตามที่สภานโยบายประกาศกำหนดโดยข้อเสนอของ กสว.], ม.36 [โทษอาญาจำคุกไม่เกิน 5 ปี หรือปรับไม่เกิน 100,000 บาท สำหรับผู้เปิดเผยความลับตาม ม.22 วรรคสี่/ห้า]', 'ระเบียบสภานโยบายฯ ว่าด้วยการแจ้ง การนำส่ง การเชื่อมโยงข้อมูลฯ พ.ศ. 2565 (TSRI-DOC-0028: ข้อมูล 15 รายการ), ประกาศสภานโยบายฯ เรื่อง การจัดทำฐานข้อมูล อววน. พ.ศ. 2565 (TSRI-DOC-0031), ระบบข้อมูลสารสนเทศวิจัยและนวัตกรรมแห่งชาติ (NRIIS) และระบบ STARS', 'พ.ร.บ.ข้อมูลข่าวสารของราชการ พ.ศ. 2540, พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 (PDPA), ประมวลกฎหมายอาญา (ความผิดเกี่ยวกับความลับในราชการ เชื่อม ม.36)', 'แยกบทบาทตาม ม.24 และ ม.26: ''วช.'' เป็นผู้ดูแลระบบข้อมูลสารสนเทศกลางและรวบรวมข้อมูลผลงานวิจัย ส่วน ''สกสว.'' มีสิทธิเข้าถึงและมีหน้าที่วิเคราะห์สังเคราะห์ข้อมูลการพัฒนาวิทยาศาสตร์และเทคโนโลยีตามแผน ววน. เสนอต่อ กสว. และสภานโยบาย และเป็นผู้เสนอสภาพบังคับที่เป็นผลร้ายตาม ม.35 วรรคสอง', 'Cluster A5 และ A1 (สำนัก F1 ร่วมกับ F2 และหน่วยภารกิจ IU1–IU6)');
INSERT INTO legal_chains_24 VALUES ('PLUG-07', 'ชุดที่ 1: ระบบแผนและงบประมาณ ววน. (หมวด 1 & 2)', 'การนำผลงานวิจัยไปใช้ประโยชน์ การให้ทุนเอกชน มาตรการ TBIR และการร่วมลงทุนรัฐ-เอกชน', 'พ.ร.บ.สภานโยบายฯ: พ.ร.บ.สภานโยบายฯ ม.11(9), ม.41(11)–(12), ม.44(8),(10),(11),(13) [สกสว. ส่งเสริมและสนับสนุนการนำผลงานวิจัยและนวัตกรรมไปใช้ประโยชน์ทั้งเชิงเศรษฐกิจ สังคม และสาธารณประโยชน์], ม.54(1)–(6) [วัตถุประสงค์กองทุน] | พ.ร.บ.ส่งเสริม ววน.: พ.ร.บ.ส่งเสริมฯ ม.11(2)–(6), ม.28 [กระทรวงและ สกสว. ส่งเสริมการนำผลงานวิจัยไปใช้ประโยชน์และสนับสนุนทุนแก่บุคคล/ชุมชน/เอกชนในโครงการ 6 ลักษณะตามระเบียบสภานโยบาย], ม.29 [สภานโยบายเสนอ ครม. ให้สิทธิประโยชน์ 7 ด้าน เช่น จัดซื้อจัดจ้างภาครัฐ ยกเว้นภาษี ความเป็นเจ้าของ IP], ม.30 [ต่อยอดเทคโนโลยีในโครงการลงทุนขนาดใหญ่ของรัฐ], ม.31 [ร่วมลงทุนรัฐ-เอกชนในโครงการนำผลงานวิจัยไปใช้ประโยชน์ โดยยกเว้นมิให้นำกฎหมายว่าด้วยการร่วมลงทุนระหว่างรัฐและเอกชนมาใช้บังคับ]', 'ระเบียบสภานโยบายฯ ว่าด้วยหลักเกณฑ์และวิธีการสนับสนุนทุนวิจัยและนวัตกรรมแก่ภาคเอกชนและภาคประชาสังคมฯ พ.ศ. 2563 (TSRI-DOC-0027), ระเบียบสภานโยบายฯ ว่าด้วยการร่วมลงทุนระหว่างรัฐและเอกชนฯ พ.ศ. 2566 (TSRI-DOC-0029), ประกาศ กสว. มาตรการส่งเสริมงานวิจัยและนวัตกรรมในธุรกิจ (TBIR) พ.ศ. 2564 (TSRI-DOC-0017)', 'พ.ร.บ.ส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2564 (TRIUP Act: TSRI-DOC-0037), พ.ร.บ.การร่วมลงทุนระหว่างรัฐและเอกชน พ.ศ. 2562 (ได้รับยกเว้นตาม ม.31 วรรคสอง), ประมวลรัษฎากร และ พ.ร.บ.ส่งเสริมการลงทุน พ.ศ. 2520 (เชื่อม ม.29(2)–(3))', 'จุดเชื่อมโยงสำคัญ: พ.ร.บ.ส่งเสริมฯ ม.29(4) เป็นรากฐานก่อนต่อยอดสู่ พ.ร.บ.ส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2564 (TRIUP Act) และ ม.31 วรรคสองปลดล็อกให้ไม่ต้องใช้ พ.ร.บ.ร่วมลงทุนฯ (PPP) แต่ใช้ระเบียบสภานโยบายฯ พ.ศ. 2566 แทน', 'Cluster A4 และ A3 (สำนัก F4: สำนักกลยุทธ์พัฒนาความร่วมมือนานาชาติและใช้ประโยชน์งานวิจัยระบบ ววน. ร่วมกับสำนัก F3)');
INSERT INTO legal_chains_24 VALUES ('PLUG-08', 'ชุดที่ 1: ระบบแผนและงบประมาณ ววน. (หมวด 1 & 2)', 'มาตรฐานการวิจัย จริยธรรมการวิจัย และการบริหารโครงการต่อเนื่อง/การถ่ายโอนฐานข้อมูล', 'พ.ร.บ.สภานโยบายฯ: พ.ร.บ.สภานโยบายฯ ม.41(10) [กสว. กำหนดมาตรฐานและจริยธรรมการวิจัยและผลักดันการนำไปใช้], ม.44(8) [สกสว. จัดทำมาตรฐานและจริยธรรมการวิจัยเสนอ กสว.], ม.71 [โอนภารกิจและงบประมาณ สกว.] | พ.ร.บ.ส่งเสริม ววน.: พ.ร.บ.ส่งเสริมฯ ม.8 [กำกับดูแลเท่าที่จำเป็นโดยไม่กระทบเสรีภาพทางวิชาการ], ม.32 [กสว. โดยความเห็นชอบของสภานโยบายกำหนดมาตรฐานการวิจัยด้านต่างๆ ประกาศราชกิจจานุเบกษา], ม.33(1) [กสว. โดยความเห็นชอบของสภานโยบายกำหนดจริยธรรมการวิจัยทั่วไป ประกาศราชกิจจานุเบกษา], ม.33(2) [หลักเกณฑ์การวิจัยที่มีปัญหากับศาสนา วัฒนธรรม จารีตประเพณี หรือศีลธรรมอันดี ให้ตราเป็นพระราชกฤษฎีกา], ม.37 [โครงการวิจัยที่ดำเนินการอยู่ก่อนวันใช้บังคับ หากมีปัญหาให้เป็นไปตามที่ กสว. กำหนด], ม.38 [ถ่ายโอนข้อมูลให้ วช.], ม.39 [เร่งรัดออกกฎรองภายใน 2 ปี]', 'ระเบียบ กสว. ว่าด้วยจริยธรรมการวิจัยทั่วไป พ.ศ. 2565 (TSRI-DOC-0030), คู่มือระเบียบการเงิน พ.ศ. 2568 ข้อ 2.3 (คำสั่งมอบอำนาจโครงการวิจัย Ongoing ของ สกว. ตามบทเฉพาะกาล: TSRI-DOC-0098)', 'รัฐธรรมนูญ พ.ศ. 2560 มาตรา 26, 32 และเสรีภาพทางวิชาการ, พระราชกฤษฎีกาตามมาตรา 33(2), กฎหมายว่าด้วยการวิจัยในมนุษย์และสัตว์ทดลอง', 'ข้อแตกต่างทางรูปแบบกฎหมายใน ม.33 ที่ออกข้อสอบบ่อย: (1) ''จริยธรรมการวิจัยทั่วไป'' ตาม ม.33(1) ออกเป็น ''ระเบียบ กสว. โดยความเห็นชอบของสภานโยบาย'' แต่ (2) ''หลักเกณฑ์การวิจัยที่มีปัญหากับศาสนา/ศีลธรรมอันดี'' ตาม ม.33(2) ต้องตราเป็น ''พระราชกฤษฎีกา''', 'Cluster A3, A5 และ B1 (สำนัก F3, F1 และ F5)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-3.1', 'ชุดที่ 2: การใช้ประโยชน์ผลงานวิจัย TRIUP (หมวด 3)', 'ห่วงโซ่ที่ 1: ขอบเขตการใช้บังคับและการคัดกรองสัญญาให้ทุน vs สัญญาจ้างพัสดุ (Scope & Exemption Gate)', 'พ.ร.บ.สภานโยบายฯ ม.11, 44 & พ.ร.บ.ส่งเสริม ววน. ม.28–31 เชื่อม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ ม.3 และ ม.4(1)–(5)', 'ประกาศสภานโยบายฯ เรื่อง หลักเกณฑ์การให้ทุนหน่วยงานรัฐ (TSRI-DOC-0047) + ระเบียบ กสว. ม.4(4) (TSRI-DOC-0041) + แนวทางคนต่างด้าว ม.4(2) (TSRI-DOC-0051)', 'พ.ร.บ.การจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 (หมวด 12: TSRI-DOC-0104) และ พ.ร.บ.การประกอบธุรกิจของคนต่างด้าว พ.ศ. 2542', 'แยก ''สัญญาให้ทุนวิจัย'' (ผู้รับทุนเป็นเจ้าของผลงานได้) ออกจาก ''สัญญาจ้างที่ปรึกษา/จัดซื้อจัดจ้างตาม พ.ร.บ.พัสดุฯ'' และกำหนดขั้นตอนขอความเห็นชอบ กสว. ล่วงหน้าก่อนทำสัญญาสำหรับงานวิจัยเพื่อมวลมนุษยชาติตาม ม.4(4)', 'A3, A4, B3 (F3, F4, F5)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-3.2', 'ชุดที่ 2: การใช้ประโยชน์ผลงานวิจัย TRIUP (หมวด 3)', 'ห่วงโซ่ที่ 2: มาตรฐานข้อสัญญาให้ทุนและข้อห้ามผู้ให้ทุนเรียกส่วนแบ่งรายได้ (Mandatory Grant Contract Clauses)', 'พ.ร.บ.สภานโยบายฯ ม.11, 44 & พ.ร.บ.ส่งเสริม ววน. ม.28–31 เชื่อม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ ม.6 วรรคหนึ่ง–วรรคสี่ และ ม.10 + พ.ร.บ.การส่งเสริม ววน. ม.19 วรรคสอง', 'ระเบียบ กสว. ว่าด้วยการกำหนดข้อสัญญาที่เป็นสาระสำคัญของสัญญาให้ทุน พ.ศ. 2565 (TSRI-DOC-0042)', 'ป.พ.พ. มาตรา 150, 173 (โมฆะกรรมบางส่วน) และ พ.ร.บ.ว่าด้วยข้อสัญญาที่ไม่เป็นธรรม พ.ศ. 2540', 'บังคับบรรจุข้อสัญญามาตรฐานในสัญญาให้ทุนและสัญญาจ้างช่วงทุกฉบับ ข้อกำหนดที่ขัดแย้งหรือให้ผู้รับจ้างช่วงเป็นเจ้าของตกเป็นโมฆะ และห้ามผู้ให้ทุนกำหนดข้อสัญญาเรียกแบ่งปันรายได้จากผู้รับทุนหรือนักวิจัย (ข้อ 4)', 'A3, A4, B1 (F3, F4, F5)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-3.3', 'ชุดที่ 2: การใช้ประโยชน์ผลงานวิจัย TRIUP (หมวด 3)', 'ห่วงโซ่ที่ 3: การเปิดเผยผลงาน การได้ความเป็นเจ้าของ และการโอนให้ TLO/Holding (Disclosure, Vesting & Transfer)', 'พ.ร.บ.สภานโยบายฯ ม.11, 44 & พ.ร.บ.ส่งเสริม ววน. ม.28–31 เชื่อม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ ม.7, ม.8, ม.9, ม.11 และ ม.15', 'ระเบียบ กสว. ว่าด้วยการเปิดเผย ความเป็นเจ้าของ และการโอนผลงานฯ พ.ศ. 2565 (TSRI-DOC-0043) + ประกาศสภานโยบายฯ เรื่อง สิทธิหน้าที่คนต่างด้าวฯ (TSRI-DOC-0048)', 'พ.ร.บ.สิทธิบัตร พ.ศ. 2522, พ.ร.บ.ลิขสิทธิ์ พ.ศ. 2537 และกฎหมายจัดตั้งนิติบุคคล (TLO / University Holding Company)', 'เปิดเผยผลงานใน 30 วัน (ไม่เกิน 90 วันหลังปิดโครงการ) -> ยื่นขอเป็นเจ้าของพร้อมแผนใช้ประโยชน์ใน 90 วัน -> ผู้ให้ทุนออกหนังสือรับรองใน 30 วัน -> โอนให้นิติบุคคลบริหารจัดการผลงาน (TLO) ได้โดยไม่ต้องขอความยินยอมผู้ให้ทุน', 'A4, A3 (F4, F3)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-3.4', 'ชุดที่ 2: การใช้ประโยชน์ผลงานวิจัย TRIUP (หมวด 3)', 'ห่วงโซ่ที่ 4: การจัดสรรรายได้ให้นักวิจัยและการกันเงินพัฒนาวิจัยของมหาวิทยาลัย (Benefit & Revenue Sharing)', 'พ.ร.บ.สภานโยบายฯ ม.11, 44 & พ.ร.บ.ส่งเสริม ววน. ม.28–31 เชื่อม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ ม.14 วรรคหนึ่ง–วรรคห้า', 'ระเบียบ กสว. ว่าด้วยหลักเกณฑ์และเงื่อนไขในการจัดสรรรายได้ให้แก่นักวิจัยฯ พ.ศ. 2565 (TSRI-DOC-0045)', 'พ.ร.บ.การอุดมศึกษา พ.ศ. 2562 และข้อบังคับการเงินของสถาบันอุดมศึกษา/หน่วยงานของรัฐ', 'บังคับให้หน่วยงานรับทุนออกระเบียบจัดสรรรายได้สุทธิให้แก่นักวิจัย (รวมถึงนักวิจัยร่วมที่ไม่ได้เป็นเจ้าของ) และกันส่วนหนึ่งเข้ากองทุนวิจัยของสถาบันอุดมศึกษาภายใน 180 วัน พร้อมส่งระเบียบให้ สกสว. ทราบภายใน 60 วัน', 'A4, A3 (F4, F3)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-3.5', 'ชุดที่ 2: การใช้ประโยชน์ผลงานวิจัย TRIUP (หมวด 3)', 'ห่วงโซ่ที่ 5: การรายงานผล 2 ปี การแจ้ง Exclusive License ต่างประเทศ และการดึงสิทธิคืน (2-Year Utilization & Clawback)', 'พ.ร.บ.สภานโยบายฯ ม.11, 44 & พ.ร.บ.ส่งเสริม ววน. ม.28–31 เชื่อม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ ม.12, ม.13 และ ม.17', 'ระเบียบ กสว. ว่าด้วยการบริหารจัดการ การใช้ประโยชน์ และการรายงาน พ.ศ. 2565 (TSRI-DOC-0044) + ประกาศสภานโยบายฯ เรื่อง การรายงานผลงานที่ผู้ให้ทุนเป็นเจ้าของ (TSRI-DOC-0049)', 'พ.ร.บ.ข้อมูลข่าวสารของราชการ พ.ศ. 2540 และกฎหมายทะเบียนทรัพย์สินทางปัญญา (การแก้ไขชื่อผู้ทรงสิทธิทางทะเบียน)', 'เจ้าของต้องใช้ประโยชน์ภายใน 2 ปีและรายงานผลอย่างน้อยปีละ 1 ครั้ง (ไม่น้อยกว่า 5 ปี); แจ้งล่วงหน้า 30 วันก่อนให้ Exclusive License แก่ผู้ไม่มีฐานธุรกิจในไทย; หากไม่ใช้ประโยชน์และไม่ขยายเวลา สิทธิตกเป็นของผู้ให้ทุนทันทีและ กสว. สั่งโอน/เปิดใช้สิทธิต่อได้ตาม ม.17', 'A4, A5 (F4, F1)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-3.6', 'ชุดที่ 2: การใช้ประโยชน์ผลงานวิจัย TRIUP (หมวด 3)', 'ห่วงโซ่ที่ 6: กลไกส่งเสริมเทคโนโลยีที่เหมาะสมแก่ชุมชนและค่าตอบแทนนักวิจัย (Appropriate Technology Ecosystem)', 'พ.ร.บ.สภานโยบายฯ ม.11, 44 & พ.ร.บ.ส่งเสริม ววน. ม.28–31 เชื่อม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ ม.18 และ ม.19 + พ.ร.บ.สภานโยบายฯ ม.49', 'ระเบียบสภานโยบายฯ เทคโนโลยีที่เหมาะสม (TSRI-DOC-0038) + ระเบียบ กสว. ค่าตอบแทนฯ (TSRI-DOC-0046) + ประกาศ กสว. ค่าตอบแทนฯ (TSRI-DOC-0050)', 'พ.ร.บ.ส่งเสริมวิสาหกิจชุมชน พ.ศ. 2548 และ พ.ร.บ.ส่งเสริมวิสาหกิจเพื่อสังคม พ.ศ. 2562', 'ตั้ง ''สกสว.'' เป็นหน่วยงานเฉพาะด้านนโยบาย/จัดสรรงบประมาณ และตั้ง ''บพท., สวก., สนช., วช.'' เป็นหน่วยงานเฉพาะด้านการให้ทุนและจ่าย ''ค่าตอบแทนการใช้ประโยชน์'' แก่นักวิจัยที่นำเทคโนโลยีที่เหมาะสมไปยกระดับเศรษฐกิจฐานราก (อนุมัติใน 60 วัน)', 'A4, A2, A3 (F4, F2, F3)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-3.7', 'ชุดที่ 2: การใช้ประโยชน์ผลงานวิจัย TRIUP (หมวด 3)', 'ห่วงโซ่ที่ 7: การขออนุญาตใช้ประโยชน์โดยบุคคลภายนอก (March-in) การอุทธรณ์ 3 ระดับ และเขตอำนาจศาล IP', 'พ.ร.บ.สภานโยบายฯ ม.11, 44 & พ.ร.บ.ส่งเสริม ววน. ม.28–31 เชื่อม พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ ม.13 วรรคสาม–สี่, ม.20, ม.21 และ ม.22', 'ระเบียบสภานโยบายฯ ว่าด้วยการขอใช้ประโยชน์โดยบุคคลภายนอก (TSRI-DOC-0039) + ระเบียบว่าด้วยการอุทธรณ์ฯ พ.ศ. 2565 (TSRI-DOC-0040)', 'พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539 และ พ.ร.บ.จัดตั้งศาลทรัพย์สินทางปัญญาและการค้าระหว่างประเทศฯ พ.ศ. 2539', 'สกสว. ทำหน้าที่รับคำขอ สอบสวนข้อเท็จจริงภายใน 60 วัน และสรุปสำนวนเสนอผู้มีอำนาจวินิจฉัย 3 ระดับ (ผอ.สกสว. / กสว. ใน 30 วัน / สภานโยบาย ใน 60 วัน) และหากมีข้อพิพาททางคดีให้อยู่ในเขตอำนาจศาลทรัพย์สินทางปัญญาและการค้าระหว่างประเทศ (ม.22)', 'B1, A4 (F5, F4)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-3.8', 'ชุดที่ 2: การใช้ประโยชน์ผลงานวิจัย TRIUP (หมวด 3)', 'ห่วงโซ่ที่ 8: การประเมินผลสัมฤทธิ์ของกฎหมายตามรัฐธรรมนูญ มาตรา 77 และการปิดช่องว่างทางปฏิบัติ (Sec. 77 Post-Legislative Loop)', 'พ.ร.บ.สภานโยบายฯ ม.11, 44 & พ.ร.บ.ส่งเสริม ววน. ม.28–31 เชื่อม รัฐธรรมนูญ ม.77 + พ.ร.บ.สภานโยบายฯ ม.45(8) + พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ ทั้งฉบับ (ม.1–23)', 'รายงานการประเมินผลสัมฤทธิ์ พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ รวมภาคผนวก (TSRI-DOC-0100 หมวด 10) + กฎหมายรองทั้ง 14 ฉบับในหมวด 3', 'พ.ร.บ.หลักเกณฑ์การจัดทำร่างกฎหมายและการประเมินผลสัมฤทธิ์ของกฎหมาย พ.ศ. 2562', 'ใช้ผลการประเมินผลสัมฤทธิ์ พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ (หมวด 10) มาปรับปรุงคู่มือปฏิบัติงาน ระบบรายงานดิจิทัล (TRIUP Portal / NRIIS) มาตรฐานสัญญาให้ทุน และการพัฒนาศักยภาพ TLO ของมหาวิทยาลัยทั่วประเทศ', 'A5, A4, B1 (F1, F4, F5)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-4.1', 'ชุดที่ 3: บริหารภายใน คู่มือ ม.77 & หมวด 12 (หมวด 4–12)', 'ห่วงโซ่ที่ 1: สถาปัตยกรรมโครงสร้างองค์กร พ.ศ. 2569 และการแบ่งสายกำกับดูแล (5 สำนัก F1–F5, 6 IU, 1 IA)', 'พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 มาตรา 43, 46, 47, 48, 49, 50 และมาตรา 63 (คณะกรรมการตรวจสอบ)', 'ข้อบังคับ อนก. บริหารงานบุคคล (ฉ.2) พ.ศ. 2566 หมวด 2/1 (DOC-0067) + ประกาศส่วนงาน พ.ศ. 2569 (DOC-0063) + แผนผังโครงสร้าง (DOC-0064) + คำสั่งมอบหมายกำกับส่วนงาน บค.6/2568 (DOC-0054)', 'เชื่อมโยง พ.ร.ฎ.ว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546 และเกณฑ์ PMQA ในประกาศ OG 2568 (DOC-0092)', 'คณะกรรมการอำนวยการ (อนก.สกสว.) อนุมัติโครงสร้างการแบ่งส่วนงานและกรอบอัตรากำลัง (ข้อ 14) -> ผู้อำนวยการ สกสว. ออกประกาศแบ่งส่วนงานเป็น 5 สำนักหลัก (F1–F5), 6 หน่วยภารกิจเชิงลึก (IU1–IU6) และหน่วยตรวจสอบภายใน (IA ที่ขึ้นตรงต่อคณะกรรมการตรวจสอบตาม ม.63) พร้อมออกคำสั่งมอบหมายผู้บริหารกำกับดูแลแต่ละสำนัก', 'Cluster B1 (สำนักบริหารและพัฒนาองค์กร F5 - 17 ภารกิจ)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-4.2', 'ชุดที่ 3: บริหารภายใน คู่มือ ม.77 & หมวด 12 (หมวด 4–12)', 'ห่วงโซ่ที่ 2: ระบบตำแหน่ง 7 กลุ่ม บัญชีเงินเดือน 8 ระดับ (Level 1–8) และการปรับเข้าสู่ตำแหน่ง พ.ศ. 2569', 'พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 มาตรา 47 ประกอบมาตรา 25(4) และมาตรา 50', 'ข้อบังคับ อนก. บริหารงานบุคคล พ.ศ. 2563 และ (ฉ.2) พ.ศ. 2566 (DOC-0066, 0067) + ระเบียบกำหนดตำแหน่งและบัญชีเงินเดือน พ.ศ. 2569 (DOC-0061) + ประกาศหลักเกณฑ์การปรับเข้าสู่ตำแหน่งฯ พ.ศ. 2569 (DOC-0062) + คำสั่งแต่งตั้ง บค.7, 8, 9, 10, 13, 14/2569 (DOC-0055 ถึง 0060)', 'หลักกฎหมายแรงงานและหลักการคุ้มครองสิทธิขั้นต่ำของพนักงานองค์การมหาชน (ห้ามลดเงินเดือน/ค่าจ้างเดิม)', 'ทบทวนบัญชีเงินเดือนทุก 5 ปี (ข้อ 11) -> กำหนดโครงสร้างตำแหน่ง 7 กลุ่ม (บริหาร, เชี่ยวชาญ, จัดการ, อาวุโส, วิชาการ/วิชาชีพ, สนับสนุน, ทั่วไป) และบัญชีเงินเดือน Level 1A (16,000 บาท) ถึง Level 8A (225,000 บาท) -> เทียบโอนจาก Sub-Grade เดิมสู่ Sub-Level ใหม่โดยห้ามต่ำกว่าเงินเดือนเดิม และออกคำสั่งบรรจุแต่งตั้งรายสำนัก', 'Cluster B2 (F5 ฝ่ายทรัพยากรบุคคล - 13 ภารกิจ)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-4.3', 'ชุดที่ 3: บริหารภายใน คู่มือ ม.77 & หมวด 12 (หมวด 4–12)', 'ห่วงโซ่ที่ 3: การสรรหา การยืมตัวเจ้าหน้าที่ของรัฐ สวัสดิการ กองทุนสำรองเลี้ยงชีพ และการทำงานยืดหยุ่น (WFH/WFA)', 'พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 มาตรา 47 ประกอบมาตรา 25(4)(ช) และมาตรา 50', 'ประกาศการสรรหาฯ (DOC-0069) + ประกาศการยืมตัว พ.ศ. 2567 (DOC-0070) + ประกาศการลาและ (ฉ.2) พ.ศ. 2569 (DOC-0071, 0072) + วันเวลาทำงาน (DOC-0073) + WFH/WFA 80:20 (DOC-0074) + ระเบียบสวัสดิการ (DOC-0075) + กองทุนสำรองเลี้ยงชีพ (DOC-0076)', 'พ.ร.บ.กองทุนสำรองเลี้ยงชีพ พ.ศ. 2530 และมติคณะรัฐมนตรีเกี่ยวกับการยืมตัวข้าราชการ/เจ้าหน้าที่ของรัฐ', 'ทดลองงาน 90–180 วัน -> เวลาทำงานเหลื่อมเวลา (เข้า 07.00–09.30 น. เลิก 15.00–17.30 น. วันละ 7 ชม.) -> สัดส่วนเข้าสำนักงาน 80% : WFH/WFA ไม่เกิน 20% -> สิทธิลาคลอดใหม่ 120 วัน + เลี้ยงดูบุตรป่วย 15 วัน -> กองทุนสำรองเลี้ยงชีพสะสม 2–15% สมทบ 8–15% (รับสมทบ 100% เมื่ออายุงานครบ 5 ปี) -> การยืมตัวเจ้าหน้าที่ของรัฐทำได้คราวละ 1 ปี', 'Cluster B2 (F5 ฝ่ายทรัพยากรบุคคล)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-4.4', 'ชุดที่ 3: บริหารภายใน คู่มือ ม.77 & หมวด 12 (หมวด 4–12)', 'ห่วงโซ่ที่ 4: วินัย ประมวลจริยธรรม นโยบาย No Gift Policy และระบบจัดการเรื่องร้องเรียนคู่ขนาน', 'พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 มาตรา 47 ประกอบมาตรา 25(4)(ง) และมาตรา 50(2)', 'ระเบียบวินัยฯ พ.ศ. 2564 (DOC-0068) + ระเบียบประมวลจริยธรรม พ.ศ. 2564 (DOC-0087) + ข้อพึงปฏิบัติ Do & Don''t พ.ศ. 2567 (DOC-0088) + ประกาศ No Gift Policy พ.ศ. 2569 TH/EN (DOC-0089, 0090) + ประกาศช่องทางและแนวทางเรื่องร้องเรียน (DOC-0091, 0093)', 'คู่มือการดำเนินการทางวินัย สกสว. พ.ศ. 2568 (DOC-0096, 111 หน้า แบบ วน.1–วน.8) เชื่อม พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539 และ พ.ร.บ.มาตรฐานทางจริยธรรม พ.ศ. 2562', 'รับเรื่องร้องเรียนผ่าน 6 ช่องทาง -> แยกผู้มีอำนาจสั่งการ: (ก) ร้องเรียนผู้บริหาร/พนักงาน เสนอ ''ผู้อำนวยการ สกสว.'' (ข) ร้องเรียนกรรมการ/ผอ.สกสว. เสนอ ''อนก.สกสว.'' -> ดำเนินการตรวจสอบข้อเท็จจริง/สืบสวน/สอบสวนตามคู่มือวินัย พ.ศ. 2568 (แบบ วน.1–8) หรือตั้งกรรมการสอบสวนจริยธรรมไม่น้อยกว่า 3 คน (ผู้ถูกลงโทษปลดออกถูกตัดสิทธิเงินสมทบกองทุนสำรองเลี้ยงชีพตาม DOC-0076 ข้อ 7)', 'Cluster B1, B2 (F5 ฝ่ายกฎหมาย & ฝ่ายทรัพยากรบุคคล)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-4.5', 'ชุดที่ 3: บริหารภายใน คู่มือ ม.77 & หมวด 12 (หมวด 4–12)', 'ห่วงโซ่ที่ 5: การแยกบริหารการเงินสำนักงาน (ม.45) ออกจากเงินกองทุน ววน. (ม.54) และเพดานเบิกจ่าย', 'พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 มาตรา 45, 47 ประกอบมาตรา 25(4)(ฉ), 51 และมาตรา 54–62', 'ข้อบังคับการเงิน การบัญชีและทรัพย์สิน พ.ศ. 2563 (DOC-0079) + ระเบียบรับ-จ่าย-เก็บรักษาเงิน พ.ศ. 2563 (DOC-0080) + ระเบียบค่าใช้จ่ายเดินทาง พ.ศ. 2563 (DOC-0083) + ระเบียบค่าตอบแทน/เบี้ยประชุม พ.ศ. 2564 (DOC-0084) + ค่าสื่อสาร (DOC-0085) + ค่าที่จอดรถ (DOC-0081) + ค่าเดินทางผู้บริหารยืมตัว (DOC-0086)', 'คู่มือการปฏิบัติงานและระเบียบปฏิบัติด้านการเงิน มิ.ย. 2568 (DOC-0098, 45 หน้า) เชื่อม พ.ร.บ.วินัยการเงินการคลังของรัฐ พ.ศ. 2561 (หมวด 12: DOC-0103)', 'แยกบัญชีธนาคารชื่อ ''สกสว.'' (งบบริหารสำนักงาน ม.45) ออกจากบัญชี ''กองทุนส่งเสริม ววน.'' (DOC-0005) โดยนำเงินฝากภายในวันที่รับหรือวันทำการถัดไป -> คุมเพดานเบิกจ่ายชัดเจน: เบี้ยประชุมผู้ทรงคุณวุฒิ ประธาน 3,125 บาท/กรรมการ 2,500 บาท, วิทยากร <=3,000 บาท/ชม., กลั่นกรอง <=2,000 บาท/โครงการ (<=20,000 บาท/รอบ), ค่าสื่อสาร WFH >=10 วัน เบิกได้ <=500 บาท/เดือน (ยื่นใน 30 วัน)', 'Cluster B3, B4 (F5 ฝ่ายการเงิน & ฝ่ายบัญชี - 18 ภารกิจ)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-4.6', 'ชุดที่ 3: บริหารภายใน คู่มือ ม.77 & หมวด 12 (หมวด 4–12)', 'ห่วงโซ่ที่ 6: การมอบอำนาจจัดซื้อจัดจ้าง (วงเงิน 500,000 บาท) และการบริหารโครงการวิจัยเพื่อพัฒนาองค์กร (ORG)', 'พ.ร.บ.สภานโยบายฯ พ.ศ. 2562 มาตรา 43, 50(1)–(2) ประกอบ พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 มาตรา 9', 'คำสั่ง สกสว. ที่ พด.70/2564 เรื่อง มอบอำนาจจัดซื้อจัดจ้างฯ (DOC-0094) + คำสั่งที่ พด.71/2564 เรื่อง แต่งตั้งเจ้าหน้าที่พัสดุ (DOC-0095)', 'คู่มือบริหารโครงการ ORG (DOC-0097, 50 หน้า) + คู่มือการเงิน (DOC-0098) เชื่อม พ.ร.บ.การจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 (หมวด 12: DOC-0104) และระเบียบกระทรวงการคลังฯ พ.ศ. 2560', 'แยกสายอนุมัติพัสดุวงเงินไม่เกิน 500,000 บาทตามแหล่งเงิน: (1) งบสำนักงาน อนุมัติโดยผู้บริหารที่กำกับ F5 (2) งบกองทุน ววน. อนุมัติโดยผู้บริหารที่กำกับ F2 และตั้งผู้ปฏิบัติงานทั่วไปเป็นเจ้าหน้าที่พัสดุวงเงินไม่เกิน 10,000 บาท; ส่วนงานวิจัยเพื่อพัฒนาการปฏิบัติงานของ สกสว. เอง ใช้กลไกทุน ORG ตามมาตรา 9 แห่ง พ.ร.บ.ส่งเสริมฯ (ยกเว้นไม่อยู่ภายใต้ พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ ตาม ม.4(1))', 'Cluster B3, B1, A5 (F5 ฝ่ายพัสดุ / แผนงบสำนักงาน & F2)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-4.7', 'ชุดที่ 3: บริหารภายใน คู่มือ ม.77 & หมวด 12 (หมวด 4–12)', 'ห่วงโซ่ที่ 7: มาตรฐานกระบวนงานจัดสรรงบประมาณกองทุน ววน. (SOP ปี T ถึง T+2) และคู่มืองบงานมูลฐาน (FF Multi-year)', 'พ.ร.บ.สภานโยบายฯ มาตรา 11(2), 12(2), 41(2)–(7), 44(4)–(7), 57–58 และ พ.ร.บ.การส่งเสริม ววน. มาตรา 16–18 (รวมฉบับที่ 2 พ.ศ. 2568)', 'ระเบียบบริหารกองทุนฯ พ.ศ. 2562 (DOC-0003) + ประกาศ กสว. คำของบประมาณ FF/SF/ST ปี 2566–2569 (DOC-0006 ถึง 0020)', 'SOP การจัดสรรงบประมาณกองทุน ววน. ก.ย. 2569 (DOC-0101, 13 หน้า) + คู่มือจัดทำคำขอและบริหารงบประมาณ FF (DOC-0099, 180 หน้า) เชื่อม พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: DOC-0102)', 'ขับเคลื่อนวงจรจัดสรรงบประมาณล่วงหน้า 2 ปี (T ถึง T+2): จัดทำกรอบวงเงิน ก.ค.–ส.ค.(T) -> เปิดรับคำขอผ่าน NRIIS (FF/SF) และ STARS (ST) 45 วัน -> กลั่นกรอง 20 วัน -> เสนอ กสว. และ คกก.ม.12(2) ธ.ค.–ม.ค.(T+1) -> แจ้ง Pre-ceiling เม.ย.(T+1) ปรับคำชี้แจงใน 15 วัน -> ชี้แจง กมธ. มิ.ย.–ส.ค.(T+1) -> จัดทำคำรับรองการปฏิบัติตามเงื่อนไข (รวมโครงการ Multi-year Promised Grant ปี 2570)', 'Cluster A2 (F2 สำนักกลยุทธ์งบประมาณฯ - 19 ภารกิจ) & Cluster A1 (F1)');
INSERT INTO legal_chains_24 VALUES ('CHAIN-4.8', 'ชุดที่ 3: บริหารภายใน คู่มือ ม.77 & หมวด 12 (หมวด 4–12)', 'ห่วงโซ่ที่ 8: การประเมินผลสัมฤทธิ์ของกฎหมายตามรัฐธรรมนูญ มาตรา 77 และการปิดช่องว่างทั้ง 8 มาตรการ (Sec. 77 Feedback Loop)', 'รัฐธรรมนูญ มาตรา 77 + พ.ร.บ.สภานโยบายฯ มาตรา 41(13)–(14), 44(8),(12),(14), 64–65 + พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 และ พ.ร.บ.ส่งเสริมการใช้ประโยชน์ฯ พ.ศ. 2564', 'เชื่อมโยงกฎหมายลำดับรองทั้ง 94 ฉบับในหมวดที่ 1 ถึงหมวดที่ 8', 'รายงานวิจัยฉบับสมบูรณ์ ประเมินผลสัมฤทธิ์ของ พ.ร.บ.การส่งเสริม ววน. พ.ศ. 2562 (DOC-0100, สัญญา ORG68F5006, 645 หน้า) เชื่อม พ.ร.บ.หลักเกณฑ์การจัดทำร่างกฎหมายและการประเมินผลสัมฤทธิ์ของกฎหมาย พ.ศ. 2562', 'สังเคราะห์ผลการประเมินผลสัมฤทธิ์ 8 มาตรการหลังบังคับใช้ครบ 5 ปี (ร่วมกับการรับฟังความเห็นและแบบจำลองเศรษฐศาสตร์ GII/WCR) เพื่อใช้เป็นฐานข้อมูลเชิงประจักษ์ในการปรับปรุงกฎหมายลำดับรอง การเชื่อมโยงฐานข้อมูล NRIIS การปลดล็อกคำรับรอง Multi-year การยกระดับบุคลากรวิจัย และการขับเคลื่อนการใช้ประโยชน์ผลงานวิจัย', 'Cluster A5 (F1 ฝ่ายติดตามและประเมินผล + IU - 10 ภารกิจ) & ทุกสำนัก');
